INSERT INTO Lessons (id, chapter_id, lesson_name, theory_cards, sort_order) VALUES (339, 33, 'Bài 3. Hai tam giác bằng nhau', '[{"id":"card-1","body":"Ad Tag - PC_oustream2026_loigiaihay.com - ZMEDIA\\nHai tam giác bằng nhau\\nHai tam giác ABC và A’B’C’ bằng nhau nếu chúng có các cạnh tương ứng bằng nhau và các góc tương ứng bằng nhau, tức là:\\nAB = A’B’ ; AC = A’C’ ; BC = B’C’ và \\\\(\\\\widehat A = \\\\widehat {A\'};\\\\widehat B = \\\\widehat {B\'};\\\\widehat C = \\\\widehat {C\'}\\\\)\\nTa viết: \\\\(\\\\Delta ABC = \\\\Delta A\'B\'C\'\\\\)\\nNếu 2 tam giác bằng nhau, ta suy ra tất cả các cạnh, các góc tương ứng bằng nhau.\\nBình luận\\nChia sẻ\\nChia sẻ\\nBình chọn:\\n3.7\\ntrên\\n7\\nphiếu","title":"Hai tam giác bằng nhau","images":[{"id":"image-1","url":"https://img.loigiaihay.com/picture/2022/0930/capture_35.PNG","alt_text":"Hình minh họa lý thuyết","public_id":null,"width_percent":100,"storage_provider":""},{"id":"image-2","url":"https://img.loigiaihay.com/picture/2022/0517/dinh-li-pytagoras-21-cv.png","alt_text":"Hình minh họa lý thuyết","public_id":null,"width_percent":100,"storage_provider":""}],"example":"","formula":"","formulas":[]}]', 3);
INSERT INTO Lessons (id, chapter_id, lesson_name, theory_cards, sort_order) VALUES (340, 33, 'Bài 4. Trường hợp bằng nhau thứ nhất của tam giác: cạnh - cạnh - cạnh', '[{"id":"card-1","body":"Ad Tag - PC_oustream2026_loigiaihay.com - ZMEDIA\\nTrường hợp bằng nhau thứ nhất của tam giác: cạnh – cạnh – cạnh (c.c.c)\\nNếu 3 cạnh của tam giác này bằng ba cạnh của tam giác kia thì hai tam giác đó bằng nhau.\\nVí dụ:\\nXét \\\\(\\\\Delta ABC\\\\) và \\\\(\\\\Delta MNP\\\\) có:\\n\\\\(\\\\begin{array}{l}AB = MN\\\\\\\\BC = NP\\\\\\\\AC = MP\\\\end{array}\\\\)\\nVậy\\\\(\\\\Delta ABC\\\\) =\\\\(\\\\Delta MNP\\\\)(c.c.c)\\nBình luận\\nChia sẻ\\nChia sẻ\\nBình chọn:\\n4.4\\ntrên\\n8\\nphiếu","title":"Trường hợp bằng nhau thứ nhất của tam giác: cạnh – cạnh – cạnh (c.c.c)","images":[{"id":"image-1","url":"https://img.loigiaihay.com/picture/2022/0930/capture_37.PNG","alt_text":"Hình minh họa lý thuyết","public_id":null,"width_percent":100,"storage_provider":""},{"id":"image-2","url":"https://img.loigiaihay.com/picture/2022/0517/dinh-li-pytagoras-21-cv.png","alt_text":"Hình minh họa lý thuyết","public_id":null,"width_percent":100,"storage_provider":""}],"example":"","formula":"","formulas":[]}]', 4);
INSERT INTO Lessons (id, chapter_id, lesson_name, theory_cards, sort_order) VALUES (341, 33, 'Bài 5. Trường hợp bằng nhau thứ hai của tam giác: cạnh - góc - cạnh', '[{"id":"card-1","body":"Ad Tag - PC_oustream2026_loigiaihay.com - ZMEDIA\\nTrường hợp bằng nhau thứ hai của tam giác: cạnh – góc – cạnh (c.g.c)\\nNếu 2 cạnh và góc xen giữa của tam giác này bằng 2 cạnh và góc xen giữa của tam giác kia thì hai tam giác đó bằng nhau.\\nVí dụ:\\nXét 2 tam giác ABC và MNP có:\\nAB=MN\\n\\\\(\\\\widehat {BAC} = \\\\widehat {NMP}\\\\)\\nAC=MP\\nVậy \\\\(\\\\Delta ABC = \\\\Delta MNP\\\\)(c.g.c)\\nBình luận\\nChia sẻ\\nChia sẻ\\nBình chọn:\\n3.8\\ntrên\\n11\\nphiếu","title":"Trường hợp bằng nhau thứ hai của tam giác: cạnh – góc – cạnh (c.g.c)","images":[{"id":"image-1","url":"https://img.loigiaihay.com/picture/2022/0930/capture_33.PNG","alt_text":"Hình minh họa lý thuyết","public_id":null,"width_percent":100,"storage_provider":""},{"id":"image-2","url":"https://img.loigiaihay.com/picture/2022/0517/dinh-li-pytagoras-21-cv_1.png","alt_text":"Hình minh họa lý thuyết","public_id":null,"width_percent":100,"storage_provider":""}],"example":"","formula":"","formulas":[]}]', 5);
INSERT INTO Lessons (id, chapter_id, lesson_name, theory_cards, sort_order) VALUES (342, 33, 'Bài 6. Trường hợp bằng nhau thứ ba của tam giác: góc- cạnh - góc', '[{"id":"card-1","body":"Ad Tag - PC_oustream2026_loigiaihay.com - ZMEDIA\\nTrường hợp bằng nhau thứ ba của tam giác: góc- cạnh - góc (g.c.g)\\nNếu 1 cạnh và 2 góc kề của tam giác này bằng 1 cạnh và 2 góc kề của tam giác kia thì hai tam giác đó bằng nhau.\\nVí dụ:\\nXét 2 tam giác ABC và MNP có:\\n\\\\(\\\\begin{array}{l}\\\\widehat B = \\\\widehat N\\\\\\\\BC = NP\\\\\\\\\\\\widehat C = \\\\widehat P\\\\end{array}\\\\)\\nVậy \\\\(\\\\Delta ABC = \\\\Delta MNP\\\\)(g.c.g)\\nBình luận\\nChia sẻ\\nChia sẻ\\nBình chọn:\\n4.5\\ntrên\\n6\\nphiếu","title":"Trường hợp bằng nhau thứ ba của tam giác: cạnh – góc – cạnh (g.c.g)","images":[{"id":"image-1","url":"https://img.loigiaihay.com/picture/2022/0930/capture_34.PNG","alt_text":"Hình minh họa lý thuyết","public_id":null,"width_percent":100,"storage_provider":""},{"id":"image-2","url":"https://img.loigiaihay.com/picture/2022/0517/dinh-li-pytagoras-21-cv_1.png","alt_text":"Hình minh họa lý thuyết","public_id":null,"width_percent":100,"storage_provider":""}],"example":"","formula":"","formulas":[]}]', 6);
