INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4232, 275, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Bảng dưới đây cho biết nhiệt độ ở một số thành phố thuộc vùng xứ lạnh trong một ngày mùa đông: Thành phố Nhiệt độ Moscow – $9^\\\\circ$C Saint Peterburg – $8^\\\\circ$C Vladivostok – $12^\\\\circ$C Hãy cho biết nhiệt độ của thành phố Saint Peterburg?","images":[]}', '[{"key":"A","text":"– $8^\\\\circ$C"},{"key":"B","text":"– $9^\\\\circ$C"},{"key":"C","text":"– $10^\\\\circ$C"},{"key":"D","text":"– $12^\\\\circ$C"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Bảng dưới đây cho biết nhiệt độ ở một số thành phố thuộc vùng xứ lạnh trong một ngày mùa đông: Thành phố Nhiệt độ Moscow – $9^\\\\circ$C Saint Peterburg – $8^\\\\circ$C Vladivostok – $12^\\\\circ$C Hãy cho biết nhiệt độ của thành phố Saint Peterburg?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Theo bảng đã cho, ta thấy nhiệt độ của thành phố Saint Peterburg trong một ngày mùa đông là – $8^\\\\circ$C.\\nKết luận: Đáp án đúng là A (– $8^\\\\circ$C).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4233, 275, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Theo bảng ở Câu 4 , hãy cho biết nhiệt độ của thành phố Moscow trong một ngày mùa đông là:","images":[]}', '[{"key":"A","text":"âm tám độ C"},{"key":"B","text":"âm mười độ C"},{"key":"C","text":"âm chín độ C"},{"key":"D","text":"chín độ C"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Theo bảng ở Câu 4 , hãy cho biết nhiệt độ của thành phố Moscow trong một ngày mùa đông là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Theo bảng đã cho ở Câu 4, ta thấy nhiệt độ của thành phố Moscow trong một ngày mùa đông là – $9^\\\\circ$C, đọc là âm chín độ C.\\nKết luận: Đáp án đúng là C (âm chín độ C).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4234, 275, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Chọn khẳng định đúng trong các khẳng định sau?","images":[]}', '[{"key":"A","text":"Số 0 là số nguyên âm"},{"key":"B","text":"Số 1 là số nguyên âm"},{"key":"C","text":"Số – 7 là số nguyên âm"},{"key":"D","text":"Số 0 không là số tự nhiên"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn khẳng định đúng trong các khẳng định sau?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có số 0 là số tự nhiên và không phải số nguyên âm nên A và D sai.\\nSố 1 là số tự nhiên và không phải số nguyên âm nên B sai.\\nSố – 7 là số nguyên âm nên C đúng.\\nKết luận: Đáp án đúng là C (Số – 7 là số nguyên âm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4235, 275, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Ông Hải kinh doanh bị lỗ 700 000 000 đồng, số nguyên âm biểu thị số tiền bị lỗ của ông Hải là:","images":[]}', '[{"key":"A","text":"– 700 đồng"},{"key":"B","text":"– 700 000 đồng"},{"key":"C","text":"– 700 000 000 đồng"},{"key":"D","text":"700 000 000 đồng"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Ông Hải kinh doanh bị lỗ 700 000 000 đồng, số nguyên âm biểu thị số tiền bị lỗ của ông Hải là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ông Hải kinh doanh bị lỗ 700 000 000 đồng, số nguyên âm biểu thị số tiền bị lỗ của ông Hải là – 700 000 000 đồng.\\nKết luận: Đáp án đúng là C (– 700 000 000 đồng).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4236, 275, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Nhà toán học Euclid sống vào thế kỉ 3 TCN, số nguyên âm biểu thị thế kỉ đó là:","images":[]}', '[{"key":"A","text":"3"},{"key":"B","text":"– 3"},{"key":"C","text":"0"},{"key":"D","text":"5"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Nhà toán học Euclid sống vào thế kỉ 3 TCN, số nguyên âm biểu thị thế kỉ đó là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Nhà toán học Euclid sống vào thế kỉ 3 TCN, số nguyên âm biểu thị thế kỉ đó là – 3.\\nKết luận: Đáp án đúng là B (– 3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4237, 275, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Số phần tử của tập hợp số nguyên âm là","images":[]}', '[{"key":"A","text":"5 phần tử."},{"key":"B","text":"10 phần tử."},{"key":"C","text":"100 phần tử."},{"key":"D","text":"vô số phần tử."}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Số phần tử của tập hợp số nguyên âm là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải: Các số – 1, – 2, – 3, … là các số nguyên âm.\\nDo đó tập hợp các số nguyên âm có vô số phần tử.\\nKết luận: Đáp án đúng là D (vô số phần tử.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4238, 275, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Dãy nào dưới đây gồm hai số nguyên âm và một số tự nhiên?","images":[]}', '[{"key":"A","text":"– 18, – 45, 23"},{"key":"B","text":"36, 48, – 72"},{"key":"C","text":"34, – 45, 0"},{"key":"D","text":"0, 121, – 60"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Dãy nào dưới đây gồm hai số nguyên âm và một số tự nhiên?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Quan sát các đáp án ta thấy ở , các số – 18, – 45 là số nguyên âm và 23 là số tự nhiên, nên dãy này gồm 2 số nguyên âm và một số tự nhiên.\\nKết luận: Đáp án đúng là A (– 18, – 45, 23).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4239, 275, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Độ sâu trung bình của toàn bộ đại dương là 3 500 m dưới mực nước biển. Số nguyên âm biểu thị độ sâu đó là:","images":[]}', '[{"key":"A","text":"3 500 m"},{"key":"B","text":"– 3 000 m"},{"key":"C","text":"– 3 500 m"},{"key":"D","text":"– 500 m"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Độ sâu trung bình của toàn bộ đại dương là 3 500 m dưới mực nước biển. Số nguyên âm biểu thị độ sâu đó là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Độ sâu trung bình của toàn bộ đại dương là 3 500 m dưới mực nước biển.\\nSố nguyên âm biểu thị độ sâu đó là – 3 500 m.\\nKết luận: Đáp án đúng là C (– 3 500 m).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4240, 275, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Nhà nước Âu Lạc được thành lập vào khoảng năm 257 TCN. Số nguyên âm biểu thị thời gian đó là:","images":[]}', '[{"key":"A","text":"257"},{"key":"B","text":"– 257"},{"key":"C","text":"– 275"},{"key":"D","text":"– 725"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Nhà nước Âu Lạc được thành lập vào khoảng năm 257 TCN. Số nguyên âm biểu thị thời gian đó là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Nhà nước Âu Lạc được thành lập vào khoảng năm 257 TCN.\\nSố nguyên âm biểu thị thời gian đó là – 257.\\nKết luận: Đáp án đúng là B (– 257).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4241, 275, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Nếu 50 000 đồng biểu diễn số tiền có là 50 000 đồng thì – 100 000 đồng biểu diễn số tiền:","images":[]}', '[{"key":"A","text":"có 100 000 đồng"},{"key":"B","text":"có 150 000 đồng"},{"key":"C","text":"nợ 100 000 đồng"},{"key":"D","text":"nợ 150 000 đồng"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Nếu 50 000 đồng biểu diễn số tiền có là 50 000 đồng thì – 100 000 đồng biểu diễn số tiền:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Nếu 50 000 đồng biểu diễn số tiền có là 50 000 đồng thì – 100 000 đồng biểu diễn số tiền nợ 100 000 đồng.\\nKết luận: Đáp án đúng là C (nợ 100 000 đồng).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4242, 275, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Nếu $20^\\\\circ$C biểu diễn 20 độ trên $0^\\\\circ$C thì – $5^\\\\circ$C biểu diễn:","images":[]}', '[{"key":"A","text":"– $5^\\\\circ$C trên $0^\\\\circ$C"},{"key":"B","text":"– $5^\\\\circ$C dưới $0^\\\\circ$C"},{"key":"C","text":"$5^\\\\circ$C trên $0^\\\\circ$C"},{"key":"D","text":"$5^\\\\circ$C dưới $0^\\\\circ$C"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Nếu $20^\\\\circ$C biểu diễn 20 độ trên $0^\\\\circ$C thì – $5^\\\\circ$C biểu diễn:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải: Nếu $20^\\\\circ$C biểu diễn 20 độ trên $0^\\\\circ$C thì – $5^\\\\circ$C biểu diễn $5^\\\\circ$C dưới $0^\\\\circ$C.\\nKết luận: Đáp án đúng là D ($5^\\\\circ$C dưới $0^\\\\circ$C).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4243, 275, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Cho tập hợp A = {– 5; – 8; 0; 14; – 70; 65; – 450}. Số phần tử là số nguyên âm có trong tập hợp A là:","images":[]}', '[{"key":"A","text":"7"},{"key":"B","text":"6"},{"key":"C","text":"5"},{"key":"D","text":"4"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho tập hợp A = {– 5; – 8; 0; 14; – 70; 65; – 450}. Số phần tử là số nguyên âm có trong tập hợp A là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải a) Đúng.\\nQuan sát bảng thống kê, nhận thấy lúc 6 giờ có nhiệt độ là −$10^\\\\circ$C.\\nb) Sai.\\nQuan sát bảng thống kê, nhận thấy lúc 14 giờ có nhiệt độ là $2^\\\\circ$C.\\nc) Đúng.\\nCác thời điểm có nhiệt độ âm là 2 giờ, 6 giờ, 10 giờ và 22 giờ.\\nd) Sai.\\nCác thời điểm trong ngày có nhiệt độ không âm là 14 giờ và 18 giờ.\\nKết luận: Đáp án đúng là D (4).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4244, 276, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tập hợp các số nguyên kí hiệu là:","images":[]}', '[{"key":"A","text":"N"},{"key":"B","text":"N *"},{"key":"C","text":"Z"},{"key":"D","text":"Z *"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tập hợp các số nguyên kí hiệu là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Theo phần lý thuyết, ta đã biết tập hợp các số nguyên kí hiệu là.\\nKết luận: Đáp án đúng là C (Z).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4245, 276, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Chọn câu đúng.","images":[]}', '[{"key":"A","text":"Số 0 không phải là số nguyên"},{"key":"B","text":"Số 0 là số nguyên âm"},{"key":"C","text":"Số 0 là số nguyên dương"},{"key":"D","text":"Số 0 là số nguyên"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu đúng.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Theo lý thuyết: Số 0 là số nguyên và số 0 không phải số nguyên âm cũng không phải số nguyên dương.\\nVậy , B, C sai và D đúng.\\nKết luận: Đáp án đúng là A (Số 0 không phải là số nguyên).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4246, 276, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Phát biểu nào sau đây đúng?","images":[]}', '[{"key":"A","text":"– 10 ∈ N"},{"key":"B","text":"– 10 ∈ Z"},{"key":"C","text":"– 10 ∉ Z"},{"key":"D","text":"– 10 ∈ N *"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Phát biểu nào sau đây đúng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: – 10 là số nguyên và không phải là số tự nhiên nên – 10 ∈ Z, – 10 ∉ N, – 10 ∉ N *.\\nKết luận: Đáp án đúng là B (– 10 ∈ Z).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4247, 276, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Chọn câu sai?","images":[]}', '[{"key":"A","text":"Z = {0; 1; 2; 3; ….}"},{"key":"B","text":"Z = {….; - 3; - 2; - 1; 0}"},{"key":"C","text":"Z = {...; -2; -1; 0; 1; 2; ...}"},{"key":"D","text":"Z = {...; -2; -1; 1; 2; ...}"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu sai?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: tập hợp các số nguyên Z = {. . .; -2; -1; 0; 1; 2; . . .} nên C đúng và A, B, D sai.\\nKết luận: Đáp án đúng là D (Z = {...; -2; -1; 1; 2; ...}).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4248, 276, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Chọn câu đúng:","images":[]}', '[{"key":"A","text":"6 ∈ N"},{"key":"B","text":"9 ∉ N"},{"key":"C","text":"– 9 ∈ N"},{"key":"D","text":"-19 ∈ Z"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có:\\n+ Vì – 6 là số nguyên âm, không phải số tự nhiên nên – 6 ∉ N, do đó A sai.\\n+ Vì 9 là số tự nhiên nên 9 ∈ N , do đó B sai.\\n+ Vì – 9 là số nguyên âm, không phải số tự nhiên nên – 9 ∉ N , do đó C sai.\\n+ Vì -19 là số nguyên âm nên -19 ∈ Z , do đó D đúng.\\nKết luận: Đáp án đúng là D (-19 ∈ Z).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4249, 276, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Điểm cách -1 ba đơn vị theo chiều âm là:","images":[]}', '[{"key":"A","text":"3"},{"key":"B","text":"-3"},{"key":"C","text":"-4"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Điểm cách -1 ba đơn vị theo chiều âm là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Điểm cách -1 ba đơn vị theo chiều âm là điểm nằm bên trái -1 và cách điểm -1 ba đơn vị.\\nĐiểm nằm bên trái điểm -1 và cách điểm -1 ba đơn vị là điểm -4 Nên điểm cách -1 ba đơn vị theo chiều âm là -4.\\nKết luận: Đáp án đúng là C (-4).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Tập hợp các số nguyên (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/61a69b58acf97d14f3b7393d1dd230c27406b472.jpeg","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Tập hợp các số nguyên (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-tap-hop-cac-so-nguyen-66720.jpeg"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4250, 276, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Điền vào chỗ trống trong câu sau: Nếu – 2 điốp biểu diễn độ cận thị thì + 2 điốp biểu diễn …","images":[]}', '[{"key":"A","text":"độ cận thị"},{"key":"B","text":"độ viễn thị"},{"key":"C","text":"độ loạn thị"},{"key":"D","text":"độ bình thường"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Điền vào chỗ trống trong câu sau: Nếu – 2 điốp biểu diễn độ cận thị thì + 2 điốp biểu diễn …\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Vì – 2 và\\n+ 2 là hai số đối nhau, mà – 2 điốp biểu thị độ cận thị thì\\n+ 2 điốp biểu diễn độ viễn thị Chọn\\nKết luận: Đáp án đúng là B (độ viễn thị).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4251, 276, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Trong các khẳng định sau, khẳng định nào đúng?","images":[]}', '[{"key":"A","text":"Nếu + 50 000 đồng biểu diễn số tiền có 50 000 đồng, thì – 50 000 đồng biểu diễn số tiền cho vay là 50 000 đồng."},{"key":"B","text":"Số 0 là số nguyên dương."},{"key":"C","text":"Số đối của số 0 là số 0."},{"key":"D","text":"Số 0 là số nguyên âm."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các khẳng định sau, khẳng định nào đúng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Nếu\\n+ 50 000 đồng biểu diễn số tiền có 50 000 đồng, thì – 50 000 đồng biểu diễn số tiền nợ là 50 000 đồng.\\nVậy A sai Số 0 không là số nguyên âm, không là số nguyên dương.\\nDo đó, B và D sai Số đối của số 0 là số 0.\\nDo đó, C đúng Chọn\\nKết luận: Đáp án đúng là C (Số đối của số 0 là số 0.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4252, 276, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Số đối của 8 là:","images":[]}', '[{"key":"A","text":"– 8"},{"key":"B","text":"0"},{"key":"C","text":"8"},{"key":"D","text":"16"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Số đối của 8 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có số đối của 8 là – 8.\\nKết luận: Đáp án đúng là A (– 8).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4253, 276, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Cho tập hợp A = {-2; 0; 3; 6} . Tập hợp B gồm các phần tử là số đối của các phần tử trong tập hợp A là:","images":[]}', '[{"key":"A","text":"B = {-2; 0; -3; -6}"},{"key":"B","text":"B = {2; 0; 3; 6}"},{"key":"C","text":"B = {-6; -3; 0; 2}"},{"key":"D","text":"B = {-2; 0; 3; 6}"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho tập hợp A = {-2; 0; 3; 6} . Tập hợp B gồm các phần tử là số đối của các phần tử trong tập hợp A là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: số đối của – 2 là 2, số đối của 0 là 0, số đối của 3 là – 3 , số đối của 6 là – 6.\\nDo đó, tập hợp B là: B = {-6; -3; 0; 2}.\\nKết luận: Đáp án đúng là C (B = {-6; -3; 0; 2}).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4254, 276, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Trong các khẳng định sau, khẳng định nào sai?","images":[]}', '[{"key":"A","text":"Nếu + 10 000 đồng biểu diễn số tiền có 10 000 đồng, thì – 10 000 đồng biểu diễn số tiền nợ 10 000 đồng."},{"key":"B","text":"Nếu -$15^\\\\circ$C biểu diễn 15 độ dưới $0^\\\\circ$C thì +$15^\\\\circ$C biểu diễn 15 độ trên $0^\\\\circ$C"},{"key":"C","text":"Nếu +5 bước biểu diễn 5 bước về phía trước thì – 5 bước biểu diễn 5 bước về phía sau."},{"key":"D","text":"Nếu – 27m biểu diễn độ sâu là 27m dưới mực nước biển thì + 27m biểu diễn độ cao 27m tính từ mặt đất."}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các khẳng định sau, khẳng định nào sai?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: Nếu – 27m biểu diễn độ sâu là 27m dưới mực nước biển thì\\n+ 27m biểu diễn độ cao 27m trên mực nước biển.\\nVậy sai.\\nKết luận: Đáp án đúng là D (Nếu – 27m biểu diễn độ sâu là 27m dưới mực nước biển thì + 27m biểu diễn độ cao 27m tính từ mặt đất.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4255, 276, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho các số: 8; 15; – 25; – 56; 0. Sắp xếp các số đã cho theo thứ tự tăng dần ta được:","images":[]}', '[{"key":"A","text":"8; 15; – 25; – 56; 0"},{"key":"B","text":"0; 8; 15; – 25; – 56"},{"key":"C","text":"– 56; – 25; 15; 8; 0"},{"key":"D","text":"– 56 ; – 25; 0; 8; 15"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho các số: 8; 15; – 25; – 56; 0. Sắp xếp các số đã cho theo thứ tự tăng dần ta được:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải\\n+ Ta có: 8 và 15 là các số nguyên dương nên 0 < 8 < 15 (1)\\n+ Lại có các số – 25;\\n– 56 là số nguyên âm nên – 25 < 0;\\n– 56 < 0 Ta so sánh hai số – 25 và – 56 bằng cách bỏ dấu trừ ở trước các số đó, ta được 25 và 56.\\nDo 25 < 56 nên – 25 > – 56.\\nDo đó: – 56 < – 25 < 0 (2) Từ (1) và (2) ta suy ra – 56 < – 25 < 0 < 8 < 15.\\nVậy xếp các số đã cho theo thứ tự tăng dần ta được: – 56;\\n– 25;\\n0;\\n8;\\n15.\\nKết luận: Đáp án đúng là D (– 56 ; – 25; 0; 8; 15).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4256, 276, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Cho E = {− 4; 2; 0; − 1; 7; − 2020}. Viết tập hợp D gồm các phần tử thuộc E và là số nguyên âm.","images":[]}', '[{"key":"A","text":"D = {− 4; 2; − 1}"},{"key":"B","text":"D = {−4 ; − 1; − 2020}"},{"key":"C","text":"D = {− 1; 7; 2020}"},{"key":"D","text":"D = {2; 0; 7}"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho E = {− 4; 2; 0; − 1; 7; − 2020}. Viết tập hợp D gồm các phần tử thuộc E và là số nguyên âm.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có E = {−4; 2; 0; −1; 7; −2020} có các số nguyên âm là − 4;\\n− 1;\\n− 2020.\\nNên tập hợp D = {− 4; − 1; − 2020}.\\nKết luận: Đáp án đúng là B (D = {−4 ; − 1; − 2020}).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4257, 276, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Điểm - 3 cách điểm 4 theo chiều dương bao nhiêu đơn vị?","images":[]}', '[{"key":"A","text":"7"},{"key":"B","text":"2"},{"key":"C","text":"9"},{"key":"D","text":"5"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Điểm - 3 cách điểm 4 theo chiều dương bao nhiêu đơn vị?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Quan sát trục số ta thấy điểm – 3 cách điểm 4 theo chiều dương là 7 khoảng hay chính là 7 đơn vị.\\nKết luận: Đáp án đúng là A (7).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Tập hợp các số nguyên (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/732dbf92add390df006111be16bca15bc468e362.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Tập hợp các số nguyên (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-tap-hop-cac-so-nguyen-66717.png"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4258, 276, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Có bao nhiêu số nguyên nằm giữa – 4 và 5 là:","images":[]}', '[{"key":"A","text":"6"},{"key":"B","text":"5"},{"key":"C","text":"8"},{"key":"D","text":"7"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Có bao nhiêu số nguyên nằm giữa – 4 và 5 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải: Các số nguyên nằm giữa −4 và 5 là: −3;\\n−2;\\n−1;\\n0;\\n1;\\n2;\\n3;\\n4.\\nVậy có 8 số thỏa mãn điều kiện đề bài.\\nKết luận: Đáp án đúng là C (8).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4259, 276, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Trên trục số điểm A cách gốc 5 đơn vị về phía bên trái, điểm B cách điểm A là 4 đơn vị về phía bên phải. Hỏi điểm B cách gốc bao nhiêu đơn vị?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tập hợp các số nguyên (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/145a566372f82667fbc56138019f14105a9c81fe.png","width":"47","height":"175","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-tap-hop-cac-so-nguyen-336901.PNG"}]}', '[{"key":"A","text":"3"},{"key":"B","text":"5"},{"key":"C","text":"2"},{"key":"D","text":"1"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trên trục số điểm A cách gốc 5 đơn vị về phía bên trái, điểm B cách điểm A là 4 đơn vị về phía bên phải. Hỏi điểm B cách gốc bao nhiêu đơn vị?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\na) Đúng.\\nTừ điểm O , di chuyển xuống dưới 2 đơn vị ta được số -2.\\nb) Sai.\\nTừ điểm O , di chuyển lên trên 2 đơn vị ta được điểm 2.\\nVậy điểm 2 cách gốc O 2 đơn vị.\\nc) Sai.\\nKhoảng cách từ gốc O đến điểm 2 và điểm -2 là bằng nhau (cùng bằng 2 đơn vị).\\nd) Đúng.\\nTừ gốc O , khi di chuyển xuống dưới và lên trên cùng một đơn vị thì ta được hai điểm mà khoảng cách từ hai điểm đó đến gốc O bằng nhau.\\nVậy trên trục số, luôn có hai điểm sao cho khoảng cách từ mỗi điểm đó đến gốc O bằng nhau.\\nKết luận: Đáp án đúng là A (3).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Tập hợp các số nguyên (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/ce68c53fa772bd1014958225ca69554b7729dd3d.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Tập hợp các số nguyên (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-tap-hop-cac-so-nguyen-66716.png"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4260, 277, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Kết quả của phép tính 25 + 15 là:","images":[]}', '[{"key":"A","text":"40"},{"key":"B","text":"10"},{"key":"C","text":"50"},{"key":"D","text":"30"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của phép tính 25 + 15 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 25\\n+ 15 = 40 Chọn\\nKết luận: Đáp án đúng là A (40).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4261, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Kết quả của phép tính (– 100) + (– 50) là:","images":[]}', '[{"key":"A","text":"– 50"},{"key":"B","text":"50"},{"key":"C","text":"150"},{"key":"D","text":"– 150"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của phép tính (– 100) + (– 50) là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 100)\\n+ (– 50) = – (100\\n+ 50) = – 150 Chọn\\nKết luận: Đáp án đúng là D (– 150).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4262, 277, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tổng của hai số – 313 và – 211 là:","images":[]}', '[{"key":"A","text":"534."},{"key":"B","text":"524"},{"key":"C","text":"– 524"},{"key":"D","text":"– 534"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tổng của hai số – 313 và – 211 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Tổng của hai số – 313 và – 211 là: (– 313)\\n+ (– 211) = – (313\\n+ 211) = – 524.\\nKết luận: Đáp án đúng là C (– 524).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4263, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tổng của – 161 và – 810 là:","images":[]}', '[{"key":"A","text":"– 971"},{"key":"B","text":"971"},{"key":"C","text":"– 649"},{"key":"D","text":"649"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tổng của – 161 và – 810 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: – 161\\n+ (– 810) = – (161\\n+ 810) = – 971 Chọn\\nKết luận: Đáp án đúng là A (– 971).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4264, 277, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Kết quả của phép tính (– 50) + 30 là:","images":[]}', '[{"key":"A","text":"– 20"},{"key":"B","text":"20"},{"key":"C","text":"– 30"},{"key":"D","text":"80"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của phép tính (– 50) + 30 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 50)\\n+ 30 = – (50 – 30) = – 20 Chọn\\nKết luận: Đáp án đúng là A (– 20).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4265, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Số nguyên nào dưới dây là kết quả của phép tính 52 + (– 122)?","images":[]}', '[{"key":"A","text":"– 70"},{"key":"B","text":"70"},{"key":"C","text":"60"},{"key":"D","text":"– 60"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Số nguyên nào dưới dây là kết quả của phép tính 52 + (– 122)?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 52\\n+ (– 122) = – (122 – 52) = – 70 Chọn\\nKết luận: Đáp án đúng là A (– 70).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4266, 277, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tính (– 909) + 909.","images":[]}', '[{"key":"A","text":"1818"},{"key":"B","text":"1"},{"key":"C","text":"0"},{"key":"D","text":"– 1818"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính (– 909) + 909.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 909)\\n+ 909 = 909 – 909 = 0 Chọn\\nKết luận: Đáp án đúng là C (0).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4267, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Phép cộng các số nguyên có tính chất nào sau đây:","images":[]}', '[{"key":"A","text":"Giao hoán"},{"key":"B","text":"Kết hợp"},{"key":"C","text":"Cộng với số 0"},{"key":"D","text":"Tất cả các đáp án trên"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Phép cộng các số nguyên có tính chất nào sau đây:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Tính chất của phép cộng các số nguyên: giao hoán, kết hợp, cộng với số 0, cộng với số đối.\\nVậy , B, C đúng nên D là hính xác nhất.\\nKết luận: Đáp án đúng là A (Giao hoán).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4268, 277, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Kết quả của phép tính (– 89) + 0 là:","images":[]}', '[{"key":"A","text":"– 89"},{"key":"B","text":"– 90"},{"key":"C","text":"0"},{"key":"D","text":"89"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của phép tính (– 89) + 0 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 89)\\n+ 0 = – 89 (tính chất cộng với số 0).\\nKết luận: Đáp án đúng là A (– 89).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4269, 277, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Tính (– 978) + 978.","images":[]}', '[{"key":"A","text":"0"},{"key":"B","text":"978"},{"key":"C","text":"1956"},{"key":"D","text":"980"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính (– 978) + 978.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có (– 978) và 978 là hai số đối nhau nên (– 978)\\n+ 978 = 0.\\nKết luận: Đáp án đúng là A (0).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4270, 277, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Chọn đáp án đúng?","images":[]}', '[{"key":"A","text":"(– 10) + (– 5) < – 16"},{"key":"B","text":"3 + 5 < – 3"},{"key":"C","text":"(– 8) + (– 7) = (– 7) + (– 8)"},{"key":"D","text":"(– 102) + (– 5) > – 100"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn đáp án đúng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 10)\\n+ (– 5) = – (10\\n+ 5) = – 15 > – 16.\\nsai 3\\n+ 5 = 8 > – 3.\\nsai (– 8)\\n+ (– 7) = (– 7)\\n+ (– 8) (tính chất giao hoán của phép cộng).\\nđúng (– 102)\\n+ (– 5) = – (102\\n+ 5) = – 107 < – 100.\\nsai Chọn\\nKết luận: Đáp án đúng là A ((– 10) + (– 5) < – 16).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4271, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Nhiệt độ hiện tại của phòng đông lạnh là – $2^\\\\circ$C. Nếu nhiệt độ giảm $7^\\\\circ$C, nhiệt độ tại phòng đông lạnh sẽ là bao nhiêu?","images":[]}', '[{"key":"A","text":"$5^\\\\circ$C"},{"key":"B","text":"– $9^\\\\circ$C"},{"key":"C","text":"– $5^\\\\circ$C"},{"key":"D","text":"$9^\\\\circ$C"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Nhiệt độ hiện tại của phòng đông lạnh là – $2^\\\\circ$C. Nếu nhiệt độ giảm $7^\\\\circ$C, nhiệt độ tại phòng đông lạnh sẽ là bao nhiêu?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Nhiệt độ giảm $7^\\\\circ$C nghĩa là tăng – $7^\\\\circ$C nên nhiệt độ tại phòng đông lạnh là: (– 2)\\n+ (– 7) = – (2\\n+ 7) = – $9^\\\\circ$C Chọn\\nKết luận: Đáp án đúng là B (– $9^\\\\circ$C).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4272, 277, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Giá trị của biểu thức a + (– 45) với a = – 25 là:","images":[]}', '[{"key":"A","text":"– 70"},{"key":"B","text":"– 25"},{"key":"C","text":"25"},{"key":"D","text":"70"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị của biểu thức a + (– 45) với a = – 25 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Thay a = – 25 vào biểu thức đã cho ta được: (– 25)\\n+ (– 45) = – (25\\n+ 45) = – 70.\\nKết luận: Đáp án đúng là A (– 70).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4273, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Chọn câu sai:","images":[]}', '[{"key":"A","text":"(– 2) + (– 5) > 0"},{"key":"B","text":"(– 3) + (– 4) = (– 2) + (– 5)"},{"key":"C","text":"(– 6) + (– 1) < – 6"},{"key":"D","text":"(– 1) + 4 = 3"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu sai:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải\\nTa có (– 2)\\n+ (– 5) = – (2\\n+ 5) = – 7 < 0 nên A sai.\\nTa có (– 3)\\n+ (– 4) = – (3\\n+ 4) = – 7 và (– 2)\\n+ (– 5) = – (2\\n+ 5) = – 7.\\nDo đó B đúng.\\nTa có (– 6)\\n+ (– 1) = – (6\\n+ 1) = – 7 < – 6 nên C đúng.\\nTa có (– 1)\\n+ 4 = 4 – 1 = 3 nên D đúng.\\nKết luận: Đáp án đúng là A ((– 2) + (– 5) > 0).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4274, 277, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Tính giá trị của biểu thức x + (– 16) , biết x = – 27:","images":[]}', '[{"key":"A","text":"– 43"},{"key":"B","text":"– 11"},{"key":"C","text":"11"},{"key":"D","text":"43"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính giá trị của biểu thức x + (– 16) , biết x = – 27:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Thay giá trị x = – 27 vào biểu thức đã cho, ta được: x\\n+ (– 16) = – 27\\n+ (– 16) = – (27\\n+ 16) = – 43 Chọn\\nKết luận: Đáp án đúng là A (– 43).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4275, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho các số: – 16; – 7; – 1; 0; 2; 7 . Hai trong các số trên có tổng bằng – 5 là:","images":[]}', '[{"key":"A","text":"– 7 + 2"},{"key":"B","text":"– 7 + (– 1)"},{"key":"C","text":"– 16 + 7"},{"key":"D","text":"– 7 + 0"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho các số: – 16; – 7; – 1; 0; 2; 7 . Hai trong các số trên có tổng bằng – 5 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: – 7\\n+ 2 = – (7 – 2) = – 5 – 7\\n+ (– 1) = – (7\\n+ 1) = – 8 – 16\\n+ 7 = – (16 – 7) = – 9 – 7\\n+ 0 = – 7 Chọn\\nKết luận: Đáp án đúng là A (– 7 + 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4276, 277, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tính (– 551) + (– 400) + (– 449)","images":[]}', '[{"key":"A","text":"– 1 400"},{"key":"B","text":"– 1 450"},{"key":"C","text":"– 1 000"},{"key":"D","text":"– 1 500"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính (– 551) + (– 400) + (– 449)\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 551)\\n+ (– 400)\\n+ (– 449) = – (551\\n+ 400\\n+ 449) = – ((551\\n+ 449)\\n+ 400) = – (1 000\\n+ 400) = – 1 400 Chọn\\nKết luận: Đáp án đúng là A (– 1 400).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4277, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Chọn đáp án đúng nhất:","images":[]}', '[{"key":"A","text":"(– 21) + 4 + (– 55) = 4 + (– 21) + (– 55)"},{"key":"B","text":"(– 21) + 4 + (– 55) = (– 55) + 4 + (– 21)"},{"key":"C","text":"(– 21) + 4 + (– 55) = 4 + (– 55) + (– 21)"},{"key":"D","text":"Cả A, B, C đều đúng."}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn đáp án đúng nhất:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 21)\\n+ 4\\n+ (–55) = 4\\n+ (– 21)\\n+ (– 55) = (– 55)\\n+ 4\\n+ (– 21) = 4\\n+ (– 55)\\n+ (– 21) (tính chất giao hoán của phép cộng) Nên A, B, C đều đúng.\\nKết luận: Đáp án đúng là D (Cả A, B, C đều đúng.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4278, 277, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Trong các khẳng định sau, khẳng định sai là:","images":[]}', '[{"key":"A","text":"Nếu tổng hai số tự nhiên bằng 0 thì cả hai số tự nhiên đó đều bằng 0"},{"key":"B","text":"Nếu tổng hai số nguyên bằng 0 thì cả hai số nguyên đó đều bằng 0"},{"key":"C","text":"Tổng của nhiều số nguyên âm cũng là một số nguyên âm"},{"key":"D","text":"Tổng của nhiều số nguyên dương cũng là một số nguyên dương"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các khẳng định sau, khẳng định sai là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: Hai số nguyên đối nhau có tổng bằng 0.\\nVậy nếu tổng của hai số nguyên bằng 0, ta chưa thể kết luận cả hai số nguyên đó đều bằng 0.\\nsai Chọn\\nKết luận: Đáp án đúng là B (Nếu tổng hai số nguyên bằng 0 thì cả hai số nguyên đó đều bằng 0).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4279, 277, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Kết quả của tổng 161 + [27 + (– 161) + (– 87)] là:","images":[]}', '[{"key":"A","text":"– 60"},{"key":"B","text":"60"},{"key":"C","text":"80"},{"key":"D","text":"– 80"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của tổng 161 + [27 + (– 161) + (– 87)] là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 161\\n+ [27\\n+ (– 161)\\n+ (– 87)] = [161\\n+ (– 161)]\\n+ [27\\n+ (– 87)] = 0\\n+ [– (87 – 27)] = – 60 Chọn.\\nKết luận: Đáp án đúng là A (– 60).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4280, 277, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Viết – 17 thành tổng hai số nguyên khác dấu:","images":[]}', '[{"key":"A","text":"– 2 + (– 15)"},{"key":"B","text":"– 2 + 19"},{"key":"C","text":"2 + (– 19)"},{"key":"D","text":"– 5 + (– 12)"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Viết – 17 thành tổng hai số nguyên khác dấu:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Trong 4 đáp án trên, và C là tổng hai số nguyên khác dấu – 2\\n+ 19 = 19 – 2 = 17 2\\n+ (– 19) = – (19 – 2) = – 17 Chọn\\nKết luận: Đáp án đúng là B (– 2 + 19).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4281, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Một phòng đông lạnh có nhiệt độ là $5^\\\\circ$C. Nhiệt độ của phòng đông lạnh là bao nhiêu nếu nhiệt độ giảm $7^\\\\circ$C ?","images":[]}', '[{"key":"A","text":"$12^\\\\circ$C"},{"key":"B","text":"$2^\\\\circ$C"},{"key":"C","text":"– $2^\\\\circ$C"},{"key":"D","text":"– $12^\\\\circ$C"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Một phòng đông lạnh có nhiệt độ là $5^\\\\circ$C. Nhiệt độ của phòng đông lạnh là bao nhiêu nếu nhiệt độ giảm $7^\\\\circ$C ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Nhiệt độ giảm $7^\\\\circ$C nghĩa là tăng – $7^\\\\circ$C.\\nVậy nhiệt độ của phòng đông lạnh lúc sau là: 5\\n+ (– 7) = – (7 – 5) = – $2^\\\\circ$C Chọn\\nKết luận: Đáp án đúng là C (– $2^\\\\circ$C).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4282, 277, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Thay * bằng chữ số thích hợp để 38 + (– 2*) = 16.","images":[]}', '[{"key":"A","text":"2"},{"key":"B","text":"4"},{"key":"C","text":"6"},{"key":"D","text":"8"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Thay * bằng chữ số thích hợp để 38 + (– 2*) = 16.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 38\\n+ (– 2*) = 16 Hay (38 – 2*) = 16 Mà 3 – 2 = 1, do đó 8 – * = 6 Khi đó: * = 8 – 6 = 2 Thử lại: 38\\n+ (– 22) = 38 – 22 = 16 (đúng).\\nKết luận: Đáp án đúng là A (2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4283, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Giá trị nào của x thỏa mãn x – 589 = (– 335).","images":[]}', '[{"key":"A","text":"x = – 452"},{"key":"B","text":"x = – 254"},{"key":"C","text":"x = 542"},{"key":"D","text":"x = 254"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị nào của x thỏa mãn x – 589 = (– 335).\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: x – 589 = (– 335) x = (– 335)\\n+ 589 x = 589 – 335 x = 254 Vậy x = 254.\\nKết luận: Đáp án đúng là D (x = 254).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4284, 277, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Tìm tổng tất cả các số nguyên x, biết: – 4 < x < 5 ?","images":[]}', '[{"key":"A","text":"1"},{"key":"B","text":"5"},{"key":"C","text":"4"},{"key":"D","text":"3"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tìm tổng tất cả các số nguyên x, biết: – 4 < x < 5 ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải: Các số nguyên thỏa mãn – 4 < x < 5 là: – 3;\\n– 2;\\n– 1;\\n0;\\n1;\\n2;\\n3;\\n4.\\nTa có: (– 3)\\n+ (– 2)\\n+ (– 1)\\n+ 0\\n+ 1\\n+ 2\\n+ 3\\n+ 4 = (– 3\\n+ 3)\\n+ (– 2\\n+ 2)\\n+ (– 1\\n+ 1)\\n+ 0\\n+ 4 = 0\\n+ 0\\n+ 0\\n+ 0\\n+ 4 = 4 Chọn\\nKết luận: Đáp án đúng là C (4).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4285, 277, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tìm x ∈ Z , biết: x + (– 27) = (– 100) + 73 :","images":[]}', '[{"key":"A","text":"x = – 1"},{"key":"B","text":"x = 0"},{"key":"C","text":"x = 1"},{"key":"D","text":"x = 2"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tìm x ∈ Z , biết: x + (– 27) = (– 100) + 73 :\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải a) Sai.\\nLợi nhuận của cửa hàng trong tháng 2 là: − 30\\n+ 50 = 20 (triệu đồng).\\nVậy lợi nhuận của cửa hàng trong tháng 2 là 20 triệu đồng.\\nb) Sai.\\nLợi nhuận trong tháng 3 của cửa hàng là: − 30\\n+ 20 = − 10 (triệu đồng).\\nVậy lợi nhuận của cửa hàng trong tháng 3 là số nguyên âm.\\nc) Đúng.\\nTổng lợi nhuận trong ba tháng đầu năm là: − 30\\n+ 20\\n+ − 10 = − 20 (triệu đồng).\\nVậy tổng lợi nhuận trong ba tháng đầu năm của cửa hàng A nhỏ hơn 30 triệu đồng.\\nd) Sai.\\nVì -20 triệu đồng < 20 triệu đồng nên trong quý I năm 2025, cửa hàng A không đạt được mục tiêu đề ra.\\nKết luận: Đáp án đúng là B (x = 0).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4286, 278, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Kết quả của phép tính 23 – 17 là:","images":[]}', '[{"key":"A","text":"– 40"},{"key":"B","text":"– 6"},{"key":"C","text":"40"},{"key":"D","text":"6"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của phép tính 23 – 17 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 23 – 17 = 6 Chọn\\nKết luận: Đáp án đúng là D (6).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4287, 278, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Khoảng cách giữa hai điểm 5 và – 2 trên trục số là:","images":[]}', '[{"key":"A","text":"– 3"},{"key":"B","text":"3"},{"key":"C","text":"– 7"},{"key":"D","text":"7"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Khoảng cách giữa hai điểm 5 và – 2 trên trục số là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Khoảng cách giữa hai điểm 5 và – 2 trên trục số là: 5 – (– 2) = 5\\n+ 2 = 7.\\nKết luận: Đáp án đúng là D (7).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4288, 278, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tính 125 – 200","images":[]}', '[{"key":"A","text":"– 75"},{"key":"B","text":"75"},{"key":"C","text":"– 85"},{"key":"D","text":"85"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính 125 – 200\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 125 – 200 = 125\\n+ (– 200) = – (200 – 125) = – 75.\\nKết luận: Đáp án đúng là A (– 75).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4289, 278, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Kết quả của phép tính (– 98) + 8 + 12 + 98 là:","images":[]}', '[{"key":"A","text":"0"},{"key":"B","text":"4"},{"key":"C","text":"10"},{"key":"D","text":"20"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của phép tính (– 98) + 8 + 12 + 98 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 98)\\n+ 8\\n+ 12\\n+ 98 = [(– 98)\\n+ 98]\\n+ (8\\n+ 12) = 0\\n+ 20 = 20 Chọn\\nKết luận: Đáp án đúng là D (20).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4290, 278, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Tổng a – (b – c – d) bằng:","images":[]}', '[{"key":"A","text":"a – b – c – d"},{"key":"B","text":"a + b – c – d"},{"key":"C","text":"a – b + c + d"},{"key":"D","text":"a + b + c + d"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tổng a – (b – c – d) bằng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: a – (b – c – d) = a – b\\n+ c\\n+ d (áp dụng quy tắc dấu ngoặc).\\nKết luận: Đáp án đúng là C (a – b + c + d).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4291, 278, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Nếu a + c = b + c thì:","images":[]}', '[{"key":"A","text":"a = b"},{"key":"B","text":"a < b"},{"key":"C","text":"a > b"},{"key":"D","text":"Cả A, B, C đều sai."}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Nếu a + c = b + c thì:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: Nếu a\\n+ c = b\\n+ c thì a = b.\\nKết luận: Đáp án đúng là A (a = b).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4292, 278, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Chọn câu đúng:","images":[]}', '[{"key":"A","text":"(– 7) + 1 100 + (– 13) + (– 1 100) = 20"},{"key":"B","text":"(– 7) + 1 100 + (– 13) + (– 1 100) = – 20"},{"key":"C","text":"(– 7) + 1 100 + (– 13) + (– 1 100) = 30"},{"key":"D","text":"(– 7) + 1 100 + (– 13) + (– 1 100) = – 10"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 7)\\n+ 1 100\\n+ (– 13)\\n+ (– 1 100) = [(– 7)\\n+ (– 13)]\\n+ [1 100\\n+ (– 1 100)] = – 20\\n+ 0 = – 20 Chọn\\nKết luận: Đáp án đúng là B ((– 7) + 1 100 + (– 13) + (– 1 100) = – 20).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4293, 278, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Kết quả của phép tính 898 – 1 008 là:","images":[]}', '[{"key":"A","text":"Số nguyên âm"},{"key":"B","text":"Số nguyên dương"},{"key":"C","text":"Số lớn hơn 3"},{"key":"D","text":"Số 0"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của phép tính 898 – 1 008 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 898 – 1 008 = 898\\n+ (– 1 008) = – (1 008 – 898) = – 110 Số – 110 là một số nguyên âm nên A đúng.\\nKết luận: Đáp án đúng là A (Số nguyên âm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4294, 278, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Hãy ghép mỗi dòng ở cột A với một dòng ở cột B để được đáp án đúng: Cột A Cột B 1. (2017 – 1994) – 2017","images":[]}', '[{"key":"A","text":"0"},{"key":"B","text":"– 1994"},{"key":"C","text":"500"},{"key":"D","text":"1 – c; 2 – a; 3 – b"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hãy ghép mỗi dòng ở cột A với một dòng ở cột B để được đáp án đúng: Cột A Cột B 1. (2017 – 1994) – 2017\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (2017 – 1994) – 2017 = 2017 – 1994 – 2017 = (2017 – 2017) – 1994 = – 1994 (527 – 2018) – (27 – 2018) = 527 – 2018 – 27\\n+ 2018 = (527 – 27)\\n+ (2018 – 2018) = 500 (– 24) – (76 – 100) = – 24 – 76\\n+ 100 = – (24\\n+ 76)\\n+ 100 = – 100\\n+ 100 = 0 Vậy ta nối 1 – b;\\n2 – c;\\n3 – a.\\nKết luận: Đáp án đúng là A (0).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4295, 278, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Chọn câu đúng:","images":[]}', '[{"key":"A","text":"170 – 228 = 58"},{"key":"B","text":"228 – 892 < 0"},{"key":"C","text":"782 – 783 > 0"},{"key":"D","text":"675 – 908 > – 3"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có:\\n170 – 228 = 170\\n+ (– 228) = – (228 – 170) = – 58 ≠ 58 nên A sai.\\n228 – 892 = 228\\n+ (– 892) = – (892 – 228) = – 664 < 0 nên B đúng.\\n782 – 783 = 782\\n+ (– 783) = – (783 – 782) = – 1 < 0 nên C sai.\\n675 – 908 = 675\\n+ (– 908) = – (908 – 675) = – 233 < – 3 nên D sai.\\nKết luận: Đáp án đúng là B (228 – 892 < 0).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4296, 278, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Biểu diễn hiệu (– 28) – (–32) thành dạng tổng là:","images":[]}', '[{"key":"A","text":"(– 28) + (– 32)"},{"key":"B","text":"(– 28) + 32"},{"key":"C","text":"28 + (– 32)"},{"key":"D","text":"28 + 32"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Biểu diễn hiệu (– 28) – (–32) thành dạng tổng là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Muốn trừ số nguyên a cho số nguyên b ta cộng a với số đối của b.\\nTa có: số đối của – 32 là 32 nên: (– 28) – (–32) = – 28\\n+ 32.\\nKết luận: Đáp án đúng là B ((– 28) + 32).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4297, 278, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Đơn giản biểu thức x + 1 982 + 172 + (– 1 982) – 162 ta được kết quả là:","images":[]}', '[{"key":"A","text":"x – 10"},{"key":"B","text":"x + 10"},{"key":"C","text":"10"},{"key":"D","text":"x"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Đơn giản biểu thức x + 1 982 + 172 + (– 1 982) – 162 ta được kết quả là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: x\\n+ 1 982\\n+ 172\\n+ (– 1 982) – 162 = x\\n+ [1 982\\n+ (– 1 982)]\\n+ (172 – 162) = x\\n+ 0\\n+ 10 = x\\n+ 10 Chọn\\nKết luận: Đáp án đúng là B (x + 10).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4298, 278, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tổng (– 43 567 – 123) + 43 567 bằng:","images":[]}', '[{"key":"A","text":"– 123"},{"key":"B","text":"– 124"},{"key":"C","text":"– 125"},{"key":"D","text":"87 011"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tổng (– 43 567 – 123) + 43 567 bằng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 43 567 – 123)\\n+ 43 567 = – 43 567 – 123\\n+ 43 567 = [(– 43 567)\\n+ 43 567]\\n+ (– 123) = 0\\n+ (– 123) = – 123 Chọn\\nKết luận: Đáp án đúng là A (– 123).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4299, 278, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Đơn giản biểu thức (– 65) – (x + 35) + 101","images":[]}', '[{"key":"A","text":"x"},{"key":"B","text":"x – 1"},{"key":"C","text":"1 – x"},{"key":"D","text":"– x"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Đơn giản biểu thức (– 65) – (x + 35) + 101\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 65) – (x\\n+ 35)\\n+ 101 = – 65 – x – 35\\n+ 101 = – 65 – 35\\n+ 101 – x = – (65\\n+ 35)\\n+ 101 – x = – 100\\n+ 101 – x = (101 – 100) – x = 1 – x Chọn\\nKết luận: Đáp án đúng là C (1 – x).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4300, 278, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Cho số nguyên b và b – x = – 9. Tìm x.","images":[]}', '[{"key":"A","text":"– 9 – b"},{"key":"B","text":"– 9 + b"},{"key":"C","text":"b + 9"},{"key":"D","text":"– b + 9"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho số nguyên b và b – x = – 9. Tìm x.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: b – x = – 9 – x = – 9 – b x = 9\\n+ b Vậy x = 9\\n+ b = b\\n+ 9.\\nKết luận: Đáp án đúng là C (b + 9).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4301, 278, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Số nguyên x nào dưới đây thỏa mãn x – 8 = 20.","images":[]}', '[{"key":"A","text":"x = 12"},{"key":"B","text":"x = 28"},{"key":"C","text":"x = 160"},{"key":"D","text":"x = – 28"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Số nguyên x nào dưới đây thỏa mãn x – 8 = 20.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: x – 8 = 20 x = 20\\n+ 8 x = 28 Vậy x = 28.\\nKết luận: Đáp án đúng là B (x = 28).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4302, 278, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tìm x biết 9 + x = 2.","images":[]}', '[{"key":"A","text":"7"},{"key":"B","text":"– 7"},{"key":"C","text":"11"},{"key":"D","text":"– 11"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tìm x biết 9 + x = 2.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 9\\n+ x = 2 x = 2 – 9 x = – 7 Vậy x = – 7.\\nKết luận: Đáp án đúng là B (– 7).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4303, 278, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tính hợp lý (– 1 215) – (– 215 + 115) – (– 1 115) ta được:","images":[]}', '[{"key":"A","text":"– 2 000"},{"key":"B","text":"2 000"},{"key":"C","text":"0"},{"key":"D","text":"1 000"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính hợp lý (– 1 215) – (– 215 + 115) – (– 1 115) ta được:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 1 215) – (–215\\n+ 115) – (– 1 115) = (– 1 215)\\n+ 215 – 115\\n+ 1 115 = [(– 1 215)\\n+ 215]\\n+ [(– 115)\\n+ 1 115] = (– 1 000)\\n+ 1 000 = 0 Chọn\\nKết luận: Đáp án đúng là C (0).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4304, 278, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Giá trị của x thỏa mãn – 15 + x = – 20","images":[]}', '[{"key":"A","text":"– 5"},{"key":"B","text":"5"},{"key":"C","text":"– 35"},{"key":"D","text":"15"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị của x thỏa mãn – 15 + x = – 20\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: – 15\\n+ x = – 20 x = (– 20) – (– 15) x = (– 20)\\n+ 15 x = – 5 Vậy x = – 5.\\nKết luận: Đáp án đúng là A (– 5).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4305, 278, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Tìm x biết (– 12) + x = (– 15) – (– 87).","images":[]}', '[{"key":"A","text":"84"},{"key":"B","text":"– 84"},{"key":"C","text":"– 114"},{"key":"D","text":"– 90"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tìm x biết (– 12) + x = (– 15) – (– 87).\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 12)\\n+ x = (– 15) – (– 87) (– 12)\\n+ x = (– 15)\\n+ 87 (– 12)\\n+ x = 87 – 15 (– 12)\\n+ x = 72 x = 72 – (– 12) x = 72\\n+ 12 x = 84 Vậy x = 84.\\nKết luận: Đáp án đúng là A (84).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4306, 278, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Số nguyên x thỏa mãn x – (15 – x) = x + 16 là:","images":[]}', '[{"key":"A","text":"1"},{"key":"B","text":"31"},{"key":"C","text":"16"},{"key":"D","text":"– 31"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Số nguyên x thỏa mãn x – (15 – x) = x + 16 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: x – (15 – x) = x\\n+ 16 x – 15\\n+ x = x\\n+ 16 x\\n+ x – x = 16\\n+ 15 x = 31 Vậy x = 31.\\nKết luận: Đáp án đúng là B (31).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4307, 278, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tìm số nguyên x biết tổng của ba số nguyên 15; – 3 và x bằng 23.","images":[]}', '[{"key":"A","text":"11"},{"key":"B","text":"– 11"},{"key":"C","text":"25"},{"key":"D","text":"– 25"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tìm số nguyên x biết tổng của ba số nguyên 15; – 3 và x bằng 23.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 15\\n+ (– 3)\\n+ x = 23 12\\n+ x = 23 x = 23 – 12 x = 11 Vậy x = 11.\\nKết luận: Đáp án đúng là A (11).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4308, 278, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tìm số nguyên x biết 34 – (25 + 34) = x – (25 – 9)","images":[]}', '[{"key":"A","text":"10"},{"key":"B","text":"– 10"},{"key":"C","text":"9"},{"key":"D","text":"– 9"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tìm số nguyên x biết 34 – (25 + 34) = x – (25 – 9)\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải a) Đúng.\\nVì thang máy đang ở tầng 8, sau đó đi lên 3 tầng thì ở tầng a nên a = 8\\n+ 3 = 11.\\nVậy a = 11.\\nb) Đúng.\\nTừ tầng 11, thang máy xuống 13 tầng thì ở tầng b nên b = 11 − 13 = − 13 − 11 = − 2.\\nVậy từ tầng a , tháng máy xuống 13 tầng thì ở tầng hầm thứ 2.\\nc) Sai.\\nTừ tầng hầm thứ 2, thang máy đi lên 6 tầng thì ở tầng c nên c = − 2\\n+ 6 = 4.\\nVậy tầng c cách tầng G là 4 tầng.\\nd) Sai.\\nTừ tầng 4, để quay về với vị trí thang máy ở tầng ban đầu, tức là tầng 8, thì thang máy cần đi lên 8 - 4 = 4 (tầng).\\nVậy từ tầng c , để quay về vị trí thang máy ở tầng ban đầu thì thang máy đi lên bốn tầng nữa.\\nKết luận: Đáp án đúng là D (– 9).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4309, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Kết quả của phép tính (– 125) . 8 là:","images":[]}', '[{"key":"A","text":"1 000"},{"key":"B","text":"– 1 000"},{"key":"C","text":"– 100"},{"key":"D","text":"– 10 000"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của phép tính (– 125) . 8 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 125).\\n8 = – (125.\\n8) = – 1 000.\\nKết luận: Đáp án đúng là B (– 1 000).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4310, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tính (– 42) . (– 5) được kết quả là:","images":[]}', '[{"key":"A","text":"– 210"},{"key":"B","text":"210"},{"key":"C","text":"– 47"},{"key":"D","text":"37"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính (– 42) . (– 5) được kết quả là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 42).\\n(– 5) = 42.\\n5 = 210 Chọn\\nKết luận: Đáp án đúng là B (210).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4311, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Chọn câu đúng.","images":[]}', '[{"key":"A","text":"(– 20) . (– 5) = – 100"},{"key":"B","text":"(– 50) . (– 12) = 600"},{"key":"C","text":"(– 18) . 25 = – 400"},{"key":"D","text":"11 . (– 11) = – 1 111"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu đúng.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải\\n(– 20).\\n(– 5) = 20.\\n5 = 100 nên A sai.\\n(– 50).\\n(– 12) = = 50.\\n12 = 600 nên B đúng.\\n(– 18).\\n25 = – (18.\\n25) = – 450 ≠ – 400 nên C sai.\\n11.\\n(– 11) = – 121 ≠ – 1 111 nên D sai.\\nKết luận: Đáp án đúng là B ((– 50) . (– 12) = 600).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4312, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Chọn câu trả lời đúng.","images":[]}', '[{"key":"A","text":"– 365 . 366 < 1"},{"key":"B","text":"– 365 . 366 = 1"},{"key":"C","text":"– 365 . 366 = – 1"},{"key":"D","text":"– 365 . 366 > 1"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu trả lời đúng.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: – 365.\\n366 < 0 < 1 (tích hai số nguyên khác dấu) và – 365.\\n366 ≠ – 1.\\nKết luận: Đáp án đúng là A (– 365 . 366 < 1).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4313, 279, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Trong các khẳng định sau, khẳng định nào đúng?","images":[]}', '[{"key":"A","text":"Khi nhân một số âm với hai số dương ta được kết qủa là một số dương"},{"key":"B","text":"Khi nhân hai số âm với một số dương ta được kết quả là một số âm"},{"key":"C","text":"Khi nhân hai số âm với hai số dương ta được kết quả là một số dương"},{"key":"D","text":"Khi nhân một số âm với ba số dương ta được kết quả là một số dương"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các khẳng định sau, khẳng định nào đúng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Khi nhân một số âm với hai số dương ta được kết quả là một số âm.\\nVậy A sai Khi nhân hai số âm với một số dương ta được kết qủa là một số dương.\\nVậy B sai Khi nhân hai số âm với hai số dương ta được kết qủa là một số dương.\\nVậy C đúng Khi nhân một số âm với ba số dương ta được kết qủa là một số âm.\\nVậy D sai Chọn\\nKết luận: Đáp án đúng là C (Khi nhân hai số âm với hai số dương ta được kết quả là một số dương).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4314, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Chọn câu sai.","images":[]}', '[{"key":"A","text":"(– 19) . (– 7) > 0"},{"key":"B","text":"3 . (– 121) < 0"},{"key":"C","text":"45 . (– 11) < – 500"},{"key":"D","text":"46 . (– 11) < – 500"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu sai.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải\\n(– 19).\\n(– 7) > 0, A đúng vì tích hai số nguyên cùng dấu là một số nguyên dương.\\n3.\\n(– 121) < 0, B đúng vì tích hai số nguyên khác dấu là một số nguyên âm.\\n45.\\n(– 11) = – (45.\\n11) = – 465 > – 500 nên C sai.\\n46.\\n(– 11) = – (46.\\n11) = – 506 < – 500 nên D đúng.\\nKết luận: Đáp án đúng là C (45 . (– 11) < – 500).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4315, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Trong các khẳng định sau khẳng định đúng là:","images":[]}', '[{"key":"A","text":"Nếu a . b > 0 thì a và b là hai số nguyên dương"},{"key":"B","text":"Nếu a . b > 0 thì a và b là hai số nguyên âm"},{"key":"C","text":"Nếu a . b = 0 thì a = 0 và b = 0"},{"key":"D","text":"Nếu a . b < 0 thì a và b là hai số nguyên khác dấu"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các khẳng định sau khẳng định đúng là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Nếu a.\\nb > 0 thì a và b là hai số nguyên cùng dấu, tức a và b có thể cùng là số nguyên âm hoặc cùng là số nguyên dương.\\nVậy và B sai Nếu a.\\nb = 0 thì a = 0 hoặc b = 0.\\nVậy sai.\\nNếu a.\\nb < 0 thì a và b là hai số nguyên khác dấu.\\nđúng.\\nKết luận: Đáp án đúng là A (Nếu a . b > 0 thì a và b là hai số nguyên dương).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4316, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tích (– 3) . (– 3) . (– 3) . (– 3) . (– 3) . (– 3) . (– 3) bằng:","images":[]}', '[{"key":"A","text":"3 8"},{"key":"B","text":"– 3 7"},{"key":"C","text":"3 7"},{"key":"D","text":"(– 3) 8"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tích (– 3) . (– 3) . (– 3) . (– 3) . (– 3) . (– 3) . (– 3) bằng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 3).\\n(– 3).\\n(– 3).\\n(– 3).\\n(– 3).\\n(– 3).\\n(– 3) = (– 3) 7 = – 3 7 Chọn\\nKết luận: Đáp án đúng là B (– 3 7).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4317, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Chọn đáp án đúng.","images":[]}', '[{"key":"A","text":"(– 8) . (– 7) < 0"},{"key":"B","text":"(– 15) . 3 > (– 2) . (– 3)"},{"key":"C","text":"2 . 18 = (– 6) . (– 6)"},{"key":"D","text":"(– 5) . 6 > 0"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn đáp án đúng.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 8).\\n(– 7) > 0 (tích hai số nguyên cùng dấu là số nguyên dương).\\nsai (– 15).\\n3 = – (15.\\n3) = – 45 (– 2).\\n(– 3) = 2.\\n3 = 6 – 45 < 6 nên sai 2.\\n18 = 36;\\n(– 6).\\n(– 6) = 6.\\n6 = 36 nên đúng (– 5).\\n6 < 0 ( tích hai số nguyên khác dấu là số nguyên âm).\\nsai Chọn\\nKết luận: Đáp án đúng là A ((– 8) . (– 7) < 0).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4318, 279, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Tích (– 4) 2 . (– 2) bằng:","images":[]}', '[{"key":"A","text":"– 16"},{"key":"B","text":"16"},{"key":"C","text":"– 32"},{"key":"D","text":"32"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tích (– 4) 2 . (– 2) bằng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 4) 2.\\n(– 2) = 16.\\n(– 2) = – 32.\\nKết luận: Đáp án đúng là C (– 32).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4319, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Viết lại tích (– 2) . (– 2) . (– 2) . (– 3) . (– 3) . (– 3) dưới dạng một lũy thừa.","images":[]}', '[{"key":"A","text":"2 3 . 3 3"},{"key":"B","text":"– 2 3 . 3 3"},{"key":"C","text":"6 3"},{"key":"D","text":"– 6 3"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Viết lại tích (– 2) . (– 2) . (– 2) . (– 3) . (– 3) . (– 3) dưới dạng một lũy thừa.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải (– 2).\\n(– 2).\\n(– 2).\\n(– 3).\\n(– 3).\\n(– 3) = [(– 2).\\n(– 3)].\\n[(– 2).\\n(– 3)].\\n[(– 2).\\n(– 3)] = 6.\\n6.\\n6 = 6 3.\\nKết luận: Đáp án đúng là C (6 3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4320, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tính (36 – 16) . (– 5) + 6 . (– 14 – 6), ta được:","images":[]}', '[{"key":"A","text":"– 220"},{"key":"B","text":"– 20"},{"key":"C","text":"20"},{"key":"D","text":"220"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính (36 – 16) . (– 5) + 6 . (– 14 – 6), ta được:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (36 – 16).\\n(– 5)\\n+ 6.\\n(– 14 – 6) = 20.\\n(– 5)\\n+ 6.\\n(– 20) = – (20.\\n5)\\n+ [– (6.\\n20)] = – 100 – 120 = – 220 Chọn\\nKết luận: Đáp án đúng là A (– 220).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4321, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Giá trị của biểu thức (x – 2)(x – 3) tại x = – 1 là:","images":[]}', '[{"key":"A","text":"– 12"},{"key":"B","text":"12"},{"key":"C","text":"– 2"},{"key":"D","text":"2"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị của biểu thức (x – 2)(x – 3) tại x = – 1 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Thay x = – 1 vào biểu thức ta được: (x – 2)(x – 3) = (– 1 – 2)(– 1 – 3) = (– 3).\\n(– 4) = 3.\\n4 = 12.\\nVậy giá trị của biểu thức đã cho bằng 12 tại x = – 1.\\nKết luận: Đáp án đúng là B (12).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4322, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tính nhanh (– 5) . 125 . (– 8) . 20 . (– 2) ta được kết quả là:","images":[]}', '[{"key":"A","text":"– 200 000"},{"key":"B","text":"– 2 000 000"},{"key":"C","text":"200 000"},{"key":"D","text":"– 100 000"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính nhanh (– 5) . 125 . (– 8) . 20 . (– 2) ta được kết quả là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 5).\\n125.\\n(– 8).\\n20.\\n(– 2) = [125.\\n(– 8)].\\n[(– 5).\\n20].\\n(– 2) = (– 1 000).\\n(– 100).\\n(– 2) = – 200 000 Chọn\\nKết luận: Đáp án đúng là A (– 200 000).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4323, 279, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Điền hai số tiếp theo vào dãy số sau: – 2; 4; – 8; 16; ...","images":[]}', '[{"key":"A","text":"32 và 64"},{"key":"B","text":"– 32 và 64"},{"key":"C","text":"32 và – 64"},{"key":"D","text":"– 32 và – 64"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Điền hai số tiếp theo vào dãy số sau: – 2; 4; – 8; 16; ...\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 4 = (– 2).\\n(– 2) – 8 = 4.\\n(– 2) 16 = (– 8).\\n(– 2) Do đó, trong dãy số trên số hạng sau là tích của số hạng trước với – 2.\\nVậy hai số hạng tiếp theo là: 16.\\n(– 2) = – 32 (– 32).\\n(– 2) = 64 Ta cần điền các số tiếp theo theo thứ tự là – 32 và 64.\\nKết luận: Đáp án đúng là B (– 32 và 64).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4324, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tính giá trị của biểu thức (– 5)x + (– 6)y với x = – 6, y = – 7.","images":[]}', '[{"key":"A","text":"– 72"},{"key":"B","text":"72"},{"key":"C","text":"– 80"},{"key":"D","text":"80"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính giá trị của biểu thức (– 5)x + (– 6)y với x = – 6, y = – 7.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Thay x = – 6, y = – 7 vào biểu thức ta được: (– 5)x\\n+ (– 6)y = (– 5).\\n(– 6)\\n+ (– 6).\\n(– 7) = 5.\\n6\\n+ 6.\\n7 = 30\\n+ 42 = 72 Chọn\\nKết luận: Đáp án đúng là B (72).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4325, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Điền số thích hợp vào chỗ chấm: 17 . (... + 7) = 17 . (– 5) + 17 . 7","images":[]}', '[{"key":"A","text":"– 2"},{"key":"B","text":"– 3"},{"key":"C","text":"– 4"},{"key":"D","text":"– 5"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Điền số thích hợp vào chỗ chấm: 17 . (... + 7) = 17 . (– 5) + 17 . 7\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 17.\\n(– 5)\\n+ 17.\\n7 = 17.\\n[(– 5)\\n+ 7] Vậy ta cần điền số – 5 vào chỗ chấm.\\nKết luận: Đáp án đúng là D (– 5).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4326, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Khi x = – 12, giá trị của biểu thức (x – 8).(x + 7) là số nào trong bốn số sau:","images":[]}', '[{"key":"A","text":"– 100"},{"key":"B","text":"100"},{"key":"C","text":"– 96"},{"key":"D","text":"– 196"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Khi x = – 12, giá trị của biểu thức (x – 8).(x + 7) là số nào trong bốn số sau:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Thay x = – 12 vào biểu thức (x – 8).\\n(x\\n+ 7) ta được: (– 12 – 8).\\n(– 12\\n+ 7) = (– 20).\\n(– 5) = 20.\\n5 = 100 Chọn\\nKết luận: Đáp án đúng là B (100).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4327, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Giá trị của biểu thức (– 63) . (1 – 299) – 299 . 63 là:","images":[]}', '[{"key":"A","text":"– 63"},{"key":"B","text":"63"},{"key":"C","text":"– 53"},{"key":"D","text":"53"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị của biểu thức (– 63) . (1 – 299) – 299 . 63 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 63).\\n(1 – 299) – 299.\\n63 = (– 63).\\n1\\n+ (– 63).\\n(– 299) – 299.\\n63 = – 63\\n+ 63.\\n299 – 63.\\n299 = – 63 Chọn\\nKết luận: Đáp án đúng là A (– 63).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4328, 279, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Giá trị của m . n 2 với m = 3, n = – 5 là:","images":[]}', '[{"key":"A","text":"– 30"},{"key":"B","text":"30"},{"key":"C","text":"– 75"},{"key":"D","text":"75"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị của m . n 2 với m = 3, n = – 5 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Thay m = 3, n = – 5 vào biểu thức ta được: m.\\nn 2 = 3.\\n(– 5) 2 = 3.\\n25 = 75.\\nKết luận: Đáp án đúng là D (75).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4329, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Giá trị của biểu thức (27 – 32) . x khi x = 8 là:","images":[]}', '[{"key":"A","text":"– 40"},{"key":"B","text":"– 39"},{"key":"C","text":"– 38"},{"key":"D","text":"– 37"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị của biểu thức (27 – 32) . x khi x = 8 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Thay x = 8 vào biểu thức ta được: (27 – 32).\\nx = (27 – 32).\\n8 = [27\\n+ (– 32)].\\n8 = [– (32 – 27)].\\n8 = – 5.\\n8 = – 40.\\nKết luận: Đáp án đúng là A (– 40).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4330, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tính tổng S = 1 – 3 + 5 – 7 + ... + 2001 – 2003.","images":[]}', '[{"key":"A","text":"S = – 1 000"},{"key":"B","text":"S = – 1 001"},{"key":"C","text":"S = – 1 002"},{"key":"D","text":"S = – 1 003"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính tổng S = 1 – 3 + 5 – 7 + ... + 2001 – 2003.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Dãy số 1;\\n3;\\n5;\\n7;\\n…;\\n2003 là dãy số cách đều nhau 2 đơn vị nên dãy này có số số hạng là: (2 003 – 1).\\n2\\n+ 1 = 2 002: 2\\n+ 1 = 1 001\\n+ 1 = 1 002 (số hạng).\\nKhi ta nhóm các số lại với nhau thành cặp thì có tất cả: 1 002: 2 = 501 (cặp số).\\nTa có: S = 1 – 3\\n+ 5 – 7 +.\\n.\\n.\\n+ 2001 – 2003 S = (1 – 3)\\n+ (5 – 7) +.\\n.\\n.\\n+ (2001 – 2003) S = (– 2)\\n+ (– 2) +.\\n.\\n.\\n+ (– 2) S = 501.\\n(– 2) = – 1 002 Chọn\\nKết luận: Đáp án đúng là C (S = – 1 002).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4331, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Giá trị của biểu thức 27 . (– 13) + 27 . (– 27) + (– 14) . (– 27) là:","images":[]}', '[{"key":"A","text":"– 702"},{"key":"B","text":"702"},{"key":"C","text":"– 720"},{"key":"D","text":"720"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị của biểu thức 27 . (– 13) + 27 . (– 27) + (– 14) . (– 27) là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 27.\\n(– 13)\\n+ 27.\\n(– 27)\\n+ (– 14).\\n(– 27) = 27.\\n(– 13)\\n+ 27.\\n(– 27)\\n+ 14.\\n27 = 27.\\n[(– 13)\\n+ (– 27)\\n+ 14] = 27.\\n[(– 40)\\n+ 14] = 27.\\n(– 26) = – 702.\\nKết luận: Đáp án đúng là A (– 702).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4332, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Giá trị biểu thức M = (– 192 873) . (– 2 345) . (– 4) 5 . 0 là:","images":[]}', '[{"key":"A","text":"– 192 873"},{"key":"B","text":"1"},{"key":"C","text":"0"},{"key":"D","text":"(– 192 873) . (– 2 345) . (– 4) 5"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị biểu thức M = (– 192 873) . (– 2 345) . (– 4) 5 . 0 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: M = (– 192 873).\\n(– 2 345).\\n(– 4) 5.\\n0 = 0 (một tích nhân với 0 cũng bằng 0).\\nKết luận: Đáp án đúng là C (0).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4333, 279, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Giá trị của x thỏa mãn – 2(x – 5) < 0 là:","images":[]}', '[{"key":"A","text":"x = 3"},{"key":"B","text":"x = 4"},{"key":"C","text":"x = 5"},{"key":"D","text":"x = 6"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị của x thỏa mãn – 2(x – 5) < 0 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Khi x > 5 thì x – 5 > 0 nên – 2(x – 5) < 0 Trong bốn đáp án trên chỉ có x = 6 > 5.\\nKết luận: Đáp án đúng là D (x = 6).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4334, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tính tổng S = 1 – 2 + 3 – 4 + ... + 2 017 – 2 018","images":[]}', '[{"key":"A","text":"S = – 1 006"},{"key":"B","text":"S = – 1 007"},{"key":"C","text":"S = – 1 008"},{"key":"D","text":"S = – 1 009"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính tổng S = 1 – 2 + 3 – 4 + ... + 2 017 – 2 018\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Dãy số 1;\\n2;\\n3;\\n…;\\n2 018 có 2 018 số hạng nên có tất cả 2018: 2 = 1 009 cặp số.\\nTa có: S = 1 – 2\\n+ 3 – 4 +.\\n.\\n.\\n+ 2 017 – 2 018 S = (1 – 2)\\n+ (3 – 4) +.\\n.\\n.\\n+ (2 017 – 2 018) S = (– 1)\\n+ (– 1) +.\\n.\\n.\\n+ (– 1) S = 1 009.\\n(– 1) = – 1 009 Chọn\\nKết luận: Đáp án đúng là D (S = – 1 009).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4335, 279, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Giá trị của x thỏa mãn 2(x – 5) < 0 là:","images":[]}', '[{"key":"A","text":"x = 4"},{"key":"B","text":"x = 5"},{"key":"C","text":"x = 6"},{"key":"D","text":"x = 7"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Giá trị của x thỏa mãn 2(x – 5) < 0 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Khi x < 5 thì x – 5 < 0 nên 2(x – 5) < 0 Trong bốn đáp án trên chỉ có x = 4 < 5.\\nKết luận: Đáp án đúng là A (x = 4).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4336, 279, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tính giá trị của biểu thức x – 2 + x – 2 + x – 2 + x – 2 + x – 2 tại x = – 7.","images":[]}', '[{"key":"A","text":"– 30"},{"key":"B","text":"30"},{"key":"C","text":"– 45"},{"key":"D","text":"45"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính giá trị của biểu thức x – 2 + x – 2 + x – 2 + x – 2 + x – 2 tại x = – 7.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải a) Đúng.\\nVì tàu ngầm đang ở độ sâu cách mặt biển 15 m nên ban đầu, tàu ngầm ở độ cao -15 m so với mặt nước biển.\\nb) Đúng.\\nSau 2 phút, tàu nổi lên trên được: 2 ⋅ 3 = 6 m.\\nVậy sau 2 phút, tàu nổi lên trên được 6 m.\\nc) Sai.\\nSau 2 phút, tàu ở độ cao so với mực nước biển là: − 15\\n+ 6 = − 9 m.\\nVậy sau 2 phút, tàu ở độ cao -9 m so với mực nước biển.\\nd) Đúng.\\nSau 5 phút, tàu ở độ cao so với mặt nước biển là: − 15\\n+ 5 ⋅ 3 = 0 m.\\nVậy sau 5 phút, tàu ở mặt nước biển.\\nKết luận: Đáp án đúng là C (– 45).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4337, 280, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Kết quả của phép tính (– 15) : 5 là:","images":[]}', '[{"key":"A","text":"3"},{"key":"B","text":"5"},{"key":"C","text":"– 3"},{"key":"D","text":"– 5"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của phép tính (– 15) : 5 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 15): 5 = – (15: 5) = – 3.\\nKết luận: Đáp án đúng là C (– 3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4338, 280, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tính: (– 66) : (– 11) ta được kết quả là:","images":[]}', '[{"key":"A","text":"6"},{"key":"B","text":"11"},{"key":"C","text":"– 6"},{"key":"D","text":"– 11"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính: (– 66) : (– 11) ta được kết quả là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 66): (– 11) = 66: 11 = 6.\\nKết luận: Đáp án đúng là A (6).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4339, 280, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Kết quả của phép tính 65 : (– 13) là:","images":[]}', '[{"key":"A","text":"– 13"},{"key":"B","text":"13"},{"key":"C","text":"5"},{"key":"D","text":"– 5"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả của phép tính 65 : (– 13) là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: 65: (– 13) = – (65: 13) = – 5.\\nKết luận: Đáp án đúng là D (– 5).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4340, 280, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho a, b là các số nguyên và b ≠ 0. Nếu có số nguyên q sao cho a = bq thì:","images":[]}', '[{"key":"A","text":"a là ước của b"},{"key":"B","text":"b là ước của a"},{"key":"C","text":"a là bội của b"},{"key":"D","text":"Cả B, C đều đúng"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho a, b là các số nguyên và b ≠ 0. Nếu có số nguyên q sao cho a = bq thì:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Với a, b là các số nguyên và b ≠ 0.\\nNếu có số nguyên q sao cho a = bq thì a là bội của b và b là ước của a nên cả hai và C đều đúng.\\nKết luận: Đáp án đúng là B (b là ước của a).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4341, 280, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Chọn khẳng định sai.","images":[]}', '[{"key":"A","text":"Nếu a là bội của b thì – a cũng là bội của b"},{"key":"B","text":"Nếu b là ước của a thì – b cũng là ước của a"},{"key":"C","text":"Nếu a là bội của b thì b là ước của a"},{"key":"D","text":"Nếu a là bội của b thì b không là ước của a"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn khẳng định sai.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Theo lý thuyết ta có: - Nếu a là bội của b thì – a cũng là bội của b - Nếu b là ước của a thì – b cũng là ước của a - Nếu a là bội của b thì b là ước của a Vậy A, B, C đúng và D sai.\\nKết luận: Đáp án đúng là D (Nếu a là bội của b thì b không là ước của a).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4342, 280, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Chọn khẳng định sai.","images":[]}', '[{"key":"A","text":"Số 0 là bội của mọi số nguyên."},{"key":"B","text":"Các số -1 và 1 là ước của mọi số nguyên"},{"key":"C","text":"Nếu a chia hết cho b thì a cũng chia hết cho bội của b."},{"key":"D","text":"Số 0 không là ước của bất kì số nguyên nào."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn khẳng định sai.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có:\\n+ Số 0 là bội của mọi số nguyên vì 0 chia hết cho tất cả các số nguyên khác 0 nên A đúng.\\n+ Mọi số nguyên đều chia hết cho -1 và 1 nên -1 và 1 là ước của mọi số nguyên nên B đúng.\\n+ Nếu a chia hết cho b thì a là bội của b, mà một số thì có vô số bội nên chưa chắc a chia hết cho bội của b.\\nChẳng hạn: 10 và 4 đều chia hết cho – 2 nên 10 và 4 đều là các bội của – 2 nhưng 10 không chia hết cho 4.\\nDo đó C sai.\\n+ Ta không có phép chia cho 0 nên 0 không phải là ước của bất kì số nguyên nào nên D đúng.\\nKết luận: Đáp án đúng là C (Nếu a chia hết cho b thì a cũng chia hết cho bội của b.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4343, 280, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Các bội của 6 là:","images":[]}', '[{"key":"A","text":"– 6; 6; 0; 23; – 23"},{"key":"B","text":"132; – 132; 16"},{"key":"C","text":"– 1; 1; 6; – 6"},{"key":"D","text":"0; 6; – 6; 12; –12; ..."}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Các bội của 6 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta tìm các bội tự nhiên của 6 bằng cách lấy 6 lần lượt nhân với các số tự nhiên 0, 1, 2, … ta được các bội tự nhiên của 6 là 0, 6, 12, … Suy ra các bội nguyên âm của 6 là – 6, – 12, … Vậy các bội của 6 là 0;\\n6;\\n– 6;\\n12;\\n– 12;\\n.\\n.\\n.\\nKết luận: Đáp án đúng là D (0; 6; – 6; 12; –12; ...).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4344, 280, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tập hợp các ước của – 8 là:","images":[]}', '[{"key":"A","text":"A = {1; – 1; 2; – 2; 4; – 4; 8; – 8}"},{"key":"B","text":"A = {0; ± 1; ± 2; ± 4; ± 8}"},{"key":"C","text":"A = {1; 2; 4; 8}"},{"key":"D","text":"A = {0; 1; 2; 4; 8}"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tập hợp các ước của – 8 là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có – 8 = (– 1).\\n8 = 1.\\n(– 8) = (– 2).\\n4 = 2.\\n(– 4) Tập hợp các ước của – 8 là A = {1; – 1; 2; – 2; 4; – 4; 8; – 8}.\\nKết luận: Đáp án đúng là A (A = {1; – 1; 2; – 2; 4; – 4; 8; – 8}).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4345, 280, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Cho tập hợp B = {x | 6 ⁝ x}. Tập hợp B có bao nhiêu phần tử?","images":[]}', '[{"key":"A","text":"5"},{"key":"B","text":"8"},{"key":"C","text":"10"},{"key":"D","text":"12"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho tập hợp B = {x | 6 ⁝ x}. Tập hợp B có bao nhiêu phần tử?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: B = {x ∈ Z| 6 ⁝ x} Vì 6 ⁝ x nên x là ước của 6, lại có x ∈ Z nên x là các ước nguyên của 6.\\nMà các ước tự nhiên của 6 là: 1;\\n2;\\n3;\\n6 Suy ra các ước nguyên âm của 6 là: – 1;\\n– 2;\\n– 3;\\n– 6.\\nVậy có tất cả 8 ước số nguyên của 6 hay tập hợp B có 8 phần tử.\\nKết luận: Đáp án đúng là B (8).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4346, 280, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Cho số nguyên tố p. Số ước của p là:","images":[]}', '[{"key":"A","text":"1 ước"},{"key":"B","text":"2 ước"},{"key":"C","text":"3 ước"},{"key":"D","text":"4 ước"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho số nguyên tố p. Số ước của p là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải: Các ước của số nguyên tố p là: 1;\\n– 1;\\np;\\n– p.\\nVậy có 4 ước của số nguyên tố p.\\nKết luận: Đáp án đúng là D (4 ước).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4347, 280, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tìm số nguyên x, biết: (– 5) . x = 45.","images":[]}', '[{"key":"A","text":"x = 5"},{"key":"B","text":"x = 9"},{"key":"C","text":"x = – 5"},{"key":"D","text":"x = – 9"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tìm số nguyên x, biết: (– 5) . x = 45.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 5).\\nx = 45 Suy ra x = 45: (– 5) = – (45: 5) = – 9.\\nVậy x = – 9.\\nKết luận: Đáp án đúng là D (x = – 9).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4348, 280, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Có bao nhiêu ước của – 24.","images":[]}', '[{"key":"A","text":"9"},{"key":"B","text":"17"},{"key":"C","text":"8"},{"key":"D","text":"16"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Có bao nhiêu ước của – 24.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Có 8 ước tự nhiên của 24 là 1;\\n2;\\n3;\\n4;\\n6;\\n8;\\n12;\\n24 Vậy có 8.\\n2 = 16 ước của – 24.\\nKết luận: Đáp án đúng là D (16).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4349, 280, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Viết tập hợp các số nguyên x, biết 12 ⁝ x và x < – 2.","images":[]}', '[{"key":"A","text":"{1}"},{"key":"B","text":"{– 3; – 4; – 6; – 12}"},{"key":"C","text":"{– 2; – 1}"},{"key":"D","text":"{– 2; – 1; 1; 2; 3; 4; 6; 12}"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Viết tập hợp các số nguyên x, biết 12 ⁝ x và x < – 2.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải: Các ước số tự nhiên của 12 là: 1;\\n2;\\n3;\\n4;\\n6;\\n12 Suy ra các ước số nguyên âm của 12 là: – 1;\\n– 2;\\n– 3;\\n– 4;\\n– 6;\\n– 12 Vậy tập hợp ước của 12 là {±1; ±2; ±3; ±4; ±6; ±12} Vì x < -2 nên các số x thỏa mãn là: – 3;\\n– 4;\\n– 6;\\n– 12.\\nTa viết được tập hợp: {– 3; – 4; – 6; –12}.\\nKết luận: Đáp án đúng là B ({– 3; – 4; – 6; – 12}).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4350, 280, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Viết tập hợp K các số nguyên x thỏa mãn (x + 3) ⁝ (x + 1).","images":[]}', '[{"key":"A","text":"K = {– 3; – 2; 0; 1}"},{"key":"B","text":"K = {– 1; 0; 2; 3}"},{"key":"C","text":"K = {– 3; 0; 1; 2}"},{"key":"D","text":"K = {– 2; 0; 1; 3}"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Viết tập hợp K các số nguyên x thỏa mãn (x + 3) ⁝ (x + 1).\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: x\\n+ 3 = (x\\n+ 1)\\n+ 2 Vì (x\\n+ 3) ⁝ (x\\n+ 1), (x\\n+ 1) ⁝ (x\\n+ 1) nên 2 ⁝ (x\\n+ 1) Khi đó x\\n+ 1 là ước của 2.\\nMà các ước của 2 là: – 1;\\n1;\\n2;\\n– 2.\\nDo đó, x\\n+ 1 = ±1 hoặc x\\n+ 1 = ±2 Nếu x\\n+ 1 = 1 thì x = 0 Nếu x\\n+ 1 = – 1 thì x = – 2 Nếu x\\n+ 1 = 2 thì x = 1 Nếu x\\n+ 1 = – 2 thì x = – 3 Do đó các số nguyên x thỏa mãn yêu cầu là: – 3;\\n– 2;\\n0;\\n1.\\nVậy K = {– 3; – 2; 0; 1}.\\nKết luận: Đáp án đúng là A (K = {– 3; – 2; 0; 1}).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4351, 280, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Tìm số nguyên x biết (– 12) 2 . x = 56 + 10 . 13x.","images":[]}', '[{"key":"A","text":"x = 3"},{"key":"B","text":"x = 4"},{"key":"C","text":"x = 5"},{"key":"D","text":"x = 6"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tìm số nguyên x biết (– 12) 2 . x = 56 + 10 . 13x.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải Ta có: (– 12) 2.\\nx = 56\\n+ 10.\\n13x 144x = 56\\n+ 130x 144x – 130x = 56 14x = 56 x = 56: 14 x = 4 Vậy x = 4.\\nKết luận: Đáp án đúng là B (x = 4).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4352, 280, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tìm số nguyên x biết: (– 6) 3 . x = 78 + (– 10) . 19x.","images":[]}', '[{"key":"A","text":"x = 3"},{"key":"B","text":"x = – 3"},{"key":"C","text":"x = 4"},{"key":"D","text":"x = – 4"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tìm số nguyên x biết: (– 6) 3 . x = 78 + (– 10) . 19x.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nLời giải a) Đúng.\\nVì x: − 20 = − 6 nên x = − 20 ⋅ − 6 = 120 > 0.\\nVậy x > 0.\\nb) Đúng.\\nVì y ⋅ − 15 = 45 nên y = 45: − 15 = − 3.\\nVậy y = − 3.\\nc) Đúng.\\nVì 120 = − 3 ⋅ − 40 nên 120 ⋮ − 3.\\nVậy x ⋮ y.\\nd) Sai.\\nVì 120 ⋮ − 3 nên các ước chung của 120 và -3 là ước của -3.\\nSuy ra, ƯC − 3 , 120 = Ư(-3) = {1; -1; 3; -3}.\\nVậy có bốn số nguyên là ước chung của x và y.\\nKết luận: Đáp án đúng là B (x = – 3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4353, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Phát biểu nào sau đây sai ?","images":[]}', '[{"key":"A","text":"Hình lục giác đều có 6 đỉnh"},{"key":"B","text":"Hình lục giác đều có 6 cạnh"},{"key":"C","text":"Hình lục giác đều có 6 đường chéo chính"},{"key":"D","text":"Hình lục giác đều có 6 góc"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Phát biểu nào sau đây sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Các , B, D đúng.\\nHình lục giác đều có 3 đường chéo chính => sai.\\nần chọn là: C\\nKết luận: Đáp án đúng là A (Hình lục giác đều có 6 đỉnh).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4354, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình lục giác đều MNPQRH, phát biểu nào sai ?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/e64c8d5625e7faeb888aea3c2a4f0f3e44807885.png","width":"243","height":"224","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113711.PNG"}]}', '[{"key":"A","text":"MQ = NR"},{"key":"B","text":"MH = RQ"},{"key":"C","text":"MN = HR"},{"key":"D","text":"MH = MQ"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình lục giác đều MNPQRH, phát biểu nào sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình lục giác đều MNPQRH có 3 đường chéo chính bằng nhau nên: MQ = NR => A đúng Hình lục giác đều MNPQRH có 6 cạnh bằng nhau nên MH = RQ và MN = HR => B, C đúng.\\nDo MH là cạnh, MQ là đường chéo chính nên hai đoạn này không bằng nhau => D sai ần chọn là: D\\nKết luận: Đáp án đúng là C (MN = HR).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4355, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Cho hình lục giác đều MNPQRH, có bao nhiêu tam giác đều được tạo thành từ các đường chéo chính có cạnh bằng cạnh của lục giác đều","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/0ef8f36f29d5151b946ff88f6dc2360a74cbb4f6.png","width":"243","height":"224","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113713.PNG"}]}', '[{"key":"A","text":"8"},{"key":"B","text":"2"},{"key":"C","text":"4"},{"key":"D","text":"6"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho hình lục giác đều MNPQRH, có bao nhiêu tam giác đều được tạo thành từ các đường chéo chính có cạnh bằng cạnh của lục giác đều\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Ta đánh số như hình trên Nhận thấy có các hình tam giác đều là: 1, 2, 3, 4, 5, 6.\\nVậy có 6 tam giác đều.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (4).","images":[{"id":"explanation-img-1","alt":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/b17ee7760f6f9722d8a8ee6bbe08fa9a62a0466b.png","width":"170","height":"156","alt_text":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113712.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4356, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình lục giác đều MNPQRH, phát biểu nào sai ?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/13450d3c3225ce0b13995475b7deeb6bbad0cc48.png","width":"243","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113714.PNG"}]}', '[{"key":"A","text":"6 đỉnh là M, N, P, Q, R, H"},{"key":"B","text":"6 cạnh là MN, NP, PQ, MQ, QR, HM"},{"key":"C","text":"3 đường chéo chính là MQ, HP, RN."},{"key":"D","text":"3 đường chéo chính cắt nhau tại 1 điểm."}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình lục giác đều MNPQRH, phát biểu nào sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: sai do MQ là đường chéo chính, sửa lại: 6 cạnh là MN, NP, PQ, HR, QR, HM ần chọn là: B\\nKết luận: Đáp án đúng là B (6 cạnh là MN, NP, PQ, MQ, QR, HM).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4357, 281, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Cho tam giác đều MNP có MN = 5cm, khẳng định nào sau đây đúng?","images":[]}', '[{"key":"A","text":"NP = 3cm"},{"key":"B","text":"MP = 4cm"},{"key":"C","text":"NP = 6cm"},{"key":"D","text":"MP = 5cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho tam giác đều MNP có MN = 5cm, khẳng định nào sau đây đúng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trong tam giác đều ba cạnh bằng nhau mà MN = 5cm nên ta có: MN = NP = MP = 5cm => Chọn D ần chọn là: D\\nKết luận: Đáp án đúng là C (NP = 6cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4358, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Chọn phát biểu sai :","images":[]}', '[{"key":"A","text":"Tam giác đều có ba cạnh"},{"key":"B","text":"Ba cạnh của tam giác đều bằng nhau"},{"key":"C","text":"Bốn góc của tam giác đều bằng nhau"},{"key":"D","text":"Tam giác đều có ba đỉnh"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Chọn phát biểu sai :\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trong tam giác đều ba góc bằng nhau => sai.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (Bốn góc của tam giác đều bằng nhau).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4359, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Hình dưới đây có mấy hình tam giác?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/54b3ee58384dde4731476c229bc13139cf4a2e9b.png","width":"232","height":"150","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113715.PNG"}]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hình dưới đây có mấy hình tam giác?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình trên có 2 hình tam giác nhỏ là: 1, 2 và 1 hình tam giác lớn ghép từ hai hình trên => Có tất cả 3 hình tam giác ần chọn là: C\\nKết luận: Đáp án đúng là C (3).","images":[{"id":"explanation-img-1","alt":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/33f4fdd07dc5a5ac386a8db81603d18e59221206.png","width":"180","height":"133","alt_text":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113716.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4360, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Hình lục giác đều có mấy cạnh","images":[]}', '[{"key":"A","text":"3"},{"key":"B","text":"5"},{"key":"C","text":"6"},{"key":"D","text":"8"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hình lục giác đều có mấy cạnh\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình lục giác đều có 6 cạnh ần chọn là: C\\nKết luận: Đáp án đúng là C (6).","images":[{"id":"explanation-img-1","alt":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8e22f3aa9848f9500a9f0b62d4fe50d5c57957e4.png","width":"175","height":"161","alt_text":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113717.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4361, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Cho lục giác đều ABCDEF có AB = 3cm, chọn câu đúng","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/bd76050eaa6ee29a72eb572a873dd15012729fd7.png","width":"363","height":"343","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113718.PNG"}]}', '[{"key":"A","text":"FC = 3cm"},{"key":"B","text":"AD = 3cm"},{"key":"C","text":"BE = 3cm"},{"key":"D","text":"EF = 3cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho lục giác đều ABCDEF có AB = 3cm, chọn câu đúng\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Lục giác đều có các cạnh bằng nhau nên AB = EF = 3cm Các đoạn thẳng AD, BE, FC là các đường chéo chính nên không bằng cạnh bên.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (BE = 3cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4362, 281, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Hình lục giác đều có bao nhiêu đường chéo chính","images":[]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hình lục giác đều có bao nhiêu đường chéo chính\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình lục giác đều có 3 đường chéo chính Ví dụ: Lục giác đều ABCD có các đường chéo chính là: AD, BE, FC ần chọn là: C\\nKết luận: Đáp án đúng là C (3).","images":[{"id":"explanation-img-1","alt":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/605df7e885902cc0d7a45848bcff00f2729b5689.png","width":"236","height":"207","alt_text":"Bài tập trắc nghiệm Bài 1: Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113719.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4363, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Cho hình chữ nhật ABCD, phát biểu nào đúng?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/234d0dd01ff6dd821ae06907ce16c1939f3b52fe.png","width":"254","height":"184","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113741.PNG"}]}', '[{"key":"A","text":"AB = AC"},{"key":"B","text":"AC = DO"},{"key":"C","text":"AC = BD"},{"key":"D","text":"OB = AC"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho hình chữ nhật ABCD, phát biểu nào đúng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trong hình chữ nhật hai đường chéo bằng nhau nên AC = BD => đúng sai do AB là cạnh, AC là đường chéo nên chúng không bằng nhau.\\nsai do AC là đường chéo, DO là một nửa đường chéo còn lại nên chúng không bằng nhau.\\nsai do OB là một nửa đường chéo, AC là đường chéo còn lại nên chúng không bằng nhau.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (AC = BD).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4364, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình chữ nhật ABCD, AB = 5cm, chọn khẳng định đúng:","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/997aacd9ede691d2d401a3139bdf8a904d1e50d1.png","width":"271","height":"206","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113742.PNG"}]}', '[{"key":"A","text":"BC = 5cm"},{"key":"B","text":"AC = 5cm"},{"key":"C","text":"AD = 5cm"},{"key":"D","text":"DC = 5cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình chữ nhật ABCD, AB = 5cm, chọn khẳng định đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trong hình chữ nhật ABCD, cạnh đối của cạnh AB là DC nên AB = DC = 5cm ần chọn là: D\\nKết luận: Đáp án đúng là C (AD = 5cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4365, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Chọn phát biểu sai trong các phát biểu sau?","images":[]}', '[{"key":"A","text":"Hình thoi có bốn đỉnh"},{"key":"B","text":"Hình thoi có hai cặp cạnh đối bằng nhau"},{"key":"C","text":"Hình thoi có hai cặp cạnh đối song song"},{"key":"D","text":"Hình có bốn đỉnh là hình thoi"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Chọn phát biểu sai trong các phát biểu sau?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình có bốn đỉnh chưa chắc là hình thoi, ví dụ: => D sai ần chọn là: D\\nKết luận: Đáp án đúng là C (Hình thoi có hai cặp cạnh đối song song).","images":[{"id":"explanation-img-1","alt":"Bài tập trắc nghiệm Bài 2: Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/a79fa949ad397b665b29c2d20c71048eadd5e00a.png","width":"179","height":"151","alt_text":"Bài tập trắc nghiệm Bài 2: Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113743.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4366, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Trong các hình sau, các hình là hình thoi là:","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/dbe9eac03cedbace72974cf0c9e5cd001b91f339.png","width":"370","height":"226","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113744.PNG"}]}', '[{"key":"A","text":"Hình 1, Hình 2"},{"key":"B","text":"Hình 3, Hình 4"},{"key":"C","text":"Hình 1, Hình 3"},{"key":"D","text":"Hình 3, Hình 5"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Trong các hình sau, các hình là hình thoi là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình thoi là hình tứ giác có hai cặp cạnh đối diện song song và bốn cạnh bằng nhau.\\n=> Hình 1 và Hình 3 là hình thoi ần chọn là: C\\nKết luận: Đáp án đúng là C (Hình 1, Hình 3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4367, 281, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Cho hình thoi ABCD có BC = 4cm, khẳng định nào sau đây đúng:","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/e07e4b4f1516947a9bacc949cef73ad8be7550d9.png","width":"262","height":"184","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113745.PNG"}]}', '[{"key":"A","text":"AB = 2cm"},{"key":"B","text":"AD = 8cm"},{"key":"C","text":"DC = 4cm"},{"key":"D","text":"AB = 8cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho hình thoi ABCD có BC = 4cm, khẳng định nào sau đây đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình thoi có bốn cạnh bằng nhau nên AB = BC = DC = AD = 4cm => DC = 4cm ần chọn là: C\\nKết luận: Đáp án đúng là C (DC = 4cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4368, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình thoi ABCD (AC > BD) có AC = 10cm, khẳng định nào sau đây đúng:","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/86bc130430b8974555da198dd880a7ae4c937ef0.png","width":"200","height":"142","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113746.PNG"}]}', '[{"key":"A","text":"OB = 5cm"},{"key":"B","text":"AO = 5cm"},{"key":"C","text":"OD = 5cm"},{"key":"D","text":"OC = 20cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình thoi ABCD (AC > BD) có AC = 10cm, khẳng định nào sau đây đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Do hai đường chéo của hình thoi cắt nhau tại trung điểm của mỗi đường nên AO = OC = 10: 2 = 5cm => B đúng, C sai Vì BD < AC nên OB = OD < 10 2 = 5cm.\\n=> A và C sai.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (OD = 5cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4369, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Trong các hình dưới đây, hình nào là hình thang cân: AAAAAAAA","images":[]}', '[{"key":"A","text":"Hình a"},{"key":"B","text":"Hình b"},{"key":"C","text":"Hình c"},{"key":"D","text":"Hình d"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Trong các hình dưới đây, hình nào là hình thang cân: AAAAAAAA\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Quan sát hình ta thấy Hình b là hình thang cân.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (Hình c).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4370, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Chọn phát biểu sai ?","images":[]}', '[{"key":"A","text":"Hình có bốn đỉnh là hình chữ nhật"},{"key":"B","text":"Hình chữ nhật có bốn đỉnh"},{"key":"C","text":"Hình chữ nhật có hai cặp cạnh đối song song."},{"key":"D","text":"Hình chữ nhật có hai đường chéo bằng nhau"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Chọn phát biểu sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình chữ nhật có bốn đỉnh, hai cặp cạnh đối song song, hai đường chéo bằng nhau.\\n=> , C, D đúng.\\nHình có 4 đỉnh chưa chắc là hình chữ nhật ví dụ: ần chọn là: A\\nKết luận: Đáp án đúng là B (Hình chữ nhật có bốn đỉnh).","images":[{"id":"explanation-img-1","alt":"Bài tập trắc nghiệm Bài 2: Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/3e54955a0c0929ddcc23b17fa4bd4edd131a41a3.png","width":"128","height":"108","alt_text":"Bài tập trắc nghiệm Bài 2: Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113748.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4371, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Diện tích hình thoi có độ dài hai đường chéo là 15cm và 6cm là:","images":[]}', '[{"key":"A","text":"90 cm 2"},{"key":"B","text":"45 dm 2"},{"key":"C","text":"45 cm 2"},{"key":"D","text":"50 cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Diện tích hình thoi có độ dài hai đường chéo là 15cm và 6cm là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Diện tích hình thoi là: S = 15.\\n6 2 = 45 c m 2 ần chọn là: C\\nKết luận: Đáp án đúng là C (45 cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4372, 281, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Nếu hình thoi có độ dài 1 cạnh là a thì:","images":[]}', '[{"key":"A","text":"Chu vi của hình thoi là 4a"},{"key":"B","text":"Chu vi của hình thoi là 6a"},{"key":"C","text":"Chu vi của hình thoi là a 2"},{"key":"D","text":"Chu vi của hình thoi là a + b + c trong đó b và c là độ dài hai đường chéo."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Nếu hình thoi có độ dài 1 cạnh là a thì:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Nếu hình thoi có độ dài 1 cạnh là a thì chu vi của hình thoi là 4a.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (Chu vi của hình thoi là a 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4373, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Một mảnh đất dạng hình thoi có độ dài đường chéo bé là 24m, độ dài đường chéo lớn gấp hai lần đường chéo bé. Diện tích của mảnh đất đó là:","images":[]}', '[{"key":"A","text":"576 m 2"},{"key":"B","text":"144 m 2"},{"key":"C","text":"1152 m 2"},{"key":"D","text":"288 m 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một mảnh đất dạng hình thoi có độ dài đường chéo bé là 24m, độ dài đường chéo lớn gấp hai lần đường chéo bé. Diện tích của mảnh đất đó là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Độ dài đường chéo lớn là: 24.\\n2=48(m) => Diện tích hình thoi là: 24.\\n48 2 = 576 m 2 ần chọn là: A\\nKết luận: Đáp án đúng là C (1152 m 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4374, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Tính diện tích của hình thoi có tổng độ dài hai đường chéo là 30cm và đường chéo lớn hơn đường chéo bé 2cm.","images":[]}', '[{"key":"A","text":"110 cm 2"},{"key":"B","text":"112 cm 2"},{"key":"C","text":"111 cm 2"},{"key":"D","text":"114 cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Tính diện tích của hình thoi có tổng độ dài hai đường chéo là 30cm và đường chéo lớn hơn đường chéo bé 2cm.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Độ dài đường chéo lớn là: (30\\n+ 2): 2 = 16(cm) Độ dài đường chéo bé là: 30 – 16 = 14(cm) Diện tích hình thoi là: 16.\\n14 2 = 112 c m 2 ần chọn là: B\\nKết luận: Đáp án đúng là C (111 cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4375, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Hình thoi A có độ dài hai đường chéo gấp đôi độ dài hai đường chéo của hình thoi B. Hỏi hình thoi A có diện tích gấp mấy lần diện tích hình thoi B?","images":[]}', '[{"key":"A","text":"2 lần"},{"key":"B","text":"3 lần"},{"key":"C","text":"4 lần"},{"key":"D","text":"6 lần"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hình thoi A có độ dài hai đường chéo gấp đôi độ dài hai đường chéo của hình thoi B. Hỏi hình thoi A có diện tích gấp mấy lần diện tích hình thoi B?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Gọi độ dài hai đường chéo của hình thoi B lần lượt là m, n.\\n=> Độ dài hai đường chéo của hình thoi A lần lượt là 2m, 2n.\\nDiện tích của hình thoi A là: 2 m.\\n2 n 2 = 2 m n Diện tích của hình thoi B là: m.\\nn 2 Vậy hình thoi A có diện tích gấp 4 lần diện tích hình thoi B.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (4 lần).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4376, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Một hình thoi có diện tích 12dm 2 , độ dài một đường chéo là 3dm. Tính độ dài đường chéo thứ 2.","images":[]}', '[{"key":"A","text":"2 dm"},{"key":"B","text":"4 dm"},{"key":"C","text":"8 dm"},{"key":"D","text":"10 dm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một hình thoi có diện tích 12dm 2 , độ dài một đường chéo là 3dm. Tính độ dài đường chéo thứ 2.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Độ dài đường chéo thứ 2 là: 2.\\n12: 3 = 8(dm) ần chọn là: C\\nKết luận: Đáp án đúng là C (8 dm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4377, 281, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Một khu đất hình thoi có độ dài cạnh là 12 m. Người ta định xây tường rào xung quanh và bớt lại cửa ra vào rộng 1,5m. Hỏi người ta cần xây bao nhiêu mét tường rào?","images":[{"id":"img-1","alt":"","url":"/uploads/images/crawled/32f29cb1f8a362998da260be39f417d7bcf3b8cc.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/de-thi.png"},{"id":"img-2","alt":"","url":"/uploads/images/crawled/99ab1d22fd95fc929ef8c34dfa92e34fbad71c06.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/giao-an-pp.png"},{"id":"img-3","alt":"","url":"/uploads/images/crawled/d118c48c7c59e39689308157c87cef6474fe7440.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/giao-an-word.png"},{"id":"img-4","alt":"","url":"/uploads/images/crawled/e763791edf79777051baaf626e13df41a05b3a0c.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/bai-tap.png"},{"id":"img-5","alt":"","url":"/uploads/images/crawled/eeb59aba1ef7cfecc1444f766bd3224977efb0d1.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/de-hsg.png"},{"id":"img-6","alt":"","url":"/uploads/images/crawled/9acd9bdc1c01e2e81e39a7a596776ccf1002b4ed.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/trac-nghiem.png"}]}', '[{"key":"A","text":"10,5 m"},{"key":"B","text":"21 m"},{"key":"C","text":"13, 5m"},{"key":"D","text":"46, 5m"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một khu đất hình thoi có độ dài cạnh là 12 m. Người ta định xây tường rào xung quanh và bớt lại cửa ra vào rộng 1,5m. Hỏi người ta cần xây bao nhiêu mét tường rào?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Chu vi hình thoi là: 12.\\n4 = 48(m) - Số mét tường phải xây là: 48 − 1,5 = 46,5(m) ần chọn là: D\\nKết luận: Đáp án đúng là C (13, 5m).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4378, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Phát biểu nào sau đây sai ?","images":[]}', '[{"key":"A","text":"Hình lục giác đều có 6 đỉnh"},{"key":"B","text":"Hình lục giác đều có 6 cạnh"},{"key":"C","text":"Hình lục giác đều có 6 đường chéo chính"},{"key":"D","text":"Hình lục giác đều có 6 góc"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Phát biểu nào sau đây sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Các , B, D đúng.\\nHình lục giác đều có 3 đường chéo chính => sai.\\nần chọn là: C\\nKết luận: Đáp án đúng là A (Hình lục giác đều có 6 đỉnh).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4379, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình lục giác đều MNPQRH, phát biểu nào sai ?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/e64c8d5625e7faeb888aea3c2a4f0f3e44807885.png","width":"243","height":"224","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113711.PNG"},{"id":"img-2","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/0ef8f36f29d5151b946ff88f6dc2360a74cbb4f6.png","width":"243","height":"224","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113713.PNG"}]}', '[{"key":"A","text":"MQ = NR"},{"key":"B","text":"MH = RQ"},{"key":"C","text":"MN = HR"},{"key":"D","text":"MH = MQ"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình lục giác đều MNPQRH, phát biểu nào sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Ta đánh số như hình trên Nhận thấy có các hình tam giác đều là: 1, 2, 3, 4, 5, 6.\\nVậy có 6 tam giác đều.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (MN = HR).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/b17ee7760f6f9722d8a8ee6bbe08fa9a62a0466b.png","width":"170","height":"156","alt_text":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113712.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4380, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Cho hình lục giác đều MNPQRH, phát biểu nào sai ?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/13450d3c3225ce0b13995475b7deeb6bbad0cc48.png","width":"243","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113714.PNG"}]}', '[{"key":"A","text":"6 đỉnh là M, N, P, Q, R, H"},{"key":"B","text":"6 cạnh là MN, NP, PQ, MQ, QR, HM"},{"key":"C","text":"3 đường chéo chính là MQ, HP, RN."},{"key":"D","text":"3 đường chéo chính cắt nhau tại 1 điểm."}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình lục giác đều MNPQRH, phát biểu nào sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: sai do MQ là đường chéo chính, sửa lại: 6 cạnh là MN, NP, PQ, HR, QR, HM ần chọn là: B\\nKết luận: Đáp án đúng là B (6 cạnh là MN, NP, PQ, MQ, QR, HM).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4381, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Cho tam giác đều MNP có MN = 5cm, khẳng định nào sau đây đúng?","images":[]}', '[{"key":"A","text":"NP = 3cm"},{"key":"B","text":"MP = 4cm"},{"key":"C","text":"NP = 6cm"},{"key":"D","text":"MP = 5cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho tam giác đều MNP có MN = 5cm, khẳng định nào sau đây đúng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trong tam giác đều ba cạnh bằng nhau mà MN = 5cm nên ta có: MN = NP = MP = 5cm => Chọn D ần chọn là: D\\nKết luận: Đáp án đúng là C (NP = 6cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4382, 281, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Chọn phát biểu sai :","images":[]}', '[{"key":"A","text":"Tam giác đều có ba cạnh"},{"key":"B","text":"Ba cạnh của tam giác đều bằng nhau"},{"key":"C","text":"Bốn góc của tam giác đều bằng nhau"},{"key":"D","text":"Tam giác đều có ba đỉnh"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Chọn phát biểu sai :\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trong tam giác đều ba góc bằng nhau => sai.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (Bốn góc của tam giác đều bằng nhau).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4383, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Hình dưới đây có mấy hình tam giác?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/54b3ee58384dde4731476c229bc13139cf4a2e9b.png","width":"232","height":"150","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113715.PNG"}]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hình dưới đây có mấy hình tam giác?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình lục giác đều có 6 cạnh ần chọn là: C\\nKết luận: Đáp án đúng là C (3).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/33f4fdd07dc5a5ac386a8db81603d18e59221206.png","width":"180","height":"133","alt_text":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113716.PNG"},{"id":"explanation-img-2","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8e22f3aa9848f9500a9f0b62d4fe50d5c57957e4.png","width":"175","height":"161","alt_text":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113717.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4384, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Cho lục giác đều ABCDEF có AB = 3cm, chọn câu đúng","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/bd76050eaa6ee29a72eb572a873dd15012729fd7.png","width":"363","height":"343","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113718.PNG"}]}', '[{"key":"A","text":"FC = 3cm"},{"key":"B","text":"AD = 3cm"},{"key":"C","text":"BE = 3cm"},{"key":"D","text":"EF = 3cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho lục giác đều ABCDEF có AB = 3cm, chọn câu đúng\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Lục giác đều có các cạnh bằng nhau nên AB = EF = 3cm Các đoạn thẳng AD, BE, FC là các đường chéo chính nên không bằng cạnh bên.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (BE = 3cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4385, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Hình lục giác đều có bao nhiêu đường chéo chính","images":[]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hình lục giác đều có bao nhiêu đường chéo chính\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình lục giác đều có 3 đường chéo chính Ví dụ: Lục giác đều ABCD có các đường chéo chính là: AD, BE, FC ần chọn là: C\\nKết luận: Đáp án đúng là C (3).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/605df7e885902cc0d7a45848bcff00f2729b5689.png","width":"236","height":"207","alt_text":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113719.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4386, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Cho hình vuông MNPQ, khẳng định nào sau đây đúng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/560bffbe7e80254c06bef8f3897e63a7b0ac2864.png","width":"222","height":"201","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113720.PNG"}]}', '[{"key":"A","text":"MN và PQ song song"},{"key":"B","text":"MN và NP song song"},{"key":"C","text":"MQ và PQ song song"},{"key":"D","text":"MN và MQ song song"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình vuông MNPQ, khẳng định nào sau đây đúng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trong hình vuông MNPQ có hai cặp cạnh đối song song với nhau là:\\n+ MN và PQ.\\n+ MQ và NP => đúng.\\nần chọn là: A\\nKết luận: Đáp án đúng là A (MN và PQ song song).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4387, 281, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Cho hình vuông MNPQ, khẳng định nào sau đây sai ?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/9b29625d0e128f3e3fdf00b8f44b6bb8a1d2d633.png","width":"181","height":"167","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113722.PNG"}]}', '[{"key":"A","text":"MN = PQ"},{"key":"B","text":"MQ = QP"},{"key":"C","text":"MN = NP"},{"key":"D","text":"MN = MP"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho hình vuông MNPQ, khẳng định nào sau đây sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình vuông MNPQ có: MN = NP = PQ = MQ => , B, C đúng.\\nsai do MN là cạnh của hình vuông, MP là đường chéo nên MN = MP là sai.\\nần chọn là: D\\nKết luận: Đáp án đúng là A (MN = PQ).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4388, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Chọn phát biểu sai ?","images":[]}', '[{"key":"A","text":"Hình vuông có bốn cạnh bằng nhau"},{"key":"B","text":"Hình vuông có bốn cặp cạnh đối song song"},{"key":"C","text":"Hình vuông có hai đường chéo bằng nhau"},{"key":"D","text":"Hình vuông có bốn góc bằng nhau"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Chọn phát biểu sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình vuông có hai cặp cạnh đối song song => sai.\\nần chọn là: B\\nKết luận: Đáp án đúng là B (Hình vuông có bốn cặp cạnh đối song song).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4389, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Hình dưới đây có tất cả bao nhiêu hình vuông?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/288c8550dab857988805822160b93daa6a0587ac.png","width":"211","height":"212","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113721.PNG"}]}', '[{"key":"A","text":"9"},{"key":"B","text":"14"},{"key":"C","text":"10"},{"key":"D","text":"13"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hình dưới đây có tất cả bao nhiêu hình vuông?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Ta đánh số như hình trên:\\n+ 9 hình vuông nhỏ là: 1, 2, 3, 4, 5, 6, 7, 8, 9.\\n+ 4 hình vuông được gép từ bốn hình vuông nhỏ là: 1245, 2356, 4578, 5689.\\n+ 1 hình vuông lớn được ghép từ 9 hình vuông nhỏ.\\nVậy có tất cả 9+4+1=14 hình vuông.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (10).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/244453990254ba60b475823eff20f097d328ea05.png","width":"218","height":"225","alt_text":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113723.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4390, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Cho hình vuông ABCD có chu vi bằng 28cm. Diện tích hình vuông ABCD là:","images":[]}', '[{"key":"A","text":"49cm"},{"key":"B","text":"28cm 2"},{"key":"C","text":"49cm 2"},{"key":"D","text":"112cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho hình vuông ABCD có chu vi bằng 28cm. Diện tích hình vuông ABCD là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Ta có cạnh AB = BC = CD = DA = 28: 4 = 7 cm.\\n- Diện tích hình vuông ABCD = 7.\\n7 = 49 cm 2.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (49cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4391, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Người ta uốn một đoạn dây đồng vừa đủ thành một hình vuông cạnh 15cm. Tính độ dài đoạn dây đồng đó.","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/50415b5f3f55d07d286448a4b6fce4ff94f1d4a7.png","width":"189","height":"202","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113724.PNG"}]}', '[{"key":"A","text":"60 cm"},{"key":"B","text":"15 cm"},{"key":"C","text":"60 cm 2"},{"key":"D","text":"225 cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Người ta uốn một đoạn dây đồng vừa đủ thành một hình vuông cạnh 15cm. Tính độ dài đoạn dây đồng đó.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Độ dài đoạn dây đồng đó là: 15.\\n4 = 60 (cm) ần chọn là: A\\nKết luận: Đáp án đúng là C (60 cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4392, 281, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Mỗi viên gạch hoa hình vuông có cạnh 20 cm. Tính chu vi hình vuông ghép bởi 4 viên gạch hoa như hình vẽ dưới đây:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/e998fc7eeccdfdffa2bf334c5708a21cce7643b6.png","width":"152","height":"153","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113725.PNG"}]}', '[{"key":"A","text":"80 cm"},{"key":"B","text":"160 cm"},{"key":"C","text":"400 cm"},{"key":"D","text":"40 cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Mỗi viên gạch hoa hình vuông có cạnh 20 cm. Tính chu vi hình vuông ghép bởi 4 viên gạch hoa như hình vẽ dưới đây:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Cạnh của hình vuông là: 20\\n+ 20 = 40 (cm) Chu vi hình vuông là: 40.\\n4 = 160 (cm) ần chọn là: B\\nKết luận: Đáp án đúng là C (400 cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4393, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Một hồ nước hình vuông cạnh 30 m. Tính chu vi hồ nước đó.","images":[]}', '[{"key":"A","text":"120 m"},{"key":"B","text":"60 m"},{"key":"C","text":"120 dm"},{"key":"D","text":"900 m"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một hồ nước hình vuông cạnh 30 m. Tính chu vi hồ nước đó.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Chu vi hồ nước là: 30.\\n4 = 120 (m) ần chọn là: A\\nKết luận: Đáp án đúng là C (120 dm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4394, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Cần bao nhiêu viên gạch hình vuông cạnh 50 cm để lát kín căn phòng có nền là hình vuông có cạnh 12 m?","images":[]}', '[{"key":"A","text":"240 viên"},{"key":"B","text":"144 viên"},{"key":"C","text":"24 viên"},{"key":"D","text":"576 viên"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cần bao nhiêu viên gạch hình vuông cạnh 50 cm để lát kín căn phòng có nền là hình vuông có cạnh 12 m?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Đổi 50 cm = 0,5 m.\\nDiện tích một viên gạch là: 0,5.\\n0,5 = 0,25(m 2 ) Diện tích căn phòng là: 12.\\n12 = 144(m 2 ) Số viên gạch để lát kín căn phòng là: 144: 0,25 = 576 (viên) ần chọn là: D\\nKết luận: Đáp án đúng là C (24 viên).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4395, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Chu vi và diện tích hình vuông có cạnh là 7 cm lần lượt là","images":[]}', '[{"key":"A","text":"28cm; 49cm"},{"key":"B","text":"28cm 2 ; 49cm"},{"key":"C","text":"49cm; 28cm 2"},{"key":"D","text":"28cm; 49cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Chu vi và diện tích hình vuông có cạnh là 7 cm lần lượt là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Chu vi hình vuông là: 4.\\n7 = 28 (cm) Diện tích hình vuông là: 7 2 = 49(cm 2 ) ần chọn là: D\\nKết luận: Đáp án đúng là C (49cm; 28cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4396, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Người ta mở rộng một cái ao hình vuông để được một cái ao hình chữ nhật có chiều dài gấp 2 lần chiều rộng. Sau khi mở rộng, diện tích ao tăng thêm 600m 2 và diện tích ao mới gấp 4 lần ao cũ. Hỏi phải dùng bao nhiêu chiếc cọc để đủ rào xung quanh ao mới? Biết rằng cọc nọ cách cọc kia 1m và ở một góc ao người ta để lối lên xuống rộng 3m.","images":[]}', '[{"key":"A","text":"120"},{"key":"B","text":"117"},{"key":"C","text":"119"},{"key":"D","text":"122"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Người ta mở rộng một cái ao hình vuông để được một cái ao hình chữ nhật có chiều dài gấp 2 lần chiều rộng. Sau khi mở rộng, diện tích ao tăng thêm 600m 2 và diện tích ao mới gấp 4 lần ao cũ. Hỏi phải dùng bao nhiêu chiếc cọc để đủ rào xung quanh ao mới? Biết rằng cọc nọ cách cọc kia 1m và ở một góc ao người ta để lối lên xuống rộng 3m.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Ta có sơ đồ: Diện tích ao mới là: 600: (4 – 1).\\n4 = 800 (m 2 ) Ta chia ao mới thành hai hình vuông có diện tích bằng nhau như hình vẽ.\\nDiện tích một hình vuông là: 800: 2 = 400 (m 2 ) Vì 400 = 20.\\n20 Cạnh của hình vuông hay chiều rộng của ao mới là 20m Chiều dài của ao mới là: 20.\\n2 = 40 (m) Chu vi áo mới là: (40\\n+ 20).\\n2 = 120(m) Số cọc để rào xung quanh ao mới là: (120 – 3): 1 = 117 (chiếc) ần chọn là: B\\nKết luận: Đáp án đúng là C (119).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/ad00118428a63858c4fcf6ede27897630913359d.png","width":"344","height":"89","alt_text":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113727.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4397, 281, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Sân trường em hình vuông. Để tăng thêm diện tích nhà trường mở rộng về mỗi phía 4m thì diện tích tăng thêm 192m 2 . Hỏi trước đây sân trường em có diện tích là bao nhiêu m 2 ?","images":[]}', '[{"key":"A","text":"16 m 2"},{"key":"B","text":"32 m 2"},{"key":"C","text":"64 m 2"},{"key":"D","text":"128 m 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Sân trường em hình vuông. Để tăng thêm diện tích nhà trường mở rộng về mỗi phía 4m thì diện tích tăng thêm 192m 2 . Hỏi trước đây sân trường em có diện tích là bao nhiêu m 2 ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Diện tích tăng thêm bằng diện tích 4 hình vuông nhỏ cạnh bằng 4m và 4 hình chữ nhật có 1 cạnh bằng 4 m và 1 cạnh bằng cạnh hình vuông Diện tích 4 hình vuông nhỏ là: 4.\\n(4.\\n4) = 64 m 2 Diện tích 4 hình chữ nhật là: 192 - 64 = 128 m 2 Diện tích 1 hình chữ nhật là 128: 4 = 32 m 2 Cạnh hình vuông đã cho là: 32: 4 = 8 m Diện tích sân trường lúc chưa mở rộng là: 8.\\n8 = 64 m 2 ần chọn là: C\\nKết luận: Đáp án đúng là C (64 m 2).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/e410ac03010af4870672c0be1c63df2662774456.png","width":"197","height":"181","alt_text":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113726.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4398, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Cho chu vi tứ giác ACDE bằng 45 cm, chu vi tam giác ABC bằng 32 cm, AC = 10 cm. Khi đó chu vi hình ABCDE là:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/76174324a30461f554ff49262024f62ad7ce85ce.png","width":"195","height":"161","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113728.PNG"}]}', '[{"key":"A","text":"77 cm"},{"key":"B","text":"67 cm"},{"key":"C","text":"57 cm"},{"key":"D","text":"87 cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho chu vi tứ giác ACDE bằng 45 cm, chu vi tam giác ABC bằng 32 cm, AC = 10 cm. Khi đó chu vi hình ABCDE là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng chu vi tứ giác ACDE và tam giác ABC là: 45\\n+ 32 = 77 (cm) Trong tổng trên cạnh AC đã được tính hai lần, mà hình ABCDE không chứa cạnh AC nên: Chu vi hình ABCDE là: 77 − 2.\\n10 = 57 (cm) ần chọn là: C\\nKết luận: Đáp án đúng là C (57 cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4399, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Cho diện tích tứ giác (1) bằng 20cm 2 , Diện tích tam giác (2) bằng 16cm 2 , Khi đó diện tích của hình trên bằng:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/4188de3c99f3ada991065965f6736e5a42d9e3ac.png","width":"209","height":"166","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-113729.PNG"}]}', '[{"key":"A","text":"36cm"},{"key":"B","text":"36dm 2"},{"key":"C","text":"26cm 2"},{"key":"D","text":"36cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho diện tích tứ giác (1) bằng 20cm 2 , Diện tích tam giác (2) bằng 16cm 2 , Khi đó diện tích của hình trên bằng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Diện tích hình đã cho là: 20\\n+ 16 = 36 (cm 2 ).\\nần chọn là: D\\nKết luận: Đáp án đúng là C (26cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4400, 281, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Cho tam giác ABC có độ dài cạnh AB bằng 12 cm.Tổng độ dài hai cạnh BC và CA hơn độ dài cạnh AB là 7cm, chu vi tam giác ABC bằng:","images":[]}', '[{"key":"A","text":"19 cm"},{"key":"B","text":"31 cm"},{"key":"C","text":"17 cm"},{"key":"D","text":"31 dm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho tam giác ABC có độ dài cạnh AB bằng 12 cm.Tổng độ dài hai cạnh BC và CA hơn độ dài cạnh AB là 7cm, chu vi tam giác ABC bằng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Tổng độ dài hai cạnh BC và CA bằng: 12\\n+ 7 = 19 (cm) - Chu vi tam giác ABC: 12\\n+ 19 = 31 (cm) ần chọn là: B\\nKết luận: Đáp án đúng là C (17 cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4401, 281, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Tìm chu vi hình tam giác ABC có ba cạnh bằng nhau, biết cạnh AC = 5 cm.","images":[]}', '[{"key":"A","text":"15 dm"},{"key":"B","text":"10 cm"},{"key":"C","text":"15 cm"},{"key":"D","text":"20 cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Tìm chu vi hình tam giác ABC có ba cạnh bằng nhau, biết cạnh AC = 5 cm.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Do hình tam giác ABC có bốn cạnh bằng nhau và AC = 5 cm nên: Chu vi tam giác ABC là: 5\\n+ 5\\n+ 5 = 15(cm) Cách khác: Chu vi tam giác ABC là: 5.\\n3 = 15 (cm).\\nần chọn là: C\\nKết luận: Đáp án đúng là C (15 cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4402, 281, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Tìm chu vi hình tứ giác MNPQ có bốn cạnh bằng nhau, biết cạnh MN = 4cm.","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Tam giác đều. Hình vuông. Lục giác đều (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/27652c8aa133ce76b62803b45c5b428e4785200f.png","width":"177","height":"165","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-tam-giac-deu-hinh-vuong-luc-giac-deu-338090.PNG"}]}', '[{"key":"A","text":"16 dm"},{"key":"B","text":"16 mm"},{"key":"C","text":"12 cm"},{"key":"D","text":"16 cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Tìm chu vi hình tứ giác MNPQ có bốn cạnh bằng nhau, biết cạnh MN = 4cm.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: a) Đúng.\\nCác cạnh của tam giác A B C là A B, A C, B C.\\nb) Đúng.\\nVì tam giác A B C là tam giác đều nên A B = B C = A C = 7 cm.\\nc) Đúng.\\nTam giác A B C là tam giác đều nên góc A = góc B = góc C = $60^\\\\circ$.\\nd) Sai.\\nVì tam giác A B C đều nên A B = B C = A C = 7 cm.\\nDo đó, tổng ba cạnh của tam giác A B C bằng 7\\n+ 7\\n+ 7 = 21 cm.\\nKết luận: Đáp án đúng là C (12 cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4403, 282, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Cho hình chữ nhật ABCD, phát biểu nào đúng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/234d0dd01ff6dd821ae06907ce16c1939f3b52fe.png","width":"254","height":"184","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113741.PNG"}]}', '[{"key":"A","text":"AB = AC"},{"key":"B","text":"AC = DO"},{"key":"C","text":"AC = BD"},{"key":"D","text":"OB = AC"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho hình chữ nhật ABCD, phát biểu nào đúng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trong hình chữ nhật hai đường chéo bằng nhau nên AC = BD => đúng sai do AB là cạnh, AC là đường chéo nên chúng không bằng nhau.\\nsai do AC là đường chéo, DO là một nửa đường chéo còn lại nên chúng không bằng nhau.\\nsai do OB là một nửa đường chéo, AC là đường chéo còn lại nên chúng không bằng nhau.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (AC = BD).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4404, 282, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình chữ nhật ABCD, AB = 5cm, chọn khẳng định đúng:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/997aacd9ede691d2d401a3139bdf8a904d1e50d1.png","width":"271","height":"206","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113742.PNG"}]}', '[{"key":"A","text":"BC = 5cm"},{"key":"B","text":"AC = 5cm"},{"key":"C","text":"AD = 5cm"},{"key":"D","text":"DC = 5cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình chữ nhật ABCD, AB = 5cm, chọn khẳng định đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trong hình chữ nhật ABCD, cạnh đối của cạnh AB là DC nên AB = DC = 5cm ần chọn là: D\\nKết luận: Đáp án đúng là C (AD = 5cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4405, 282, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Chọn phát biểu sai trong các phát biểu sau?","images":[]}', '[{"key":"A","text":"Hình thoi có bốn đỉnh"},{"key":"B","text":"Hình thoi có hai cặp cạnh đối bằng nhau"},{"key":"C","text":"Hình thoi có hai cặp cạnh đối song song"},{"key":"D","text":"Hình có bốn đỉnh là hình thoi"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Chọn phát biểu sai trong các phát biểu sau?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình có bốn đỉnh chưa chắc là hình thoi, ví dụ: => D sai ần chọn là: D\\nKết luận: Đáp án đúng là C (Hình thoi có hai cặp cạnh đối song song).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/a79fa949ad397b665b29c2d20c71048eadd5e00a.png","width":"179","height":"151","alt_text":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113743.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4406, 282, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Trong các hình sau, các hình là hình thoi là:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/dbe9eac03cedbace72974cf0c9e5cd001b91f339.png","width":"370","height":"226","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113744.PNG"}]}', '[{"key":"A","text":"Hình 1, Hình 2"},{"key":"B","text":"Hình 3, Hình 4"},{"key":"C","text":"Hình 1, Hình 3"},{"key":"D","text":"Hình 3, Hình 5"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Trong các hình sau, các hình là hình thoi là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình thoi là hình tứ giác có hai cặp cạnh đối diện song song và bốn cạnh bằng nhau.\\n=> Hình 1 và Hình 3 là hình thoi ần chọn là: C\\nKết luận: Đáp án đúng là C (Hình 1, Hình 3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4407, 282, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Cho hình thoi ABCD có BC = 4cm, khẳng định nào sau đây đúng:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/e07e4b4f1516947a9bacc949cef73ad8be7550d9.png","width":"262","height":"184","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113745.PNG"}]}', '[{"key":"A","text":"AB = 2cm"},{"key":"B","text":"AD = 8cm"},{"key":"C","text":"DC = 4cm"},{"key":"D","text":"AB = 8cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho hình thoi ABCD có BC = 4cm, khẳng định nào sau đây đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình thoi có bốn cạnh bằng nhau nên AB = BC = DC = AD = 4cm => DC = 4cm ần chọn là: C\\nKết luận: Đáp án đúng là C (DC = 4cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4408, 282, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình thoi ABCD (AC > BD) có AC = 10cm, khẳng định nào sau đây đúng:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/86bc130430b8974555da198dd880a7ae4c937ef0.png","width":"200","height":"142","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113746.PNG"}]}', '[{"key":"A","text":"OB = 5cm"},{"key":"B","text":"AO = 5cm"},{"key":"C","text":"OD = 5cm"},{"key":"D","text":"OC = 20cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình thoi ABCD (AC > BD) có AC = 10cm, khẳng định nào sau đây đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Do hai đường chéo của hình thoi cắt nhau tại trung điểm của mỗi đường nên AO = OC = 10: 2 = 5cm => B đúng, C sai Vì BD < AC nên OB = OD < 10 2 = 5cm.\\n=> A và C sai.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (OD = 5cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4409, 282, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Trong các hình dưới đây, hình nào là hình thang cân: AAAAAAAA","images":[]}', '[{"key":"A","text":"Hình a"},{"key":"B","text":"Hình b"},{"key":"C","text":"Hình c"},{"key":"D","text":"Hình d"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Trong các hình dưới đây, hình nào là hình thang cân: AAAAAAAA\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Quan sát hình ta thấy Hình b là hình thang cân.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (Hình c).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4410, 282, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Chọn phát biểu sai ?","images":[]}', '[{"key":"A","text":"Hình có bốn đỉnh là hình chữ nhật"},{"key":"B","text":"Hình chữ nhật có bốn đỉnh"},{"key":"C","text":"Hình chữ nhật có hai cặp cạnh đối song song."},{"key":"D","text":"Hình chữ nhật có hai đường chéo bằng nhau"}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Chọn phát biểu sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình chữ nhật có bốn đỉnh, hai cặp cạnh đối song song, hai đường chéo bằng nhau.\\n=> , C, D đúng.\\nHình có 4 đỉnh chưa chắc là hình chữ nhật ví dụ: ần chọn là: A\\nKết luận: Đáp án đúng là B (Hình chữ nhật có bốn đỉnh).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/3e54955a0c0929ddcc23b17fa4bd4edd131a41a3.png","width":"128","height":"108","alt_text":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113748.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4411, 282, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Diện tích hình thoi có độ dài hai đường chéo là 15cm và 6cm là:","images":[]}', '[{"key":"A","text":"90 cm 2"},{"key":"B","text":"45 dm 2"},{"key":"C","text":"45 cm 2"},{"key":"D","text":"50 cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Diện tích hình thoi có độ dài hai đường chéo là 15cm và 6cm là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Diện tích hình thoi là: S = 15.\\n6 2 = 45 c m 2 ần chọn là: C\\nKết luận: Đáp án đúng là C (45 cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4412, 282, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Nếu hình thoi có độ dài 1 cạnh là a thì:","images":[]}', '[{"key":"A","text":"Chu vi của hình thoi là 4a"},{"key":"B","text":"Chu vi của hình thoi là 6a"},{"key":"C","text":"Chu vi của hình thoi là a 2"},{"key":"D","text":"Chu vi của hình thoi là a + b + c trong đó b và c là độ dài hai đường chéo."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Nếu hình thoi có độ dài 1 cạnh là a thì:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Nếu hình thoi có độ dài 1 cạnh là a thì chu vi của hình thoi là 4a.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (Chu vi của hình thoi là a 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4413, 282, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Một mảnh đất dạng hình thoi có độ dài đường chéo bé là 24m, độ dài đường chéo lớn gấp hai lần đường chéo bé. Diện tích của mảnh đất đó là:","images":[]}', '[{"key":"A","text":"576 m 2"},{"key":"B","text":"144 m 2"},{"key":"C","text":"1152 m 2"},{"key":"D","text":"288 m 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một mảnh đất dạng hình thoi có độ dài đường chéo bé là 24m, độ dài đường chéo lớn gấp hai lần đường chéo bé. Diện tích của mảnh đất đó là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Độ dài đường chéo lớn là: 24.\\n2=48(m) => Diện tích hình thoi là: 24.\\n48 2 = 576 m 2 ần chọn là: A\\nKết luận: Đáp án đúng là C (1152 m 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4414, 282, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Tính diện tích của hình thoi có tổng độ dài hai đường chéo là 30cm và đường chéo lớn hơn đường chéo bé 2cm.","images":[]}', '[{"key":"A","text":"110 cm 2"},{"key":"B","text":"112 cm 2"},{"key":"C","text":"111 cm 2"},{"key":"D","text":"114 cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Tính diện tích của hình thoi có tổng độ dài hai đường chéo là 30cm và đường chéo lớn hơn đường chéo bé 2cm.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Độ dài đường chéo lớn là: (30\\n+ 2): 2 = 16(cm) Độ dài đường chéo bé là: 30 – 16 = 14(cm) Diện tích hình thoi là: 16.\\n14 2 = 112 c m 2 ần chọn là: B\\nKết luận: Đáp án đúng là C (111 cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4415, 282, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Hình thoi A có độ dài hai đường chéo gấp đôi độ dài hai đường chéo của hình thoi B. Hỏi hình thoi A có diện tích gấp mấy lần diện tích hình thoi B?","images":[]}', '[{"key":"A","text":"2 lần"},{"key":"B","text":"3 lần"},{"key":"C","text":"4 lần"},{"key":"D","text":"6 lần"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hình thoi A có độ dài hai đường chéo gấp đôi độ dài hai đường chéo của hình thoi B. Hỏi hình thoi A có diện tích gấp mấy lần diện tích hình thoi B?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Gọi độ dài hai đường chéo của hình thoi B lần lượt là m, n.\\n=> Độ dài hai đường chéo của hình thoi A lần lượt là 2m, 2n.\\nDiện tích của hình thoi A là: 2 m.\\n2 n 2 = 2 m n Diện tích của hình thoi B là: m.\\nn 2 Vậy hình thoi A có diện tích gấp 4 lần diện tích hình thoi B.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (4 lần).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4416, 282, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Một hình thoi có diện tích 12dm 2 , độ dài một đường chéo là 3dm. Tính độ dài đường chéo thứ 2.","images":[]}', '[{"key":"A","text":"2 dm"},{"key":"B","text":"4 dm"},{"key":"C","text":"8 dm"},{"key":"D","text":"10 dm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một hình thoi có diện tích 12dm 2 , độ dài một đường chéo là 3dm. Tính độ dài đường chéo thứ 2.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Độ dài đường chéo thứ 2 là: 2.\\n12: 3 = 8(dm) ần chọn là: C\\nKết luận: Đáp án đúng là C (8 dm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4417, 282, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Một khu đất hình thoi có độ dài cạnh là 12 m. Người ta định xây tường rào xung quanh và bớt lại cửa ra vào rộng 1,5m. Hỏi người ta cần xây bao nhiêu mét tường rào?","images":[]}', '[{"key":"A","text":"10,5 m"},{"key":"B","text":"21 m"},{"key":"C","text":"13, 5m"},{"key":"D","text":"46, 5m"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một khu đất hình thoi có độ dài cạnh là 12 m. Người ta định xây tường rào xung quanh và bớt lại cửa ra vào rộng 1,5m. Hỏi người ta cần xây bao nhiêu mét tường rào?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Chu vi hình thoi là: 12.\\n4 = 48(m) - Số mét tường phải xây là: 48 − 1,5 = 46,5(m) ần chọn là: D\\nKết luận: Đáp án đúng là C (13, 5m).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4418, 282, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Một thửa ruộng hình chữ nhật có chu vi 200 m. Chiều dài hình chữ nhật hơn hai lần chiều rộng là 10m. Tính diện tích hình chữ nhật đó.","images":[]}', '[{"key":"A","text":"1200 m 2"},{"key":"B","text":"2100 m 2"},{"key":"C","text":"200 m 2"},{"key":"D","text":"100 m 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một thửa ruộng hình chữ nhật có chu vi 200 m. Chiều dài hình chữ nhật hơn hai lần chiều rộng là 10m. Tính diện tích hình chữ nhật đó.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Nửa chu vi thửa ruộng là: 200: 2 = 100 (m) Chiều rộng của thửa ruộng là: (100 - 10): 3 = 30 (m) Chiều dài của thửa ruộng là: 100 - 30 = 70 (m) Diện tích hình chữ nhật là: 70.\\n30 = 2100 (m 2 ) ần chọn là: B\\nKết luận: Đáp án đúng là C (200 m 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4419, 282, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Tính diện tích mảnh vườn được tạo bởi 1 hình vuông và 1 hình chữ nhật như hình vẽ:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/db316132ef59a6e26c2360ecae6ab96468222646.png","width":"167","height":"161","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113749.PNG"}]}', '[{"key":"A","text":"4 m 2"},{"key":"B","text":"16 m 2"},{"key":"C","text":"20 m 2"},{"key":"D","text":"24 m 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Tính diện tích mảnh vườn được tạo bởi 1 hình vuông và 1 hình chữ nhật như hình vẽ:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Diện tích phần đất hình vuông là: 2 2 = 4(m 2 ) Diện tích phần đất hình chữ nhật là: 8.\\n2 = 16(m 2 ) Diện tích mảnh vườn là: 4\\n+ 16 = 20(m 2 ) ần chọn là: C\\nKết luận: Đáp án đúng là C (20 m 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4420, 282, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Một miếng bìa hình chữ nhật có chu vi 96 cm, nếu giảm chiều dài 13 cm và giảm chiều rộng 5 cm thì được một hình vuông. Hỏi miếng bìa hình chữ nhật đó có diện tích bằng bao nhiêu?","images":[]}', '[{"key":"A","text":"560cm 2"},{"key":"B","text":"560dm 2"},{"key":"C","text":"56dm"},{"key":"D","text":"65cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một miếng bìa hình chữ nhật có chu vi 96 cm, nếu giảm chiều dài 13 cm và giảm chiều rộng 5 cm thì được một hình vuông. Hỏi miếng bìa hình chữ nhật đó có diện tích bằng bao nhiêu?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Miếng bìa hình chữ nhật có chiều dài hơn chiều rộng là: 13 – 5 = 8 (cm) Nửa chu vi hình chữ nhật: 96: 2 = 48 (cm) Chiều rộng hình chữ nhật là: (48 – 8): 2 = 20 (cm) Chiều dài hình chữ nhật là: 20\\n+ 8 = 28 (cm) Diện tích miếng bìa hình chữ nhật là: 28.\\n20 = 560 (cm 2 ) Đáp số: 560 (cm 2 ) ần chọn là: A\\nKết luận: Đáp án đúng là C (56dm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4421, 282, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Diện tích của một hình chữ nhật có chiều rộng 26 cm và có chu vi gấp 3 lần chiều dài là:","images":[]}', '[{"key":"A","text":"2028cm"},{"key":"B","text":"1352cm"},{"key":"C","text":"2028cm 2"},{"key":"D","text":"1352cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Diện tích của một hình chữ nhật có chiều rộng 26 cm và có chu vi gấp 3 lần chiều dài là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Theo đề bài: Chu vi = 3.\\nchiều dài => Chu vi = 2.\\nchiều dài\\n+ chiều dài.\\nMà: Chu vi = 2.\\nchiều dài\\n+ 2.\\nchiều rộng => Chiều dài = 2.\\nchiều rộng.\\nSuy ra chiều dài hình chữ nhật là: 2.\\n26 = 52 cm.\\nDiện tích hình chữ nhật là: 52.\\n26 = 1352 (cm 2 ).\\nần chọn là: D\\nKết luận: Đáp án đúng là C (2028cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4422, 282, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Một miếng đất hình chữ nhật có chiều dài 64 m, chiều rộng 34 m. Người ta giảm chiều dài và tăng chiều rộng để miếng đất là hình vuông, biết phần diện tích giảm theo chiều dài là 272. Tìm phần diện tích tăng thêm theo chiều rộng.","images":[]}', '[{"key":"A","text":"176m 2"},{"key":"B","text":"2176m 2"},{"key":"C","text":"1232m 2"},{"key":"D","text":"3136m 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một miếng đất hình chữ nhật có chiều dài 64 m, chiều rộng 34 m. Người ta giảm chiều dài và tăng chiều rộng để miếng đất là hình vuông, biết phần diện tích giảm theo chiều dài là 272. Tìm phần diện tích tăng thêm theo chiều rộng.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Ta có hình vẽ minh họa sau: Số đo bị giảm của chiều dài miếng đất là: 272: 34 = 8 (m) Cạnh của miếng đất hình vuông là: 64 – 8 = 56 (m) Chiều rộng miếng đất được tăng thêm số mét là: 56 – 34 = 22 (m) Diện tích phần tăng theo chiều rộng miếng đất là: 56.\\n22 = 1232 (m 2 ) ần chọn là: C\\nKết luận: Đáp án đúng là C (1232m 2).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","url":"/uploads/images/crawled/050a5fd799cde7b4ca09434b0fa6484da1fe88a2.png","width":"285","height":"204","alt_text":"10+ Bài tập trắc nghiệm Hình chữ nhật. Hình thoi (có đáp án) | Toán lớp 6 Cánh diều (ảnh 1)","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-hinh-chu-nhat-hinh-thoi-113750.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4423, 282, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Chu vi và diện tích của hình chữ nhật có chiều rộng bằng 15cm và nửa chu vi bằng 40cm?","images":[]}', '[{"key":"A","text":"80 dm và 600 dm 2"},{"key":"B","text":"80 dm và 375 dm 2"},{"key":"C","text":"40 dm và 375 dm 2"},{"key":"D","text":"80 cm và 375cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Chu vi và diện tích của hình chữ nhật có chiều rộng bằng 15cm và nửa chu vi bằng 40cm?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Chu vi của hình chữ nhật là: 40.\\n2 = 80(cm) Chiều dài của hình chữ nhật là: 40 – 15 = 25(cm) Diện tích của hình chữ nhật là: 15.\\n25 = 375(cm 2 ) Vậy chu vi và diện tích hình chữ nhật lần lượt là: 80 cm và 375cm 2 ần chọn là: D\\nKết luận: Đáp án đúng là C (40 dm và 375 dm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4424, 282, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Diện tích hình chữ nhật ABCD có chiều dài AB là 15cm và chiều rộng BD là 8cm là:","images":[]}', '[{"key":"A","text":"23cm 2"},{"key":"B","text":"46cm 2"},{"key":"C","text":"120cm 2"},{"key":"D","text":"120cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Diện tích hình chữ nhật ABCD có chiều dài AB là 15cm và chiều rộng BD là 8cm là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Diện tích hình chữ nhật ABCD là: 15.\\n8=120(cm 2 ).\\nần chọn là: C\\nKết luận: Đáp án đúng là C (120cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4425, 283, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Cho hình bình hành ABCD ABCD , cặp cạnh song song với nhau là:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình bình hành (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/08dd5cde7cd9b895a16da07d17ec8dab073b6fb3.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-3-hinh-binh-hanh-113766.PNG"}]}', '[{"key":"A","text":"AB và AD"},{"key":"B","text":"AD và DC"},{"key":"C","text":"BC và AD"},{"key":"D","text":"DC và BC"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình bình hành ABCD ABCD , cặp cạnh song song với nhau là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Vì trong hình bình hành hai cặp cạnh đối diện song song với nhau nên BC song song với AD => C đúng ần chọn là: C\\nKết luận: Đáp án đúng là C (BC và AD).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4426, 283, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Trong các hình dưới đây, hình nào là hình bình hành?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình bình hành (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/34e947a4aa1bc23f1092f399eff13386db6d5c2f.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-3-hinh-binh-hanh-113767.PNG"}]}', '[{"key":"A","text":"Hình 1, hình 2, hình 4"},{"key":"B","text":"Hình 2, hình 3, hình 4"},{"key":"C","text":"Hình 1, hình 4, hình 5"},{"key":"D","text":"Hình 1, hình 2, hình 5"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các hình dưới đây, hình nào là hình bình hành?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Các hình là hình bình hành là: Hình 1, hình 2, hình 5 ần chọn là: D\\nKết luận: Đáp án đúng là C (Hình 1, hình 4, hình 5).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4427, 283, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Trong những khẳng định sau, khẳng định nào sai ?","images":[]}', '[{"key":"A","text":"Hình bình hành có 4 đỉnh"},{"key":"B","text":"Hình bình hành có bốn cạnh"},{"key":"C","text":"Hình có bốn đỉnh là hình bình hành"},{"key":"D","text":"Hình bình hành có hai cạnh đối song song."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong những khẳng định sau, khẳng định nào sai ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình bình hành có 4 đỉnh, có bốn cạnh, hai cạnh đối song song => A, B, D đúng Hình có bốn đỉnh chưa chắc là hình bình hành, ví dụ: ần chọn là: C\\nKết luận: Đáp án đúng là C (Hình có bốn đỉnh là hình bình hành).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình bình hành (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8c5cd22bfc01dda9d6030f9948965eaf1dad97cd.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Hình bình hành (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-3-hinh-binh-hanh-113768.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4428, 283, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình bình hành ABCD , cặp cạnh bằng nhau là:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình bình hành (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/9f37e64493719a6246f71ebb6b9d60279974c249.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-3-hinh-binh-hanh-113769.PNG"}]}', '[{"key":"A","text":"AB và AD"},{"key":"B","text":"AD và DC"},{"key":"C","text":"BC và AB"},{"key":"D","text":"DC và AB"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình bình hành ABCD , cặp cạnh bằng nhau là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Vì trong hình bình hành hai cặp cạnh đối diện bằng nhau nên DC = AB.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (BC và AB).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4429, 283, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Trong các hình dưới đây, hình nào là hình bình hành?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình bình hành (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/63bf668bf477bf110af63c58dfb42a48e7f67b7a.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-3-hinh-binh-hanh-113770.PNG"}]}', '[{"key":"A","text":"Hình 2"},{"key":"B","text":"Hình 2 và hình 3"},{"key":"C","text":"Hình 1, hình 2, hình 5"},{"key":"D","text":"Hình 1, hình 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các hình dưới đây, hình nào là hình bình hành?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Do hình bình hành là tứ giác có hai cặp cạnh đối diện song song và bằng nhau.\\n=> Các hình là hình bình hành là: Hình 1, hình 2, hình 5.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (Hình 1, hình 2, hình 5).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4430, 283, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình bình hành ABCD có chiều cao hạ xuống cạnh CD là 5 cm, chiều dài CD là 15 cm, diện tích hình bình hành ABCD là:","images":[]}', '[{"key":"A","text":"20 cm 2"},{"key":"B","text":"75 cm"},{"key":"C","text":"20 cm"},{"key":"D","text":"75 cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình bình hành ABCD có chiều cao hạ xuống cạnh CD là 5 cm, chiều dài CD là 15 cm, diện tích hình bình hành ABCD là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình bình hành ABCD có chiều cao bằng 5 cm và độ dài cạnh đáy bằng 15 cm nên: Diện tích hình bình hành ABCD là: 5.\\n15 = 75 cm 2 ần chọn là: D\\nKết luận: Đáp án đúng là C (20 cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4431, 283, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Mảnh đất hình bình hành có cạnh đáy là 47 m, mở rộng mảnh đất bằng cách tăng các cạnh đáy của hình bình hành này thêm 7 m thì được mảnh đất hình bình hành mới có diện tích hơn diện tích mảnh đất ban đầu là 189 m 2 . Hãy tính diện tích mảnh đất ban đầu.","images":[]}', '[{"key":"A","text":"1296 m 2"},{"key":"B","text":"1926 m 2"},{"key":"C","text":"1629 m 2"},{"key":"D","text":"1269 m 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Mảnh đất hình bình hành có cạnh đáy là 47 m, mở rộng mảnh đất bằng cách tăng các cạnh đáy của hình bình hành này thêm 7 m thì được mảnh đất hình bình hành mới có diện tích hơn diện tích mảnh đất ban đầu là 189 m 2 . Hãy tính diện tích mảnh đất ban đầu.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Phần diện tích tăng thêm chính là diện tích hình bình hành có cạnh đáy 7m và chiều cao là chiều cao của mảnh đất hình bình hành ban đầu.\\nChiều cao mảnh đất là: 189: 7 = 27 (m) Diện tích mảnh đất hình bình hành ban đầu là: 27.\\n47 = 1269 (m 2 ) ần chọn là: D\\nKết luận: Đáp án đúng là C (1629 m 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4432, 283, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình bình hành có chu vi là 480cm, có độ dài cạnh đáy gấp 5 lần cạnh kia và gấp 8 lần chiều cao. Tính diện tích hình bình hành","images":[]}', '[{"key":"A","text":"5000 cm"},{"key":"B","text":"10000 cm"},{"key":"C","text":"2500 cm 2"},{"key":"D","text":"5000 cm 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình bình hành có chu vi là 480cm, có độ dài cạnh đáy gấp 5 lần cạnh kia và gấp 8 lần chiều cao. Tính diện tích hình bình hành\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Ta có nửa chu vi hình bình hành là: 480: 2 = 240 (cm) Cạnh đáy gấp 5 lần cạnh kia nên nửa chu vi sẽ gấp 6 lần cạnh kia.\\n- Ta có cạnh đáy hình bình hành là: 240: 6.\\n5 = 200 (cm) - Chiều cao của hình bình hành là: 200: 8 = 25 (cm) - Diện tích của hình bình hành là: 200.\\n25 = 5000 (cm 2 ) ần chọn là: D\\nKết luận: Đáp án đúng là C (2500 cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4433, 283, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Cho hình bình hành có diện tích là 312 m 2 , độ dài đáy là 24 m, chiều cao hình bình hành đó là:","images":[]}', '[{"key":"A","text":"17m"},{"key":"B","text":"30m"},{"key":"C","text":"37m"},{"key":"D","text":"13m"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình bình hành có diện tích là 312 m 2 , độ dài đáy là 24 m, chiều cao hình bình hành đó là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình bình hành đã cho có diện tích là 312 m 2 và độ dài đáy là 24 m nên: Chiều cao hình bình hành là: 312: 24 = 13 (m) ần chọn là: D\\nKết luận: Đáp án đúng là C (37m).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4434, 283, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Cho khu đất hình bình hành độ dài đáy là 300 dm, chiều cao khu đất hình bình hành là 20 m. Diện tích hình bình hành đó là:","images":[]}', '[{"key":"A","text":"6000 cm 2"},{"key":"B","text":"600 cm 2"},{"key":"C","text":"600 dm 2"},{"key":"D","text":"600 m 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho khu đất hình bình hành độ dài đáy là 300 dm, chiều cao khu đất hình bình hành là 20 m. Diện tích hình bình hành đó là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Đổi 300 dm = 30 m Diện tích hình bình hành đã cho là: 30.\\n20 = 600 (m 2 ) ần chọn là: D\\nKết luận: Đáp án đúng là C (600 dm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4435, 283, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Chọn câu đúng:","images":[]}', '[{"key":"A","text":"Diện tích hình bình hành bằng nửa tích của cạnh đáy nhân với chiều cao."},{"key":"B","text":"Diện tích hình bình hành bằng tổng của cạnh đáy và chiều cao."},{"key":"C","text":"Diện tích hình bình hành bằng tích của cạnh đáy nhân với chiều cao."},{"key":"D","text":"Diện tích hình bình hành bằng hiệu của cạnh đáy và chiều cao."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Diện tích hình bình hành bằng tích của cạnh đáy nhân với chiều cao.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (Diện tích hình bình hành bằng tích của cạnh đáy nhân với chiều cao.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4436, 283, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Chọn câu đúng:","images":[]}', '[{"key":"A","text":"Chu vi của một hình bình hành bằng tổng một cặp cạnh kề nhau bất kỳ."},{"key":"B","text":"Chu vi hình bình hành bằng tổng của cạnh đáy và chiều cao."},{"key":"C","text":"Chu vi hình bình hành bằng tích của cạnh đáy nhân với chiều cao."},{"key":"D","text":"Chu vi của một hình bình hành bằng 2 lần tổng một cặp cạnh kề nhau bất kỳ."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Chu vi của một hình bình hành bằng 2 lần tổng một cặp cạnh kề nhau bất kỳ.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (Chu vi hình bình hành bằng tích của cạnh đáy nhân với chiều cao.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4437, 284, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Trong các hình dưới đây, hình nào là hình thang cân:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/de21e6532ca7d9fe88584db77a5f3622857707a5.png","width":"482","height":"92","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113812.PNG"}]}', '[{"key":"A","text":"Hình a"},{"key":"B","text":"Hình b"},{"key":"C","text":"Hình c"},{"key":"D","text":"Hình d"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Trong các hình dưới đây, hình nào là hình thang cân:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Quan sát hình ta thấy Hình b là hình thang cân.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (Hình c).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4438, 284, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Quan sát hình thang cân EFGH, góc H của hình thang đó bằng góc nào?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8fa52df9772fbc1c6faeb80ed7bca82fb244b9ec.png","width":"156","height":"115","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113813.PNG"}]}', '[{"key":"A","text":"Góc E"},{"key":"B","text":"Góc F"},{"key":"C","text":"Góc G"},{"key":"D","text":"Góc O"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Quan sát hình thang cân EFGH, góc H của hình thang đó bằng góc nào?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Do góc H và góc G cùng kề đáy HG của hình thang EFGH nên: Góc H bằng góc G.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (Góc G).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8fa52df9772fbc1c6faeb80ed7bca82fb244b9ec.png","width":"156","height":"115","alt_text":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113813.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4439, 284, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Quan sát hình thang cân EFGH, đoạn EG bằng đoạn:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8fa52df9772fbc1c6faeb80ed7bca82fb244b9ec.png","width":"156","height":"115","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113813.PNG"}]}', '[{"key":"A","text":"EH"},{"key":"B","text":"HF"},{"key":"C","text":"EF"},{"key":"D","text":"HG"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Quan sát hình thang cân EFGH, đoạn EG bằng đoạn:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Do góc EG và HF là hai đường chéo của hình thang EFGH nên: EG = HF.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (EF).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8fa52df9772fbc1c6faeb80ed7bca82fb244b9ec.png","width":"156","height":"115","alt_text":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113813.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4440, 284, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Hình thang cân có:","images":[]}', '[{"key":"A","text":"1 cạnh bên"},{"key":"B","text":"2 cạnh bên"},{"key":"C","text":"3 cạnh bên"},{"key":"D","text":"4 cạnh bên"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hình thang cân có:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình thang cân có 2 cạnh bên.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (3 cạnh bên).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4441, 284, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Tên các đỉnh của hình thang cân EFGH dưới đây là","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8fa52df9772fbc1c6faeb80ed7bca82fb244b9ec.png","width":"156","height":"115","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113813.PNG"}]}', '[{"key":"A","text":"E, G, O, H"},{"key":"B","text":"E, F, O, G"},{"key":"C","text":"E, F, G, H"},{"key":"D","text":"E, F, G, H, O"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Tên các đỉnh của hình thang cân EFGH dưới đây là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình thang cân EFGH có bốn đỉnh là: E, F, G, H.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (E, F, G, H).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8fa52df9772fbc1c6faeb80ed7bca82fb244b9ec.png","width":"156","height":"115","alt_text":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113813.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4442, 284, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Quan sát hình thang cân EFGH, cạnh EH bằng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8fa52df9772fbc1c6faeb80ed7bca82fb244b9ec.png","width":"156","height":"115","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113813.PNG"}]}', '[{"key":"A","text":"EF"},{"key":"B","text":"HG"},{"key":"C","text":"HF"},{"key":"D","text":"FG"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Quan sát hình thang cân EFGH, cạnh EH bằng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Do góc EH và FG là cạnh bên của hình thang EFGH nên: EH = FG ần chọn là: D\\nKết luận: Đáp án đúng là C (HF).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4443, 284, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Cho hình thang cân ABCD, có BC = 3 cm. Chọn khẳng định đúng","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/60c029d9bc2dbc3c68a16144bcc8acb5d8149c4c.png","width":"224","height":"123","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113815.PNG"}]}', '[{"key":"A","text":"AB = 3cm"},{"key":"B","text":"AD = 3cm"},{"key":"C","text":"DC = 3cm"},{"key":"D","text":"AC= 3cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho hình thang cân ABCD, có BC = 3 cm. Chọn khẳng định đúng\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình thang cân ABCD có AD và BC là hai cạnh bên nên: AD = BC = 3 cm.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (DC = 3cm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4444, 284, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Hình thang cân EFGH có:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8fa52df9772fbc1c6faeb80ed7bca82fb244b9ec.png","width":"156","height":"115","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113813.PNG"}]}', '[{"key":"A","text":"EF là đường chéo"},{"key":"B","text":"EF và GH là đường chéo"},{"key":"C","text":"EH và FG là đường chéo"},{"key":"D","text":"EG và HF là đường chéo"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hình thang cân EFGH có:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình thang cân EFGH có: EG và HF là đường chéo.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (EH và FG là đường chéo).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4445, 284, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Diện tích hình thang sau bằng:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/78e68163be74879ea290ce691d8ba61002daaf38.png","width":"154","height":"117","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-113818.PNG"}]}', '[{"key":"A","text":"49cm"},{"key":"B","text":"49cm 2"},{"key":"C","text":"98cm 2"},{"key":"D","text":"98cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Diện tích hình thang sau bằng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Diện tích hình thang đã cho là: 5\\n+ 9 2 = 49 c m 2 ần chọn là: B\\nKết luận: Đáp án đúng là C (98cm 2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4446, 284, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Một hình thang có diện tích 20 m 2 , đáy lớn 55dm và đáy bé 45dm. Tính chiều cao của hình thang?","images":[]}', '[{"key":"A","text":"2 dm"},{"key":"B","text":"4 dm"},{"key":"C","text":"40 dm"},{"key":"D","text":"20 dm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Một hình thang có diện tích 20 m 2 , đáy lớn 55dm và đáy bé 45dm. Tính chiều cao của hình thang?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Đổi 20m 2 = 2000dm 2 Chiều cao của hình thang là: 2.\\n2000: (55\\n+ 45) = 40(dm) ần chọn là: C\\nKết luận: Đáp án đúng là C (40 dm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4447, 284, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tính trung bình cộng hai đáy của một hình thang, biết rằng diện tích hình thang bằng 7m 2 và chiều cao bằng 2m.","images":[]}', '[{"key":"A","text":"3,5 m"},{"key":"B","text":"7 m"},{"key":"C","text":"14 m"},{"key":"D","text":"9 m"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tính trung bình cộng hai đáy của một hình thang, biết rằng diện tích hình thang bằng 7m 2 và chiều cao bằng 2m.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trung bình cộng hai đáy của hình thang là: 7: 2 = 3,57: 2 = 3,5 (m) ần chọn là: A\\nKết luận: Đáp án đúng là C (14 m).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4448, 284, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Một thửa ruộng hình thang có đáy bé 26m, đáy lớn hơn đáy bé 8m, đáy bé hơn chiều cao 6m. Trung bình cứ 100m 2 thu hoạch được 70,5kg thóc. Hỏi thu hoạch được bao nhiêu ki-lô-gam thóc trên thửa ruộng đó?","images":[]}', '[{"key":"A","text":"423 kg"},{"key":"B","text":"600 kg"},{"key":"C","text":"432 kg"},{"key":"D","text":"141 kg"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Một thửa ruộng hình thang có đáy bé 26m, đáy lớn hơn đáy bé 8m, đáy bé hơn chiều cao 6m. Trung bình cứ 100m 2 thu hoạch được 70,5kg thóc. Hỏi thu hoạch được bao nhiêu ki-lô-gam thóc trên thửa ruộng đó?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Đáy lớn của thửa ruộng hình thang là: 26\\n+ 8 = 34 (m) Chiều cao của thửa ruộng hình thang là: 26 – 6 = 20 (m) Diện tích thửa ruộng hình thang là: 34\\n+ 26.\\n20 2 = 600 m 2 600m 2 gấp 6 lần 100m 2 Số ki-lô-gam thóc thu hoạch được trên thửa ruộng đó: 6.\\n70,5 = 423 (kg) ần chọn là: A\\nKết luận: Đáp án đúng là C (432 kg).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4449, 284, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Cho hình thang có độ dài hai cạnh bên là 5 cm và 7 cm, đáy lớn gấp đôi đáy nhỏ, biết độ dài đáy nhỏ là 6 cm. Chu vi hình thang là:","images":[]}', '[{"key":"A","text":"36 cm"},{"key":"B","text":"18 cm"},{"key":"C","text":"30 cm"},{"key":"D","text":"24 cm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình thang có độ dài hai cạnh bên là 5 cm và 7 cm, đáy lớn gấp đôi đáy nhỏ, biết độ dài đáy nhỏ là 6 cm. Chu vi hình thang là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: a)Sai.\\nVì ABCD là hình thang có DC là đáy nhỏ nên đáy AB là đáy lớn của hình thang cân ABCD.\\nHai đường chéo của hình thang cân ABCD là BD và AC.\\nDo đó, a) sai.\\nb) Đúng.\\nVì hai đường chéo cắt nhau tại O nên BD đi qua điểm O.\\nc) Sai.\\nVì ABCD là hình thang cân có DC là đáy nên AC = BD.\\nd) Đúng.\\nVì AC = BD và OC = OD nên A C − O C = B D − O D.\\nSuy ra OA = OB.\\nVậy tam giác AOB có hai cạnh bằng nhau.\\nKết luận: Đáp án đúng là C (30 cm).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/3292274fc3cce1d334dd33e61b56871e98c29cfb.png","width":"176","height":"154","alt_text":"10+ Bài tập trắc nghiệm Hình thang cân (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-hinh-thang-can-338098.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4450, 285, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Hình chữ nhật có bao nhiêu trục đối xứng","images":[]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hình chữ nhật có bao nhiêu trục đối xứng\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Vậy hình chữ nhật có 2 trục đối xứng.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (3).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/311070bad0bf6e1c0c3cabfca6635172cf1114ec.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-113828.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4451, 285, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình sau, chọn câu đúng nhất:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8b629b6fea5e469bc7d7e27c844bf0bcb9787cc5.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-113829.PNG"}]}', '[{"key":"A","text":"Hình a) và c) có trục đối xứng"},{"key":"B","text":"Hình c) có trục đối xứng"},{"key":"C","text":"Hình b) và c) có trục đối xứng"},{"key":"D","text":"Cả 3 hình có trục đối xứng"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình sau, chọn câu đúng nhất:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Ta có chữ N và Z không có trục đối xứng, chữ O có trục đối xứng.\\nVậy hình c) có trục đối xứng.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (Hình b) và c) có trục đối xứng).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/de4429465b9b5be99abad7774c0bd8b16c2fe9fc.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-113832.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4452, 285, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Trong những hình dưới đây, những hình có trục đối xứng là:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/4c9026f8878103a3863fc1bed90cf0c98bb246ac.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-113831.PNG"}]}', '[{"key":"A","text":"1,2,4"},{"key":"B","text":"1,2,4,6"},{"key":"C","text":"1,2,3,4,6,8"},{"key":"D","text":"1,2,4,5"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong những hình dưới đây, những hình có trục đối xứng là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Vậy hình 1,2,3,4,6,8 là các hình có trục đối xứng.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (1,2,3,4,6,8).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/636c0a2fea938e7b1db8fef8dddb880c143018ab.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-113833.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4453, 285, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho các hình sau, có bao nhiêu hình có trục đối xứng","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/7b56864fdc516d545b30cb89b1245db1a79af258.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-113834.PNG"}]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho các hình sau, có bao nhiêu hình có trục đối xứng\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: => Các hình có trục đối xứng là: b, c, d.\\nVậy có 3 hình có trục đối xứng.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (3).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/e7bceea264c5a660c6c8b4e425385bc199edfb9d.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-113835.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4454, 285, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Hình tam giác đều có mấy trục đối xứng:","images":[]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"0"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hình tam giác đều có mấy trục đối xứng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Vậy hình tam giác đều có 3 trục đối xứng.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (3).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/44e6def495c9466d783cb5aa9e35bbe11a4674a5.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-113836.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4455, 285, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Trong các hình bên, những hình có trục đối xứng là","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/021d5b50878b9f55823ecbc0ed7189d414a4a2be.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-113837.PNG"}]}', '[{"key":"A","text":"Tam giác đều, trái tim, cánh diều"},{"key":"B","text":"Cánh quạt, trái tim, cánh diều"},{"key":"C","text":"Trái tim, Cánh diều"},{"key":"D","text":"Cả bốn hình"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các hình bên, những hình có trục đối xứng là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Những hình có trục đối xứng: tam giác đều, cánh quạt, trái tim, cánh diều.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (Trái tim, Cánh diều).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4456, 285, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Hình tròn có tất cả bao nhiêu trục đối xứng?","images":[]}', '[{"key":"A","text":"Vô số trục đối xứng"},{"key":"B","text":"1 trục đối xứng."},{"key":"C","text":"2 trục đối xứng"},{"key":"D","text":"0 trục đối xứng."}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hình tròn có tất cả bao nhiêu trục đối xứng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nHình tròn có vô số trục đối xứng.\\nKết luận: Đáp án đúng là A (Vô số trục đối xứng).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4457, 285, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho đoạn thẳng AB. Trục đối xứng của đoạn thẳng AB là đường thẳng","images":[]}', '[{"key":"A","text":"Đi qua trung điểm của đoạn thẳng AB."},{"key":"B","text":"Đi qua điểm A."},{"key":"C","text":"Đi qua điểm B."},{"key":"D","text":"Đi qua trung điểm của đoạn thẳng AB và vuông góc với AB."}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho đoạn thẳng AB. Trục đối xứng của đoạn thẳng AB là đường thẳng\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrục đối xứng của đoạn thẳng AB là đường thẳng đi qua trung điểm của đoạn thẳng AB và vuông góc với AB.\\nKết luận: Đáp án đúng là D (Đi qua trung điểm của đoạn thẳng AB và vuông góc với AB.).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/f2a8797b85a96d779ac4c33706364fe8a1b4e44b.png","width":"168","height":"77","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-338112.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4458, 285, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Hình vuông có bao nhiêu trục đối xứng?","images":[]}', '[{"key":"A","text":"2."},{"key":"B","text":"3."},{"key":"C","text":"4."},{"key":"D","text":"0."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hình vuông có bao nhiêu trục đối xứng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nHình vuông có 4 trục đối xứng, trong đó có: Hai trục đối xứng là đường chéo của hình vuông.\\nHai trục đối xứng là đường nối trung điểm của hai cạnh đối diện.\\nKết luận: Đáp án đúng là C (4.).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/e14c3a987b6b1aee1333f39e492a8778d9852d83.png","width":"239","height":"96","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-338113.PNG"},{"id":"explanation-img-2","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/bf0910557ca9d7036ea45475757adda810cc24f0.png","width":"255","height":"108","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-338114.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4459, 285, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Đường thẳng nào trong hình vẽ dưới đây là trục đối xứng của hình chữ nhật ABCD?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/0e3d17e922fbcd841dac287c5875a3b5d1c12ae2.png","width":"230","height":"167","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-338115.PNG"}]}', '[{"key":"A","text":"Đường thẳng q."},{"key":"B","text":"Đường thẳng p."},{"key":"C","text":"Đường thẳng m."},{"key":"D","text":"Đường thẳng d."}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Đường thẳng nào trong hình vẽ dưới đây là trục đối xứng của hình chữ nhật ABCD?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: a) Sai.\\nHình vuông, hình chữ nhật là các hình đối xứng trục đối xứng.\\nHình bình hành là hình không có trục đối xứng.\\nb) Đúng.\\nMỗi đường chéo là một trục đối xứng của hình thoi: c) Sai.\\n+ Mỗi đường thẳng đi qua trung điểm của hai cạnh đối diện là một trục đối xứng của hình chữ nhật: Do đó, hình chữ nhật có hai trục đối xứng.\\n+ Hình thang cân có 1 trục đối xứng: d) Đúng.\\nHình tròn có vô số trục đối xứng, mỗi trục đối xứng là đường thẳng đi qua tâm của nó nên hình tròn là hình có trục đối xứng.\\nHình vuông có 4 trục đối xứng: Trong các hình trên, có hai hình có nhiều hơn 2 trục đối xứng là: Hình tròn và hình vuông.\\nKết luận: Đáp án đúng là B (Đường thẳng p.).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8ac4a6d38a3dd6d01f3a1f06febe17574b268581.png","width":"177","height":"101","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-338100.PNG"},{"id":"explanation-img-2","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/339ab57efc740930035ccd7291dd26cc34bdd011.png","width":"165","height":"115","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-338101.PNG"},{"id":"explanation-img-3","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/0ad46559e3f71bf6fd9b454625592d011c7f6b3b.png","width":"230","height":"134","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-338102.PNG"},{"id":"explanation-img-4","alt":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/805fc182eac7aee7d13a7188b95a14431c8136b0.png","width":"166","height":"160","alt_text":"10+ Bài tập trắc nghiệm Hình có trục đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-5-hinh-co-truc-doi-xung-338103.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4460, 286, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Hình nào sau đây không có tâm đối xứng","images":[]}', '[{"key":"A","text":"Hình vuông"},{"key":"B","text":"Hình chữ nhật"},{"key":"C","text":"Hình bình hành"},{"key":"D","text":"Hình tam giác đều"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hình nào sau đây không có tâm đối xứng\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Tâm đối xứng của hình vuông là giao điểm của hai đường chéo.\\n- Tâm đối xứng của hình chữ nhật là giao điểm của hai đường chéo.\\n- Tâm đối xứng của hình bình hành là giao điểm của hai đường chéo.\\n- Hình tam giác đều không có tâm đối xứng.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (Hình bình hành).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4461, 286, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình sau, hình có tâm đối xứng là:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/c26cbd552382c2fc14e491c7a62bca36accf3592.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-6-hinh-co-tam-doi-xung-113845.PNG"}]}', '[{"key":"A","text":"Hình a"},{"key":"B","text":"Hình b"},{"key":"C","text":"Hình c"},{"key":"D","text":"Hình a và Hình c"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình sau, hình có tâm đối xứng là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình a có tâm đối xứng: ần chọn là: A\\nKết luận: Đáp án đúng là C (Hình c).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8b2127dd2a2fab4a2d96901c9c93659a977a1d6f.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-6-hinh-co-tam-doi-xung-113846.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4462, 286, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Cho các chữ sau đây, những chữ cái có tâm đối xứng là:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/59c75a40242516fc5bbc2d80f8606ecf1645646f.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-6-hinh-co-tam-doi-xung-113847.PNG"}]}', '[{"key":"A","text":"H, N"},{"key":"B","text":"H ,M ,X"},{"key":"C","text":"H ,N ,X"},{"key":"D","text":"N, X"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho các chữ sau đây, những chữ cái có tâm đối xứng là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Những chữ cái có tâm đối xứng: H, N, X ần chọn là: C\\nKết luận: Đáp án đúng là C (H ,N ,X).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4463, 286, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Hình nào sau đây có tâm đối xứng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/12c30e4007420e1465d3aeebb24d52c974bd2e84.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-6-hinh-co-tam-doi-xung-113848.PNG"}]}', '[{"key":"A","text":"96"},{"key":"B","text":"EF"},{"key":"C","text":"PQ"},{"key":"D","text":"Không có hình nào"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hình nào sau đây có tâm đối xứng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình có tâm đối xứng là: ần chọn là: A\\nKết luận: Đáp án đúng là C (PQ).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/fc315b806b3f7ae78aa1031ca641a886a0602ff8.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-6-hinh-co-tam-doi-xung-113849.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4464, 286, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Trong các hình sau, có bao nhiêu hình có tâm đối xứng:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/b81ffab7122fa0b005df237c84fd441d47b55b2f.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-6-hinh-co-tam-doi-xung-113850.PNG"}]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các hình sau, có bao nhiêu hình có tâm đối xứng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: => Hình a và hình b là hình có tâm đối xứng.\\nVậy có 2 hình có tâm đối xứng.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (3).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/5134c0e7ab33904542efb5844e1ff8e1bb2b2f14.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-6-hinh-co-tam-doi-xung-113851.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4465, 286, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tâm đối xứng của hình thoi ABCD là","images":[]}', '[{"key":"A","text":"Giao điểm của hai đường chéo."},{"key":"B","text":"Trung điểm của AB"},{"key":"C","text":"Trung điểm của CD"},{"key":"D","text":"Điểm C"}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tâm đối xứng của hình thoi ABCD là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTâm đối xứng của hình thoi ABCD là giao điểm của hai đường chéo.\\nKết luận: Đáp án đúng là A (Giao điểm của hai đường chéo.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4466, 286, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Hình nào dưới đây là hình không có tâm đối xứng?","images":[]}', '[{"key":"A","text":"Hình vuông"},{"key":"B","text":"Hình chữ nhật."},{"key":"C","text":"Hình thoi."},{"key":"D","text":"Hình thang cân."}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hình nào dưới đây là hình không có tâm đối xứng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nHình vuông, hình chữ nhật, hình thoi là các hình có tâm đối xứng.\\nTâm đối xứng của các hình đó là giao điểm của hai đường chéo.\\nHình thang cân là hình không có tâm đối xứng.\\nKết luận: Đáp án đúng là D (Hình thang cân.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4467, 286, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hình vuông vẽ dưới đây: Điểm nào dưới đây là tâm đối xứng của hình trên?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/9c5c380616062c5002320401d3903fc1a669a8b8.png","width":"154","height":"142","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-6-hinh-co-tam-doi-xung-338116.PNG"}]}', '[{"key":"A","text":"Điểm A"},{"key":"B","text":"Điểm B"},{"key":"C","text":"Điểm C"},{"key":"D","text":"Điểm D"}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hình vuông vẽ dưới đây: Điểm nào dưới đây là tâm đối xứng của hình trên?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nĐiểm D là tâm đối xứng của hình vuông ở trên.\\nKết luận: Đáp án đúng là D (Điểm D).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4468, 286, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Cho đoạn thẳng AB = 6 cm. Gọi điểm O là tâm đối xứng của đoạn thẳng AB. Độ dài đoạn thẳng OA bằng","images":[]}', '[{"key":"A","text":"2 cm."},{"key":"B","text":"3 cm."},{"key":"C","text":"4 cm."},{"key":"D","text":"5 cm."}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho đoạn thẳng AB = 6 cm. Gọi điểm O là tâm đối xứng của đoạn thẳng AB. Độ dài đoạn thẳng OA bằng\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nVì O là tâm đối xứng của đoạn thẳng AB nên O là trung điểm của đoạn thẳng AB.\\nDo đó, OA = AB: 2 = 6: 2 = 3 (cm).\\nVậy độ dài đoạn thẳng OA bằng 3 cm.\\nKết luận: Đáp án đúng là B (3 cm.).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/99be7eee59a912615fbc4ddb1b7e0854dd16c6bb.png","width":"227","height":"28","alt_text":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-6-hinh-co-tam-doi-xung-338117.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4469, 286, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Chọn câu đúng.","images":[]}', '[{"key":"A","text":"Tâm đối xứng của hình lục giác đều ABCDEF là trung điểm của EB."},{"key":"B","text":"Tâm đối xứng của hình lục giác đều ABCDEF là trung điểm của AE."},{"key":"C","text":"Hình lục giác đều là hình không có tâm đối xứng."},{"key":"D","text":"Hình lục giác đều có hai tâm đối xứng."}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn câu đúng.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: a) Sai.\\nHình thang cân là hình không có tâm đối xứng.\\nb) Đúng.\\nHình vuông, hình chữ nhật, hình bình hành có tâm đối xứng là giao điểm của hai đường chéo.\\nVậy tập hợp {Hình vuông; hình chữ nhật; hình bình hành} gồm các hình có tâm đối xứng.\\nc) Sai.\\nTâm của hình tròn là tâm đối xứng của hình đó.\\nHình thoi có tâm đối xứng là giao điểm của hai đường chéo.\\nDo đó, trong các hình trên, có 5 hình là hình có tâm đối xứng là: Hình vuông, hình chữ nhật, hình bình hành, hình thoi, hình tròn.\\nd) Đúng.\\nHình bình hành không có trục đối xứng.\\nHình tròn có trục đối xứng là các đường kính của hình đó.\\nHình chữ nhật có các trục đối xứng là các đường thẳng đi qua trung điểm hai cạnh đối.\\nHình thoi có các trục đối xứng là hai đường chéo.\\nHình vuông có các trục đối xứng là hai đường chéo và các đường thẳng đi qua trung điểm hai cạnh đối.\\nCó 4 hình vừa có tâm đối xứng vừa có trục đối xứng là: Hình vuông, hình chữ nhật, hình thoi, hình tròn.\\nKết luận: Đáp án đúng là A (Tâm đối xứng của hình lục giác đều ABCDEF là trung điểm của EB.).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/702501f9a9081620d510a1f69a88fd80534d08dc.png","width":"144","height":"131","alt_text":"10+ Bài tập trắc nghiệm Hình có tâm đối xứng (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-6-hinh-co-tam-doi-xung-338118.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4470, 287, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Trong các hình sau, hình nào có trục đối xứng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/561b11e95f48d6383e319b9e753f920a82e7ff0a.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-113859.PNG"}]}', '[{"key":"A","text":"hình a"},{"key":"B","text":"hình a"},{"key":"C","text":"hình a và hình b"},{"key":"D","text":"không có hình nào"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các hình sau, hình nào có trục đối xứng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình a có trục đối xứng.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (hình a và hình b).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4471, 287, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Chọn khẳng định đúng nhất về chiếc đĩa dưới đây:","images":[]}', '[{"key":"A","text":"Chiếc bàn có tâm đối xứng"},{"key":"B","text":"Chiếc bàn có trục đối xứng"},{"key":"C","text":"Chiếc bàn vừa có tâm đối xứng và trục đối xứng"},{"key":"D","text":"Chiếc bàn không có tâm đối xứng và trục đối xứng"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Chọn khẳng định đúng nhất về chiếc đĩa dưới đây:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Quan sát hình vẽ ta thấy: Chiếc đĩa vừa có tâm đối xứng và trục đối xứng ần chọn là: C\\nKết luận: Đáp án đúng là C (Chiếc bàn vừa có tâm đối xứng và trục đối xứng).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4472, 287, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Trong các hình dưới đây, hình nào có tâm đối xứng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/0a31ec915b4df0c06fe1ab6d1af8907def4a126c.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-113860.PNG"}]}', '[{"key":"A","text":"Hình a, b, c"},{"key":"B","text":"Hình a, c"},{"key":"C","text":"Hình a,d"},{"key":"D","text":"Cả bốn hình"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các hình dưới đây, hình nào có tâm đối xứng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình có tâm đối xứng là: a);\\nc) ần chọn là: B\\nKết luận: Đáp án đúng là C (Hình a,d).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4473, 287, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Trong các hình bên, những hình có tâm đối xứng là","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/bc61f6031c1380e3fda6dd34c4acd069311b3a7e.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-113861.PNG"}]}', '[{"key":"A","text":"Tam giác đều"},{"key":"B","text":"Cánh quạt"},{"key":"C","text":"Trái tim"},{"key":"D","text":"Cánh diều"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các hình bên, những hình có tâm đối xứng là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Hình có tâm đối xứng là hình cánh quạt (Tâm đối xứng là tâm của đường tròn nhỏ phía trong) ần chọn là: B\\nKết luận: Đáp án đúng là C (Trái tim).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4474, 287, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Trong các hình bên, những hình có trục đối xứng là","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/af730dcb3ad270c4657b6db4ba4d3c58b3d4576a.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-113862.PNG"}]}', '[{"key":"A","text":"Tam giác đều, trái tim, cánh diều"},{"key":"B","text":"Cánh quạt, trái tim, cánh diều"},{"key":"C","text":"Trái tim, Cánh diều"},{"key":"D","text":"Cả bốn hình"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các hình bên, những hình có trục đối xứng là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Những hình có trục đối xứng: tam giác đều, cánh quạt, trái tim, cánh diều.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (Trái tim, Cánh diều).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4475, 287, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho hai hình sau, chọn câu đúng:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/aeff8f4e825263b47501e9e6267e2e00f50fe80f.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-113863.PNG"}]}', '[{"key":"A","text":"Hình con sao biển có trục đối xứng"},{"key":"B","text":"Hình chiếc lá có trục đối xứng"},{"key":"C","text":"Hình chiếc lá có trục đối xứng"},{"key":"D","text":"Không có hình nào có trục đối xứng"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho hai hình sau, chọn câu đúng:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Vậy hình con sao biển có trục đối xứng.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (Hình chiếc lá có trục đối xứng).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/f2f009e29c86aa9e7219a79036946220cfc923b3.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-113864.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4476, 287, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Hình nào dưới đây có trục đối xứng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/a09e38ddd3dad188522ead5a1da2d76ff00ba48d.png","width":"448","height":"141","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-338119.PNG"}]}', '[{"key":"A","text":"Hình a), Hình b), Hình c)."},{"key":"B","text":"Hình a), Hình c), Hình d)."},{"key":"C","text":"Hình b), Hình c), Hình d)"},{"key":"D","text":"Hình a) và Hình c)."}]', 'B', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hình nào dưới đây có trục đối xứng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nCác hình có trục đối xứng là: Hình a), Hình c), Hình d).\\nKết luận: Đáp án đúng là B (Hình a), Hình c), Hình d).).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4477, 287, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho các hình vẽ sau: Đường nét đứt trong hình không là trục đối xứng của hình vẽ?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/41e9919a728775dfbd7b8b3f4a6f92b903f36696.png","width":"498","height":"99","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-338120.PNG"}]}', '[{"key":"A","text":"Hình 1."},{"key":"B","text":"Hình 2."},{"key":"C","text":"Hình 3."},{"key":"D","text":"Hình 4."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho các hình vẽ sau: Đường nét đứt trong hình không là trục đối xứng của hình vẽ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nĐường nét đứng trong hình 3 không là trục đối xứng của hình vẽ.\\nKết luận: Đáp án đúng là C (Hình 3.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4478, 287, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Hình nào dưới đây là hình có tâm đối xứng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/15fa05ca4f78463ff22d3bbd1240d62d49c1232b.png","width":"528","height":"95","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-338121.PNG"}]}', '[{"key":"A","text":"Hình 1."},{"key":"B","text":"Hình 2."},{"key":"C","text":"Hình 3."},{"key":"D","text":"Hình 4."}]', 'D', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hình nào dưới đây là hình có tâm đối xứng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nHình 4 là hình có tâm đối xứng (tâm đối xứng là điểm màu đỏ):\\nKết luận: Đáp án đúng là D (Hình 4.).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/8c14565188d7e4df6106558e07081ab6bf485701.png","width":"180","height":"64","alt_text":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-338122.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4479, 287, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Cho các hình sau: Hình nào là hình có tâm đối xứng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/2050c8c7d887674deaeee9d64f9b8ab080b083fd.png","width":"412","height":"122","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-338123.PNG"},{"id":"img-2","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/13f9938e06e64d2c833c806465087b866784171b.png","width":"337","height":"260","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-338108.PNG"}]}', '[{"key":"A","text":"Hình 1, Hình 3."},{"key":"B","text":"Hình 1, hình 2, hình 3."},{"key":"C","text":"Hình 1, Hình 2"},{"key":"D","text":"Hình 2, hình 3."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho các hình sau: Hình nào là hình có tâm đối xứng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: a) Đúng.\\nHình 1 là hình có trục đối xứng.\\nb) Đúng.\\nHình 6 là hình có tâm đối xứng.\\nc) Đúng.\\nHình 6 không có tâm đối xứng và không có trục đối xứng.\\nd) Sai.\\nCó hình 1 và hình 6 vừa có trục đối xứng vừa có tâm đối xứng.\\nKết luận: Đáp án đúng là C (Hình 1, Hình 2).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/0c7ffb7f57677ae6cf8e80cd2db22d1776ad6b40.png","width":"309","height":"134","alt_text":"10+ Bài tập trắc nghiệm Đối xứng trong thực tiễn (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-7-doi-xung-trong-thuc-tien-338124.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4480, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Các môn thể thao được ưa thích của lớp 6a Các môn thể thao được yêu thích của lớp 6A là:","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/cebd4c12cb09ea5eedc5d7c22f522e1515ddf898.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113926.PNG"}]}', '[{"key":"A","text":"Cầu lông, bóng bàn, đá cầu, bóng rổ, bóng đá"},{"key":"B","text":"Bóng chuyền, bóng bàn, bóng đá, đá cầu, bóng rổ"},{"key":"C","text":"Đá cầu, bóng chuyền, điền kinh, bóng rổ, bóng bàn"},{"key":"D","text":"Bóng rổ, đá cầu, bóng đá"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Các môn thể thao được ưa thích của lớp 6a Các môn thể thao được yêu thích của lớp 6A là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Các môn thể thao được yêu thích của lớp 6A là: Bóng đá, cầu lông, bóng bàn, đá cầu, bóng rổ.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (Đá cầu, bóng chuyền, điền kinh, bóng rổ, bóng bàn).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4481, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Số học sinh vắng trong ngày của các lớp khối 6 trường THCS A là 6A1 6A2 6A3 6A4 6A5 6A6 6A7 6A8 Có bao nhiêu lớp có số học sinh vắng ít nhất","images":[]}', '[{"key":"A","text":"4"},{"key":"B","text":"5"},{"key":"C","text":"1"},{"key":"D","text":"2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Số học sinh vắng trong ngày của các lớp khối 6 trường THCS A là 6A1 6A2 6A3 6A4 6A5 6A6 6A7 6A8 Có bao nhiêu lớp có số học sinh vắng ít nhất\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số học sinh vắng ít nhất trong một lớp là 1 Lớp có số học sinh vắng ít nhất là lớp 6A4 , 6A8 Vậy có 2 lớp có số học sinh vắng ít nhất.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (1).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4482, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Em hãy chỉ ra các điểm không hợp lí trong bảng dữ liệu sau: Danh sách học sinh giỏi lớp 7A STT Họ và tên 1 Nguyễn Hoàng Xuân 2 Phạm Thị Hương 3 Đỗ Thu Hà 4 03456789 Ngô Xuân Giang","images":[]}', '[{"key":"A","text":"Nguyễn Hoàng Xuân"},{"key":"B","text":"03456789"},{"key":"C","text":"Phạm Thị Hương"},{"key":"D","text":"Ngô Xuân Giang"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Em hãy chỉ ra các điểm không hợp lí trong bảng dữ liệu sau: Danh sách học sinh giỏi lớp 7A STT Họ và tên 1 Nguyễn Hoàng Xuân 2 Phạm Thị Hương 3 Đỗ Thu Hà 4 03456789 Ngô Xuân Giang\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Họ và tên phải là chữ nên 03456789 không thể là họ và tên của một người ần chọn là: B\\nKết luận: Đáp án đúng là C (Phạm Thị Hương).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4483, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Có bao nhiêu điểm không hợp lí trong cột “email” của bảng dữ liệu: Danh sách email của các bạn tổ 1 lớp 6D","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/4ab782162454a4dc2b2c6939b5386c7da407f2dd.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113927.PNG"}]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Có bao nhiêu điểm không hợp lí trong cột “email” của bảng dữ liệu: Danh sách email của các bạn tổ 1 lớp 6D\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Ở bảng 4, Email của bạn Cúc và bạn Đào không hợp lí vì không đúng theo cú pháp của email (Email phải có @) ần chọn là: B\\nKết luận: Đáp án đúng là C (3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4484, 288, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Cho bảng số liệu đánh giá chất lượng sản phẩm bằng điểm số 1, 2, 3, 4, 5 của một lô hàng gồm 15 sản phẩm như sau: Điểm Số sản phẩm 0 7 Đối tượng thống kê là","images":[]}', '[{"key":"A","text":"Các điểm số 1, 2, 3, 4, 5."},{"key":"B","text":"Số sản phẩm 3,0,5,7,0"},{"key":"C","text":"Điểm số và sản phẩm"},{"key":"D","text":"Lô hàng"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho bảng số liệu đánh giá chất lượng sản phẩm bằng điểm số 1, 2, 3, 4, 5 của một lô hàng gồm 15 sản phẩm như sau: Điểm Số sản phẩm 0 7 Đối tượng thống kê là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Bảng trên có thông tin về số sản phẩm đạt từng loại điểm 1, 2, 3, 4, 5 nên đối tượng thống kê là các điểm số 1,2,3,4,5.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (Điểm số và sản phẩm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4485, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Bạn Hùng ghi chép nhanh điểm Toán của các bạn trong tổ 1 của lớp 6A5 thành dãy dữ liệu: 5, 8, 6, 7, 8, 5, 4, 6, 9, 6, 8, 8. Em hãy giúp Hùng sắp xếp lại dữ liệu trên vào bảng sau (theo mẫu): Em hãy cho biết có bao nhiêu bạn được điểm 8 và có bao nhiêu bạn có điểm dưới 6.","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/40eb5848463b098556b9e39633b1ca5e42837366.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113928.PNG"}]}', '[{"key":"A","text":"4 bạn được 8 và 2 bạn dưới 6."},{"key":"B","text":"4 bạn được 8 và 3 bạn dưới 6"},{"key":"C","text":"4 bạn được 8 và 6 bạn dưới 6"},{"key":"D","text":"1 bạn được 8 và 3 bạn dưới 6"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Bạn Hùng ghi chép nhanh điểm Toán của các bạn trong tổ 1 của lớp 6A5 thành dãy dữ liệu: 5, 8, 6, 7, 8, 5, 4, 6, 9, 6, 8, 8. Em hãy giúp Hùng sắp xếp lại dữ liệu trên vào bảng sau (theo mẫu): Em hãy cho biết có bao nhiêu bạn được điểm 8 và có bao nhiêu bạn có điểm dưới 6.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Cách điền: Tổ 1 của lớp 6A5 có 12 bạn đạt các điểm toán là: 9;\\n8;\\n7;\\n6;\\n5;\\n4.\\nTrong các số 5, 8, 6, 7, 8, 5, 4, 6, 9, 6, 8, 8 có 1 số 9 nên số bạn được 9 là 1.\\n=> Ta điền 1 vào ô dưới điểm 9.\\nSố bạn được 8 là 4 nên ta điền 4 vào ô dưới điểm 8 Tương tự với số bạn được 7;\\n6;\\n5;\\n4.\\nĐiểm dưới 6 là 5 và 4 Số bạn được 5 là 2 và số bạn được 4 là 1 nên tổng số bạn dưới 6 là 2+1=3 bạn.\\nDựa vào bảng trên ta thấy có 4 bạn được điểm 8 và 3 bạn có điểm dưới 6.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (4 bạn được 8 và 6 bạn dưới 6).","images":[{"id":"explanation-img-1","alt":"Bài tập trắc nghiệm Bài 1: Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/02b5823cdb1568f0a184ec6d27d96a7dac690355.png","width":"","height":"","alt_text":"Bài tập trắc nghiệm Bài 1: Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113929.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4486, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Hãy đọc bảng thống kê xếp loại hạnh kiểm lớp 6A sau: Em hãy cho biết lớp 6A có tất cả bao nhiêu học sinh?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/ae42b238e63de6c24543e58c844fd5b84c02a557.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113930.PNG"}]}', '[{"key":"A","text":"25"},{"key":"B","text":"3"},{"key":"C","text":"2"},{"key":"D","text":"30"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hãy đọc bảng thống kê xếp loại hạnh kiểm lớp 6A sau: Em hãy cho biết lớp 6A có tất cả bao nhiêu học sinh?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số học sinh lớp 6A là: 25\\n+ 3\\n+ 2 = 30 (học sinh) ần chọn là: D\\nKết luận: Đáp án đúng là C (2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4487, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Điều tra loại phim yêu thích nhất của 36 học sinh lớp 6A3, bạn lớp trưởng thu được bảng dữ liệu ban đầu như sau: Viết tắt: H: Hoạt hình; L: Lịch sử; K: Khoa học; C: Ca nhạc; T: Trinh thám. Loại phim nào được các bạn học sinh lớp 6A3 yêu thích nhất?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/2494f952585f38f1670cf6029ac2b1b324e01ae1.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113931.PNG"}]}', '[{"key":"A","text":"Hoạt hình"},{"key":"B","text":"Lịch sử"},{"key":"C","text":"Khoa học"},{"key":"D","text":"Trinh thám"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Điều tra loại phim yêu thích nhất của 36 học sinh lớp 6A3, bạn lớp trưởng thu được bảng dữ liệu ban đầu như sau: Viết tắt: H: Hoạt hình; L: Lịch sử; K: Khoa học; C: Ca nhạc; T: Trinh thám. Loại phim nào được các bạn học sinh lớp 6A3 yêu thích nhất?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số chữ H là 11, số chữ L là 6, số chữ K là 4, số chữ C là 7, số chữ T là 8.\\nBảng thống kế các bộ phim yêu thích của các học sinh lớp 6A3 là: Loại phim Hoạt hình Lịch sử Khoa học Ca nhạc Trinh thám Số bạn thích 11 6 4 7 8 Phim hoạt hình có số bạn là 11 nên loại phim hoạt hình được các bạn học sinh lớp 6A3 yêu thích nhất.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (Khoa học).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4488, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Một nhóm bạn thân gồm 6 người đi đến một quán trà chanh và mua các loại nước uống và các loại nước uống được ghi lại trong bảng sau: Nước cam Nước dưa hấu Nước chanh Nước dứa Có bao nhiêu loại nước được mua?","images":[]}', '[{"key":"A","text":"5"},{"key":"B","text":"4"},{"key":"C","text":"3"},{"key":"D","text":"2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một nhóm bạn thân gồm 6 người đi đến một quán trà chanh và mua các loại nước uống và các loại nước uống được ghi lại trong bảng sau: Nước cam Nước dưa hấu Nước chanh Nước dứa Có bao nhiêu loại nước được mua?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Có 4 loại nước được mua: Nước cam, nước dưa hấu, nước chanh, nước dứa.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4489, 288, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Lan tìm hiểu về thức ăn sáng nay của các bạn trong lớp và thu được kết quả như sau: Dữ liệu nào sau đây không là số liệu?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 1: Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/7e607a1286dc88199dc74b9c9fdb624e67c70b80.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113932.PNG"}]}', '[{"key":"A","text":"Xôi"},{"key":"B","text":"11"},{"key":"C","text":"8"},{"key":"D","text":"2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Lan tìm hiểu về thức ăn sáng nay của các bạn trong lớp và thu được kết quả như sau: Dữ liệu nào sau đây không là số liệu?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Xôi không là số nên không là số liệu.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (8).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4490, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Điểm thi của Nam và Khải được biểu diễn trong biểu đồ cột kép ở hình sau: Khẳng định nào sau đây đúng ?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/f6d316e07e2e13449b0e67680ffe6dd8df631593.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113965.PNG"}]}', '[{"key":"A","text":"Điểm Toán của Nam cao hơn Khải"},{"key":"B","text":"Điểm cả 3 môn của Khải cao hơn Nam"},{"key":"C","text":"Điểm Ngữ văn của Nam cao hơn Khải"},{"key":"D","text":"Điểm Ngữ văn của Khải cao hơn Nam"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Điểm thi của Nam và Khải được biểu diễn trong biểu đồ cột kép ở hình sau: Khẳng định nào sau đây đúng ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Điểm toán của Nam thấp hơn Khải => A sai.\\nĐiểm Ngữ văn của Nam cao hơn Khải.\\nTức là điểm Ngữ văn của Khải thấp hơn Nam nên điểm 3 môn của Khải cao hơn Nam là sai => B sai, C đúng và D sai.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (Điểm Ngữ văn của Nam cao hơn Khải).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4491, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Điểm thi của Nam và Khải được biểu diễn trong biểu đồ cột kép ở hình sau: Điểm cao nhất thuộc về bạn nào, môn nào?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/63a67c67d7f6de94554774afe6947d539ab37f6f.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113966.PNG"}]}', '[{"key":"A","text":"Bạn Nam môn Tiếng Anh"},{"key":"B","text":"Bạn Nam môn Toán"},{"key":"C","text":"Bạn Khải môn Toán"},{"key":"D","text":"Bạn Khải môn Ngữ văn"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Điểm thi của Nam và Khải được biểu diễn trong biểu đồ cột kép ở hình sau: Điểm cao nhất thuộc về bạn nào, môn nào?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Cột cao nhất là cột màu xanh, môn Toán.\\nVậy điểm cao nhất thuộc về bạn Khải môn Toán.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (Bạn Khải môn Toán).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4492, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Quan sát biểu đồ trong Hình 6, em hãy cho biết nó được ghép bởi","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/c392784af07bdaf3c541de81b9fc4b2e2481a95d.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113967.PNG"}]}', '[{"key":"A","text":"Biểu đồ số cây hoa trồng được của lớp 6A2 và 6A3"},{"key":"B","text":"Biểu đồ số cây hoa trồng được của lớp 6A2"},{"key":"C","text":"Biểu đồ số cây hoa trồng được của lớp 6A3"},{"key":"D","text":"Biểu đồ số cây hoa trồng được của lớp 6A1 và 6A2."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Quan sát biểu đồ trong Hình 6, em hãy cho biết nó được ghép bởi\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Biểu đồ hình 6 được ghép bởi 2 biểu đồ: - Biểu đồ số cây hoa trồng được của lớp 6A1 - Biểu đồ số cây hoa trồng được của lớp 6A2 ần chọn là: D\\nKết luận: Đáp án đúng là C (Biểu đồ số cây hoa trồng được của lớp 6A3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4493, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho biểu đồ cột ghép điểm học kì 1 của bạn Hải và bạn Lan như sau: Môn Ngữ văn của bạn Lan bằng bao nhiêu?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/43b789fdac6799c56c9bd80b57d77f7a9720f239.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113973.PNG"}]}', '[{"key":"A","text":"8"},{"key":"B","text":"7"},{"key":"C","text":"6"},{"key":"D","text":"9"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho biểu đồ cột ghép điểm học kì 1 của bạn Hải và bạn Lan như sau: Môn Ngữ văn của bạn Lan bằng bao nhiêu?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Điểm của bạn Lan là màu đỏ và hàng Ngữ văn nên số điểm Ngữ văn của Lan là 7.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (6).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4494, 288, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Cho biểu đồ cột ghép điểm học kì 1 của bạn Hải và bạn Lan như sau: Điểm Toán của Lan cao hơn Hải là bao nhiêu điểm?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/63cee304ad24a5b90dd35561617a2c4fe23c040a.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113974.PNG"}]}', '[{"key":"A","text":"8 điểm"},{"key":"B","text":"0 điểm"},{"key":"C","text":"1 điểm"},{"key":"D","text":"2 điểm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho biểu đồ cột ghép điểm học kì 1 của bạn Hải và bạn Lan như sau: Điểm Toán của Lan cao hơn Hải là bao nhiêu điểm?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Điểm toán của Lan là 8 và của Hải là 7.\\nĐiểm toán của Lan cao hơn của Hải là 8-7=1 điểm.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (1 điểm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4495, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Biểu đồ cột kép biểu diễn sĩ số học sinh đầu năm học và cuối năm học của bốn lớp khối 6: Sĩ số của lớp nào tăng?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/783365415776f2ed902c4a9a5a95a6d6aed92b4f.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113975.PNG"}]}', '[{"key":"A","text":"6A1"},{"key":"B","text":"6A2"},{"key":"C","text":"6A3"},{"key":"D","text":"6A4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Biểu đồ cột kép biểu diễn sĩ số học sinh đầu năm học và cuối năm học của bốn lớp khối 6: Sĩ số của lớp nào tăng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Sĩ số của lớp 6A2 tăng vì sĩ số đầu năm là 35 và cuối năm là 38.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (6A3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4496, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Biểu đồ cột kép biểu diễn sĩ số học sinh đầu năm học và cuối năm học của bốn lớp khối 6: Sĩ số đầu năm của lớp nào cao nhất?","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/27984e0cfa52d89a04bcca873a37e60c56a03832.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113976.PNG"}]}', '[{"key":"A","text":"6A2"},{"key":"B","text":"6A1"},{"key":"C","text":"6A3"},{"key":"D","text":"6A4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Biểu đồ cột kép biểu diễn sĩ số học sinh đầu năm học và cuối năm học của bốn lớp khối 6: Sĩ số đầu năm của lớp nào cao nhất?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Sĩ số đầu năm của lớp 6A4 là cao nhất trong 4 lớp.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (6A3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4497, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Cho biểu đồ cột kép sau: Số con cá của tổ 3 và tổ 4 nuôi trong biểu đồ ở hình trên là","images":[{"id":"img-1","alt":"Bài tập trắc nghiệm Bài 2: Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/1b56bca5ea473dfec4f3c8298c0a4aae554f5c48.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113977.PNG"},{"id":"img-2","alt":"","url":"/uploads/images/crawled/32f29cb1f8a362998da260be39f417d7bcf3b8cc.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/de-thi.png"},{"id":"img-3","alt":"","url":"/uploads/images/crawled/99ab1d22fd95fc929ef8c34dfa92e34fbad71c06.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/giao-an-pp.png"},{"id":"img-4","alt":"","url":"/uploads/images/crawled/d118c48c7c59e39689308157c87cef6474fe7440.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/giao-an-word.png"},{"id":"img-5","alt":"","url":"/uploads/images/crawled/e763791edf79777051baaf626e13df41a05b3a0c.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/bai-tap.png"},{"id":"img-6","alt":"","url":"/uploads/images/crawled/eeb59aba1ef7cfecc1444f766bd3224977efb0d1.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/de-hsg.png"},{"id":"img-7","alt":"","url":"/uploads/images/crawled/9acd9bdc1c01e2e81e39a7a596776ccf1002b4ed.png","width":"","height":"","source_url":"https://vietjack.com/git/images/doc_icon/trac-nghiem.png"}]}', '[{"key":"A","text":"Tổ 3 là 10, tổ 4 là 14"},{"key":"B","text":"Tổ 3 là 12, tổ 4 là 16"},{"key":"C","text":"Tổ 3 là 12, tổ 4 là 15"},{"key":"D","text":"Tổ 3 là 15, tổ 4 là 12"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho biểu đồ cột kép sau: Số con cá của tổ 3 và tổ 4 nuôi trong biểu đồ ở hình trên là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số cá tổ 3: 12 Số cá tổ 4: 15 ần chọn là: C\\nKết luận: Đáp án đúng là C (Tổ 3 là 12, tổ 4 là 15).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4498, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Các môn thể thao được ưa thích của lớp 6a Các môn thể thao được yêu thích của lớp 6A là:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/cebd4c12cb09ea5eedc5d7c22f522e1515ddf898.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113926.PNG"}]}', '[{"key":"A","text":"Cầu lông, bóng bàn, đá cầu, bóng rổ, bóng đá"},{"key":"B","text":"Bóng chuyền, bóng bàn, bóng đá, đá cầu, bóng rổ"},{"key":"C","text":"Đá cầu, bóng chuyền, điền kinh, bóng rổ, bóng bàn"},{"key":"D","text":"Bóng rổ, đá cầu, bóng đá"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Các môn thể thao được ưa thích của lớp 6a Các môn thể thao được yêu thích của lớp 6A là:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Các môn thể thao được yêu thích của lớp 6A là: Bóng đá, cầu lông, bóng bàn, đá cầu, bóng rổ.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (Đá cầu, bóng chuyền, điền kinh, bóng rổ, bóng bàn).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4499, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Số học sinh vắng trong ngày của các lớp khối 6 trường THCS A là 6A1 6A2 6A3 6A4 6A5 6A6 6A7 6A8 Có bao nhiêu lớp có số học sinh vắng ít nhất","images":[]}', '[{"key":"A","text":"4"},{"key":"B","text":"5"},{"key":"C","text":"1"},{"key":"D","text":"2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Số học sinh vắng trong ngày của các lớp khối 6 trường THCS A là 6A1 6A2 6A3 6A4 6A5 6A6 6A7 6A8 Có bao nhiêu lớp có số học sinh vắng ít nhất\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số học sinh vắng ít nhất trong một lớp là 1 Lớp có số học sinh vắng ít nhất là lớp 6A4 , 6A8 Vậy có 2 lớp có số học sinh vắng ít nhất.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (1).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4500, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Em hãy chỉ ra các điểm không hợp lí trong bảng dữ liệu sau: Danh sách học sinh giỏi lớp 7A STT Họ và tên 1 Nguyễn Hoàng Xuân 2 Phạm Thị Hương 3 Đỗ Thu Hà 4 03456789 Ngô Xuân Giang","images":[]}', '[{"key":"A","text":"Nguyễn Hoàng Xuân"},{"key":"B","text":"03456789"},{"key":"C","text":"Phạm Thị Hương"},{"key":"D","text":"Ngô Xuân Giang"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Em hãy chỉ ra các điểm không hợp lí trong bảng dữ liệu sau: Danh sách học sinh giỏi lớp 7A STT Họ và tên 1 Nguyễn Hoàng Xuân 2 Phạm Thị Hương 3 Đỗ Thu Hà 4 03456789 Ngô Xuân Giang\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Họ và tên phải là chữ nên 03456789 không thể là họ và tên của một người ần chọn là: B\\nKết luận: Đáp án đúng là C (Phạm Thị Hương).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4501, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Có bao nhiêu điểm không hợp lí trong cột “email” của bảng dữ liệu: Danh sách email của các bạn tổ 1 lớp 6D","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/4ab782162454a4dc2b2c6939b5386c7da407f2dd.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113927.PNG"}]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Có bao nhiêu điểm không hợp lí trong cột “email” của bảng dữ liệu: Danh sách email của các bạn tổ 1 lớp 6D\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Ở bảng 4, Email của bạn Cúc và bạn Đào không hợp lí vì không đúng theo cú pháp của email (Email phải có @) ần chọn là: B\\nKết luận: Đáp án đúng là C (3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4502, 288, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Cho bảng số liệu đánh giá chất lượng sản phẩm bằng điểm số 1, 2, 3, 4, 5 của một lô hàng gồm 15 sản phẩm như sau: Điểm Số sản phẩm 0 7 Đối tượng thống kê là","images":[]}', '[{"key":"A","text":"Các điểm số 1, 2, 3, 4, 5."},{"key":"B","text":"Số sản phẩm 3,0,5,7,0"},{"key":"C","text":"Điểm số và sản phẩm"},{"key":"D","text":"Lô hàng"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho bảng số liệu đánh giá chất lượng sản phẩm bằng điểm số 1, 2, 3, 4, 5 của một lô hàng gồm 15 sản phẩm như sau: Điểm Số sản phẩm 0 7 Đối tượng thống kê là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Bảng trên có thông tin về số sản phẩm đạt từng loại điểm 1, 2, 3, 4, 5 nên đối tượng thống kê là các điểm số 1,2,3,4,5.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (Điểm số và sản phẩm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4503, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Bạn Hùng ghi chép nhanh điểm Toán của các bạn trong tổ 1 của lớp 6A5 thành dãy dữ liệu: 5, 8, 6, 7, 8, 5, 4, 6, 9, 6, 8, 8. Em hãy giúp Hùng sắp xếp lại dữ liệu trên vào bảng sau (theo mẫu): Em hãy cho biết có bao nhiêu bạn được điểm 8 và có bao nhiêu bạn có điểm dưới 6.","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/40eb5848463b098556b9e39633b1ca5e42837366.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113928.PNG"}]}', '[{"key":"A","text":"4 bạn được 8 và 2 bạn dưới 6."},{"key":"B","text":"4 bạn được 8 và 3 bạn dưới 6"},{"key":"C","text":"4 bạn được 8 và 6 bạn dưới 6"},{"key":"D","text":"1 bạn được 8 và 3 bạn dưới 6"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Bạn Hùng ghi chép nhanh điểm Toán của các bạn trong tổ 1 của lớp 6A5 thành dãy dữ liệu: 5, 8, 6, 7, 8, 5, 4, 6, 9, 6, 8, 8. Em hãy giúp Hùng sắp xếp lại dữ liệu trên vào bảng sau (theo mẫu): Em hãy cho biết có bao nhiêu bạn được điểm 8 và có bao nhiêu bạn có điểm dưới 6.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Cách điền: Tổ 1 của lớp 6A5 có 12 bạn đạt các điểm toán là: 9;\\n8;\\n7;\\n6;\\n5;\\n4.\\nTrong các số 5, 8, 6, 7, 8, 5, 4, 6, 9, 6, 8, 8 có 1 số 9 nên số bạn được 9 là 1.\\n=> Ta điền 1 vào ô dưới điểm 9.\\nSố bạn được 8 là 4 nên ta điền 4 vào ô dưới điểm 8 Tương tự với số bạn được 7;\\n6;\\n5;\\n4.\\nĐiểm dưới 6 là 5 và 4 Số bạn được 5 là 2 và số bạn được 4 là 1 nên tổng số bạn dưới 6 là 2+1=3 bạn.\\nDựa vào bảng trên ta thấy có 4 bạn được điểm 8 và 3 bạn có điểm dưới 6.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (4 bạn được 8 và 6 bạn dưới 6).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/02b5823cdb1568f0a184ec6d27d96a7dac690355.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113929.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4504, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Hãy đọc bảng thống kê xếp loại hạnh kiểm lớp 6A sau: Em hãy cho biết lớp 6A có tất cả bao nhiêu học sinh?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/ae42b238e63de6c24543e58c844fd5b84c02a557.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113930.PNG"}]}', '[{"key":"A","text":"25"},{"key":"B","text":"3"},{"key":"C","text":"2"},{"key":"D","text":"30"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Hãy đọc bảng thống kê xếp loại hạnh kiểm lớp 6A sau: Em hãy cho biết lớp 6A có tất cả bao nhiêu học sinh?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số học sinh lớp 6A là: 25\\n+ 3\\n+ 2 = 30 (học sinh) ần chọn là: D\\nKết luận: Đáp án đúng là C (2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4505, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Điều tra loại phim yêu thích nhất của 36 học sinh lớp 6A3, bạn lớp trưởng thu được bảng dữ liệu ban đầu như sau: Viết tắt: H: Hoạt hình; L: Lịch sử; K: Khoa học; C: Ca nhạc; T: Trinh thám. Loại phim nào được các bạn học sinh lớp 6A3 yêu thích nhất?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/2494f952585f38f1670cf6029ac2b1b324e01ae1.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113931.PNG"}]}', '[{"key":"A","text":"Hoạt hình"},{"key":"B","text":"Lịch sử"},{"key":"C","text":"Khoa học"},{"key":"D","text":"Trinh thám"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Điều tra loại phim yêu thích nhất của 36 học sinh lớp 6A3, bạn lớp trưởng thu được bảng dữ liệu ban đầu như sau: Viết tắt: H: Hoạt hình; L: Lịch sử; K: Khoa học; C: Ca nhạc; T: Trinh thám. Loại phim nào được các bạn học sinh lớp 6A3 yêu thích nhất?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số chữ H là 11, số chữ L là 6, số chữ K là 4, số chữ C là 7, số chữ T là 8.\\nBảng thống kế các bộ phim yêu thích của các học sinh lớp 6A3 là: Loại phim Hoạt hình Lịch sử Khoa học Ca nhạc Trinh thám Số bạn thích 11 6 4 7 8 Phim hoạt hình có số bạn là 11 nên loại phim hoạt hình được các bạn học sinh lớp 6A3 yêu thích nhất.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (Khoa học).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4506, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Một nhóm bạn thân gồm 6 người đi đến một quán trà chanh và mua các loại nước uống và các loại nước uống được ghi lại trong bảng sau: Nước cam Nước dưa hấu Nước chanh Nước dứa Có bao nhiêu loại nước được mua?","images":[]}', '[{"key":"A","text":"5"},{"key":"B","text":"4"},{"key":"C","text":"3"},{"key":"D","text":"2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một nhóm bạn thân gồm 6 người đi đến một quán trà chanh và mua các loại nước uống và các loại nước uống được ghi lại trong bảng sau: Nước cam Nước dưa hấu Nước chanh Nước dứa Có bao nhiêu loại nước được mua?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Có 4 loại nước được mua: Nước cam, nước dưa hấu, nước chanh, nước dứa.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4507, 288, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Lan tìm hiểu về thức ăn sáng nay của các bạn trong lớp và thu được kết quả như sau: Dữ liệu nào sau đây không là số liệu?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/7e607a1286dc88199dc74b9c9fdb624e67c70b80.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113932.PNG"}]}', '[{"key":"A","text":"Xôi"},{"key":"B","text":"11"},{"key":"C","text":"8"},{"key":"D","text":"2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Lan tìm hiểu về thức ăn sáng nay của các bạn trong lớp và thu được kết quả như sau: Dữ liệu nào sau đây không là số liệu?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Xôi không là số nên không là số liệu.\\nần chọn là: A\\nKết luận: Đáp án đúng là C (8).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4508, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Cho biểu đồ tranh số học sinh khối lớp 6 được điểm 10 môn Toán trong tuần như sau: Số học sinh được điểm 10 môn Toán vào Thứ Tư là bao nhiêu?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/ba3c0e5456c7491e58ae47d5a2e561c18c25c929.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113933.PNG"}]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"5"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho biểu đồ tranh số học sinh khối lớp 6 được điểm 10 môn Toán trong tuần như sau: Số học sinh được điểm 10 môn Toán vào Thứ Tư là bao nhiêu?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Thứ Tư có 4 hình tròn tương ứng với 4 học sinh được điểm 10 môn Toán.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (5).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4509, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Biểu đồ tranh dưới đây cho biết số ti vi (TV) bán được qua các năm của siêu thị điện máy A. Năm nào siêu thị điện máy bán được nhiều TV nhất?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/2ccb464969c30b54510dfba46b2b646672885cf6.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113934.PNG"}]}', '[{"key":"A","text":"2017"},{"key":"B","text":"2018"},{"key":"C","text":"2019"},{"key":"D","text":"2020"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Biểu đồ tranh dưới đây cho biết số ti vi (TV) bán được qua các năm của siêu thị điện máy A. Năm nào siêu thị điện máy bán được nhiều TV nhất?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Số ti vi bán được qua các năm ở siêu thị điện máy A là:\\n+ Năm 2016: 500.\\n2 = 1 000 TV\\n+ Năm 2017: 500.\\n3 = 1 500 TV\\n+ Năm 2018: 500\\n+ 250 = 750 TV\\n+ Năm 2019: 500.\\n4 = 2 000 TV\\n+ Năm 2020: 500.\\n6 = 3 000 TV - Năm 2020 bán được số ti vi nhiều nhất (3 000 TV).\\nần chọn là: D\\nKết luận: Đáp án đúng là C (2019).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4510, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Biểu đồ tranh dưới đây cho ta thông tin về loại quả yêu thích của các bạn học sinh khối lớp 6. Trong biểu đồ trên, nếu số bạn yêu thích quả táo là 45 thì ta phải vẽ thêm bao nhiêu biểu tượng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/6bd06519df44cd8a9184f09d4a73252e26e5f4ad.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113935.PNG"}]}', '[{"key":"A","text":"20"},{"key":"B","text":"1"},{"key":"C","text":"2"},{"key":"D","text":"4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Biểu đồ tranh dưới đây cho ta thông tin về loại quả yêu thích của các bạn học sinh khối lớp 6. Trong biểu đồ trên, nếu số bạn yêu thích quả táo là 45 thì ta phải vẽ thêm bao nhiêu biểu tượng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: 10.\\n2\\n+ 5 = 25 => Táo được 25 học sinh yêu thích.\\nNếu số bạn yêu thích quả táo là 45 thì số táo tăng thêm là: 45 – 25 = 20 (học sinh) Số biểu tượng cần vẽ là 20: 10=2 (biểu tượng) Vậy phải vẽ thêm 2 biểu tượng ngôi sao.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (2).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4511, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Một cửa hàng bán kính ghi lại số kính bán được trong tháng bằng bảng số liệu sau: Số kính bán được trong tháng Màu kính Trắng Đen Xanh Trắng bạc Vàng kim Số lượng 20 10 30 15 25 Sử dụng các biểu tượng sau để vẽ biểu đồ tranh Cần bao nhiêu biểu tượng hình tròn màu tím để biểu diễn số kính màu vàng kim?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/41c27dc235a9cebc6e178e3d451abc5d52dd2151.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113936.PNG"}]}', '[{"key":"A","text":"25"},{"key":"B","text":"4"},{"key":"C","text":"5"},{"key":"D","text":"6"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một cửa hàng bán kính ghi lại số kính bán được trong tháng bằng bảng số liệu sau: Số kính bán được trong tháng Màu kính Trắng Đen Xanh Trắng bạc Vàng kim Số lượng 20 10 30 15 25 Sử dụng các biểu tượng sau để vẽ biểu đồ tranh Cần bao nhiêu biểu tượng hình tròn màu tím để biểu diễn số kính màu vàng kim?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Màu trắng có 20 chiếc, ta vẽ 20: 5=4 hình tròn.\\nTương tự với màu đen, ta vẽ 2 hình, màu xanh ta vẽ 6 hình, màu trắng bạc ta vẽ 3 hình và màu vàng kim vẽ 5 hình.\\nTừ bảng thống kê, ta vẽ được biểu đồ tranh như sau: ần chọn là: C\\nKết luận: Đáp án đúng là C (5).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/40ed0c19c9684cfa2985f8cefe3c78a574ff2631.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113937.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4512, 288, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Biểu đồ tranh dưới đây cho biết số học sinh nữ của các lớp khối 6 trường THCS Hoàng Việt. Em hãy quan sát biểu đồ tranh ở trên và chọn đáp án đúng","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/ee15973bf348861dd38fe48e7d89bfb851bea796.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113938.PNG"}]}', '[{"key":"A","text":"Lớp 6A1 có ít học sinh nữ nhất"},{"key":"B","text":"Lớp 6A4 có nhiều học sinh nữ hơn lớp 6A5"},{"key":"C","text":"Lớp 6A6 có 20 học sinh nữ."},{"key":"D","text":"Tổng số học sinh nữ của các lớp khối 6 là 120 học sinh"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Biểu đồ tranh dưới đây cho biết số học sinh nữ của các lớp khối 6 trường THCS Hoàng Việt. Em hãy quan sát biểu đồ tranh ở trên và chọn đáp án đúng\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số học sinh nữ.\\nLớp 6A1: 2.\\n10 = 20 học sinh nữ Lớp 6A2: 3.\\n10 = 30 học sinh nữ Lớp 6A3: 1.\\n10 = 10 học sinh nữ Lớp 6A4: 2.\\n10 = 20 học sinh nữ Lớp 6A5: 3.\\n10 = 30 học sinh nữ Lớp 6A6: 2.\\n10 = 20 học sinh nữ Lớp 6A3 có ít học sinh nữ nhất (10 học sinh) => A sai Lớp 6A5 có 30 học sinh nữ, lớp 6A4 có 20 học sinh nữ => Lớp 6A4 có ít học sinh nữ hơn lớp 6A5.\\n=> B sai.\\nLớp 6A6 có 20 học sinh nữ.\\n=> C đúng.\\nTổng số học sinh nữ của các lớp khối 6 là: 20\\n+ 30\\n+ 10\\n+ 20\\n+ 30\\n+ 20 = 130 học sinh.\\n=> D sai.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (Lớp 6A6 có 20 học sinh nữ.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4513, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Dân số Việt Nam trong năm 1989 là","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/1028ba0ed0d13b5b8ab7e7f5c65bf7200ffadb0b.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113939.PNG"}]}', '[{"key":"A","text":"67 nghìn người"},{"key":"B","text":"87 nghìn người"},{"key":"C","text":"67 triệu người"},{"key":"D","text":"79 nghìn người"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Dân số Việt Nam trong năm 1989 là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Từ biểu đồ trên ta thấy dân số Việt Nam năm 1989 là 67 triệu người.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (67 triệu người).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4514, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Số con vật nuôi của học sinh trong lớp 6A1 là Con vật nào được nuôi nhiều nhất","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/3ab7dbde38e92f36c2132136b5f925e7a1be0040.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113940.PNG"}]}', '[{"key":"A","text":"Chó"},{"key":"B","text":"Mèo"},{"key":"C","text":"Cá"},{"key":"D","text":"Chim"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Số con vật nuôi của học sinh trong lớp 6A1 là Con vật nào được nuôi nhiều nhất\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số chó được nuôi là 5 con Số mèo là 10 con Số cá là 7 con Số chim là 4 con Vậy mèo được nuôi nhiều nhất.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (Cá).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4515, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Biểu đồ cột dưới đây cho biết thông tin về kết quả học lực của học sinh khối 6 trường THCS Quang Trung. Số lượng học sinh học lực trung bình ít hơn số lượng học sinh học lực khá là","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/dc37a5cdc8b0135ca54d0a0d8b11048a2f0705cd.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113941.PNG"}]}', '[{"key":"A","text":"88 học sinh"},{"key":"B","text":"90 học sinh"},{"key":"C","text":"102 học sinh"},{"key":"D","text":"140 học sinh"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Biểu đồ cột dưới đây cho biết thông tin về kết quả học lực của học sinh khối 6 trường THCS Quang Trung. Số lượng học sinh học lực trung bình ít hơn số lượng học sinh học lực khá là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số học sinh khá là 140 và số học sinh trung bình là 52.\\nSố học sinh học lực trung bình ít hơn số lượng học sinh học lực khá là 140 - 52=88 (học sinh).\\nần chọn là: A\\nKết luận: Đáp án đúng là C (102 học sinh).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4516, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Biểu đồ cột dưới đây cho biết thông tin về kết quả học lực của học sinh khối 6 trường THCS Quang Trung. Số học sinh trên trung bình là","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/3b9cfae2ac00846772a42f4605037cfb01e35456.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113942.PNG"}]}', '[{"key":"A","text":"140"},{"key":"B","text":"178"},{"key":"C","text":"180"},{"key":"D","text":"38"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Biểu đồ cột dưới đây cho biết thông tin về kết quả học lực của học sinh khối 6 trường THCS Quang Trung. Số học sinh trên trung bình là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Trong đó có 38 học sinh giỏi và 140 học sinh khá.\\nVậy trường THCS Quang Trung có: 38\\n+ 140 = 178 học sinh khối 6 có xếp loại học lực trên trung bình.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (180).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4517, 288, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Nếu số bạn lớp 6B tăng thêm một bạn và bạn đó thích mận thì cột mận tăng thêm bao nhiêu đơn vị?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/f010f9e7339ed9d01ad68357db1d3da75ce52f42.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113943.PNG"}]}', '[{"key":"A","text":"6"},{"key":"B","text":"1"},{"key":"C","text":"7"},{"key":"D","text":"2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Nếu số bạn lớp 6B tăng thêm một bạn và bạn đó thích mận thì cột mận tăng thêm bao nhiêu đơn vị?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số bạn thích mận tăng 1 bạn nên chiều cao của cột “Mận” tăng 1 đơn vị.\\nBiểu đồ cột là: ần chọn là: B\\nKết luận: Đáp án đúng là C (7).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/3a750ed9a58e98f53ff2c9cb878cdb00f613793d.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113944.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4518, 288, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Điểm thi học kì 1 của bạn Hùng đối với các môn được ghi lại trong bảng sau: Môn học Ngữ văn Toán Ngoại ngữ 1 Giáo dục công dân Lịch sử và Địa lí Khoa học tự nhiên Điểm thi HKI 6 7 5 Biểu đồ cột biểu diễn bảng trên là Trả lời: Ngữ văn: Chiều cao 6 Toán, ngoại ngữ 1 và giáo dục công dân chiều cao 7. Lịch sử và Địa lí chiều cao 6 Khoa học tự nhiên chiều cao 5. Vậy ta có biểu đồ cột: Đáp án cần chọn là: B Câu hỏi. Bạn An tìm kiếm thông tin trên mạng Internet và lập được bảng về tuổi số của một số loài động vật trong vườn thú như sau: Tên động vật Tuổi thọ (năm) Thỏ 10 Cáo 22 Hươu cao cổ 28 Cá voi cái 29 Sư tử 35 Gấu trắng 30 Khi đó:","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/a7971e2f665dd1f4590567688ce89a1babbf5544.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113945.PNG"},{"id":"img-2","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/31106e7579bb15fd3e17d7a9277df22dda6bb4ad.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113946.PNG"},{"id":"img-3","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/ace9c42d63c856ef3e0133f097ef8701440ce93b.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113947.PNG"},{"id":"img-4","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/402d925f96e0f216b0f110baccee78ba5f3842d7.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113948.PNG"}]}', '[{"key":"A","text":"Bạn An thu thập các thông tin trên thông qua những nguồn có sẵn."},{"key":"B","text":"Từ bảng trên, ta thu được 2 dãy dữ liệu là: Tên loài động vật và tuổi thọ của các loài động vật đó."},{"key":"C","text":"Dữ liệu về tên động vật là dữ liệu không là số."},{"key":"D","text":"Các dãy dữ liệu thu được đều là dữ liệu không là số."}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Điểm thi học kì 1 của bạn Hùng đối với các môn được ghi lại trong bảng sau: Môn học Ngữ văn Toán Ngoại ngữ 1 Giáo dục công dân Lịch sử và Địa lí Khoa học tự nhiên Điểm thi HKI 6 7 5 Biểu đồ cột biểu diễn bảng trên là Trả lời: Ngữ văn: Chiều cao 6 Toán, ngoại ngữ 1 và giáo dục công dân chiều cao 7. Lịch sử và Địa lí chiều cao 6 Khoa học tự nhiên chiều cao 5. Vậy ta có biểu đồ cột: Đáp án cần chọn là: B Câu hỏi. Bạn An tìm kiếm thông tin trên mạng Internet và lập được bảng về tuổi số của một số loài động vật trong vườn thú như sau: Tên động vật Tuổi thọ (năm) Thỏ 10 Cáo 22 Hươu cao cổ 28 Cá voi cái 29 Sư tử 35 Gấu trắng 30 Khi đó:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\na) Đúng.\\nBạn An tìm kiếm thông tin trên mạng Internet nên bạn An thu thập các thông tin trên thông qua những nguồn có sẵn.\\nVậy a) đúng.\\nb) Đúng.\\nTừ bảng trên, ta thu được 2 dãy dữ liệu là: Tên loài động vật và tuổi thọ của các loài động vật đó.\\nVậy b) đúng.\\nc) Đúng.\\nDữ liệu về tên động vật là dữ liệu không là số.\\nVậy c) đúng.\\nd) Sai.\\nDữ liệu về tên động vật là dữ liệu không là số còn dữ liệu về tuổi thọ của các loài động vật đó là số liệu.\\nVậy d) sai.\\nKết luận: Đáp án đúng là A (Bạn An thu thập các thông tin trên thông qua những nguồn có sẵn.).","images":[{"id":"explanation-img-1","alt":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/bbb1453630a0c14f8b1edac63083cc49fe12a065.png","width":"","height":"","alt_text":"10+ Bài tập trắc nghiệm Thu thập, tổ chức, biểu diễn, phân tích và xử lí dữ liệu (có đáp án) | Toán lớp 6 Cánh diều","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-1-thu-thap-to-chuc-bieu-dien-phan-tich-va-xu-li-du-lieu-113949.PNG"}]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4519, 288, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Trong các dữ liệu sau, có bao nhiêu dữ liệu là số?","images":[]}', '[{"key":"A","text":"Cân nặng của các bạn nam trong lớp 6A (đơn vị tính là )."},{"key":"B","text":"Phường mà các bạn sinh sống trong lớp 6C."},{"key":"C","text":"Số thành viên trong gia đình của các học sinh lớp 6E."},{"key":"D","text":"Loài hoa yêu thích của các bạn học sinh lớp 6D."}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong các dữ liệu sau, có bao nhiêu dữ liệu là số?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nCác dữ liệu trong các phần a), c), e), f).\\nDo đó, có 4 dữ liệu là số liệu.\\nKết luận: Đáp án đúng là A (Cân nặng của các bạn nam trong lớp 6A (đơn vị tính là ).).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4520, 289, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Điểm thi của Nam và Khải được biểu diễn trong biểu đồ cột kép ở hình sau: Khẳng định nào sau đây đúng ?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/f6d316e07e2e13449b0e67680ffe6dd8df631593.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113965.PNG"}]}', '[{"key":"A","text":"Điểm Toán của Nam cao hơn Khải"},{"key":"B","text":"Điểm cả 3 môn của Khải cao hơn Nam"},{"key":"C","text":"Điểm Ngữ văn của Nam cao hơn Khải"},{"key":"D","text":"Điểm Ngữ văn của Khải cao hơn Nam"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Điểm thi của Nam và Khải được biểu diễn trong biểu đồ cột kép ở hình sau: Khẳng định nào sau đây đúng ?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Điểm toán của Nam thấp hơn Khải => A sai.\\nĐiểm Ngữ văn của Nam cao hơn Khải.\\nTức là điểm Ngữ văn của Khải thấp hơn Nam nên điểm 3 môn của Khải cao hơn Nam là sai => B sai, C đúng và D sai.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (Điểm Ngữ văn của Nam cao hơn Khải).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4521, 289, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Điểm thi của Nam và Khải được biểu diễn trong biểu đồ cột kép ở hình sau: Điểm cao nhất thuộc về bạn nào, môn nào?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/63a67c67d7f6de94554774afe6947d539ab37f6f.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113966.PNG"}]}', '[{"key":"A","text":"Bạn Nam môn Tiếng Anh"},{"key":"B","text":"Bạn Nam môn Toán"},{"key":"C","text":"Bạn Khải môn Toán"},{"key":"D","text":"Bạn Khải môn Ngữ văn"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Điểm thi của Nam và Khải được biểu diễn trong biểu đồ cột kép ở hình sau: Điểm cao nhất thuộc về bạn nào, môn nào?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Cột cao nhất là cột màu xanh, môn Toán.\\nVậy điểm cao nhất thuộc về bạn Khải môn Toán.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (Bạn Khải môn Toán).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4522, 289, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Quan sát biểu đồ trong Hình 6, em hãy cho biết nó được ghép bởi","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/c392784af07bdaf3c541de81b9fc4b2e2481a95d.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113967.PNG"}]}', '[{"key":"A","text":"Biểu đồ số cây hoa trồng được của lớp 6A2 và 6A3"},{"key":"B","text":"Biểu đồ số cây hoa trồng được của lớp 6A2"},{"key":"C","text":"Biểu đồ số cây hoa trồng được của lớp 6A3"},{"key":"D","text":"Biểu đồ số cây hoa trồng được của lớp 6A1 và 6A2."}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Quan sát biểu đồ trong Hình 6, em hãy cho biết nó được ghép bởi\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Biểu đồ hình 6 được ghép bởi 2 biểu đồ: - Biểu đồ số cây hoa trồng được của lớp 6A1 - Biểu đồ số cây hoa trồng được của lớp 6A2 ần chọn là: D\\nKết luận: Đáp án đúng là C (Biểu đồ số cây hoa trồng được của lớp 6A3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4523, 289, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Cho biểu đồ cột ghép điểm học kì 1 của bạn Hải và bạn Lan như sau: Môn Ngữ văn của bạn Lan bằng bao nhiêu?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/43b789fdac6799c56c9bd80b57d77f7a9720f239.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113973.PNG"}]}', '[{"key":"A","text":"8"},{"key":"B","text":"7"},{"key":"C","text":"6"},{"key":"D","text":"9"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho biểu đồ cột ghép điểm học kì 1 của bạn Hải và bạn Lan như sau: Môn Ngữ văn của bạn Lan bằng bao nhiêu?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Điểm của bạn Lan là màu đỏ và hàng Ngữ văn nên số điểm Ngữ văn của Lan là 7.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (6).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4524, 289, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Cho biểu đồ cột ghép điểm học kì 1 của bạn Hải và bạn Lan như sau: Điểm Toán của Lan cao hơn Hải là bao nhiêu điểm?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/63cee304ad24a5b90dd35561617a2c4fe23c040a.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113974.PNG"}]}', '[{"key":"A","text":"8 điểm"},{"key":"B","text":"0 điểm"},{"key":"C","text":"1 điểm"},{"key":"D","text":"2 điểm"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Cho biểu đồ cột ghép điểm học kì 1 của bạn Hải và bạn Lan như sau: Điểm Toán của Lan cao hơn Hải là bao nhiêu điểm?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Điểm toán của Lan là 8 và của Hải là 7.\\nĐiểm toán của Lan cao hơn của Hải là 8-7=1 điểm.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (1 điểm).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4525, 289, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Biểu đồ cột kép biểu diễn sĩ số học sinh đầu năm học và cuối năm học của bốn lớp khối 6: Sĩ số của lớp nào tăng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/783365415776f2ed902c4a9a5a95a6d6aed92b4f.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113975.PNG"}]}', '[{"key":"A","text":"6A1"},{"key":"B","text":"6A2"},{"key":"C","text":"6A3"},{"key":"D","text":"6A4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Biểu đồ cột kép biểu diễn sĩ số học sinh đầu năm học và cuối năm học của bốn lớp khối 6: Sĩ số của lớp nào tăng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Sĩ số của lớp 6A2 tăng vì sĩ số đầu năm là 35 và cuối năm là 38.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (6A3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4526, 289, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Biểu đồ cột kép biểu diễn sĩ số học sinh đầu năm học và cuối năm học của bốn lớp khối 6: Sĩ số đầu năm của lớp nào cao nhất?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/27984e0cfa52d89a04bcca873a37e60c56a03832.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113976.PNG"}]}', '[{"key":"A","text":"6A2"},{"key":"B","text":"6A1"},{"key":"C","text":"6A3"},{"key":"D","text":"6A4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Biểu đồ cột kép biểu diễn sĩ số học sinh đầu năm học và cuối năm học của bốn lớp khối 6: Sĩ số đầu năm của lớp nào cao nhất?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Sĩ số đầu năm của lớp 6A4 là cao nhất trong 4 lớp.\\nần chọn là: D\\nKết luận: Đáp án đúng là C (6A3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4527, 289, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Cho biểu đồ cột kép sau: Số con cá của tổ 3 và tổ 4 nuôi trong biểu đồ ở hình trên là","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/1b56bca5ea473dfec4f3c8298c0a4aae554f5c48.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-113977.PNG"}]}', '[{"key":"A","text":"Tổ 3 là 10, tổ 4 là 14"},{"key":"B","text":"Tổ 3 là 12, tổ 4 là 16"},{"key":"C","text":"Tổ 3 là 12, tổ 4 là 15"},{"key":"D","text":"Tổ 3 là 15, tổ 4 là 12"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Cho biểu đồ cột kép sau: Số con cá của tổ 3 và tổ 4 nuôi trong biểu đồ ở hình trên là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số cá tổ 3: 12 Số cá tổ 4: 15 ần chọn là: C\\nKết luận: Đáp án đúng là C (Tổ 3 là 12, tổ 4 là 15).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4528, 289, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Biểu đồ dưới đây biểu diễn số xe máy bán được của bốn cửa hàng phân phối của một hãng xe máy trong hai tháng cuối năm: Phát biểu nào sau đây là đúng?","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/2063486195a0a6f8f5b1f6d06838b9bfcd1ecc6c.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-1.PNG"},{"id":"img-2","alt":"10+ Bài tập trắc nghiệm Biểu đồ cột kép (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/069e8e15cae96ed2c6337b04bd0a1576a7aeee13.png","width":"","height":"","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-2-bieu-do-cot-kep-2.PNG"}]}', '[{"key":"A","text":"Cửa hàng 1 bán được nhiều xe hơn cửa hàng 2."},{"key":"B","text":"Cửa hàng 3 bán được nhiều xe hơn cửa hàng 2 là 10 xe."},{"key":"C","text":"Cửa hàng 4 bán được nhiều xe nhất."},{"key":"D","text":"Tháng 11 bán được nhiều xe hơn tháng 12."}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Biểu đồ dưới đây biểu diễn số xe máy bán được của bốn cửa hàng phân phối của một hãng xe máy trong hai tháng cuối năm: Phát biểu nào sau đây là đúng?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\na) Đúng.\\nSố xe mẫu N bán được trong các năm 2023, 2024 và 2025 lần lượt là 45 chiếc, 60 chiếc và 100 chiếc.\\nVậy a) đúng.\\nb) Đúng.\\nVì 50 > 45 nên 2023, số chiếc xe mẫu M bán được nhiều hơn số xe mẫu N.\\nVậy b) đúng.\\nc) Sai.\\nVì 55 < 60, 45 < 100 nên năm 2024 và năm 2025 số xe mẫu M bán được ít hơn số xe mẫu N.\\nTheo ý b), 2023, số chiếc xe mẫu M bán được nhiều hơn số xe mẫu N.\\nSuy ra, có 1 năm số chiếc xe mẫu M bán được nhiều hơn số xe mẫu N.\\nVậy c) sai.\\nd) Sai.\\nVì 45 < 60 < 100 nên từ năm 2023 đến năm 2025, mẫu xe ô tô N bán được tăng qua mỗi năm.\\nVì 50 < 55, 55 > 45 nên từ năm 2023 đến năm 2025, mẫu xe ô tô M bán được không tăng qua mỗi năm.\\nVậy d) sai.\\nKết luận: Đáp án đúng là A (Cửa hàng 1 bán được nhiều xe hơn cửa hàng 2.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4529, 290, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Một hộp có 5 chiếc thẻ cùng loại, mỗi thẻ được ghi một trong các số 1, 2, 3, 4, 5; hai thẻ khác nhau thì ghi số khác nhau. Rút ngẫu nhiên một thẻ. Số xuất hiện trên thẻ được rút có phải là phần tử của tập hợp {1; 2; 3; 4; 5} hay không? Trả lời: Số có thể xuất hiện trên thẻ là một trong năm số: 1; 2; 3; 4; 5. Các số này đều là phần tử của tập hợp {1; 2; 3; 4; 5}. Phần II. Trắc nghiệm đúng, sai Câu hỏi. Hằng có 4 hộp bánh quy có kem với các vị: vị dâu, vị táo, vị cam, vị chanh leo. Bạn Hằng lấy ngẫu nhiên 2 hộp bánh cho em trai. Khi đó:","images":[]}', '[{"key":"A","text":"2 hộp bánh quy có kem vị dâu và vị táo là một kết quả có thể của hành động “Hằng lấy ngẫu nhiên hai hộp bánh”."},{"key":"B","text":"Em trai Hằng có thể được 2 hộp bánh quy kem có vị táo."},{"key":"C","text":"Với sự kiện “Hai hộp bánh đưa cho em trai Hằng có 1 hộp có vị dâu” thì có 2 kết quả có thể xảy ra."},{"key":"D","text":"Có tất cả 6 kết quả có thể xảy ra đối với hành động “Hằng lấy ngẫu nhiên hai hộp bánh”."}]', 'A', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Một hộp có 5 chiếc thẻ cùng loại, mỗi thẻ được ghi một trong các số 1, 2, 3, 4, 5; hai thẻ khác nhau thì ghi số khác nhau. Rút ngẫu nhiên một thẻ. Số xuất hiện trên thẻ được rút có phải là phần tử của tập hợp {1; 2; 3; 4; 5} hay không? Trả lời: Số có thể xuất hiện trên thẻ là một trong năm số: 1; 2; 3; 4; 5. Các số này đều là phần tử của tập hợp {1; 2; 3; 4; 5}. Phần II. Trắc nghiệm đúng, sai Câu hỏi. Hằng có 4 hộp bánh quy có kem với các vị: vị dâu, vị táo, vị cam, vị chanh leo. Bạn Hằng lấy ngẫu nhiên 2 hộp bánh cho em trai. Khi đó:\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\na) Đúng.\\nVì có một hộp bánh quy kem có vị dâu và một hộp bánh quy kem có vị táo nên 2 hộp bánh quy có kem vị dâu và vị táo là một kết quả có thể của hành động “lấy ngẫu nhiên hai hộp bánh”.\\nVậy a) đúng.\\nb) Sai.\\nVì chỉ có 1 hộp bánh quy kem có vị táo nên em trai Hằng không thể có được 2 hộp bánh kem quy có vị táo.\\nVậy b) sai.\\nc) Sai.\\nCó 3 kết quả có thể xảy ra với sự kiện “Hai hộp bánh đưa cho em trai Hằng có 1 hộp có vị dâu” là: Vị dâu và vị táo;\\nvị dâu và vị cam;\\nvị dâu và vị chanh leo.\\nVậy c) sai.\\nd) Đúng.\\nCó tất cả 6 kết quả có thể xảy ra đối với hành động “Hằng lấy ngẫu nhiên hai hộp bánh” là: Vị dâu và vị táo;\\nvị dâu và vị cam;\\nvị dâu và vị chanh leo;\\nvị táo và vị cam;\\nvị táo và vị chanh leo;\\nvị cam và vị chanh leo.\\nVậy d) đúng.\\nKết luận: Đáp án đúng là A (2 hộp bánh quy có kem vị dâu và vị táo là một kết quả có thể của hành động “Hằng lấy ngẫu nhiên hai hộp bánh”.).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4530, 291, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tung hai đồng xu cân đối 50 lần ta được kết quả như sau: Sự kiện Hai đồng sấp Một đồng sấp, một đồng ngửa Hai đồng ngửa Số lần 22 20 8 Xác suất thực nghiệm của sự kiện “Có một đồng xu sấp, một đồng xu ngửa” là","images":[]}', '[{"key":"A","text":"0,2"},{"key":"B","text":"0,4"},{"key":"C","text":"0,44"},{"key":"D","text":"0,16"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tung hai đồng xu cân đối 50 lần ta được kết quả như sau: Sự kiện Hai đồng sấp Một đồng sấp, một đồng ngửa Hai đồng ngửa Số lần 22 20 8 Xác suất thực nghiệm của sự kiện “Có một đồng xu sấp, một đồng xu ngửa” là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Số lần tung là 50.\\n- Số lần sự kiện “Có một đồng xu sấp, một đồng xu ngửa” xảy ra là 20.\\n- Xác suất thực nghiệm của sự kiện trên là 20: 50 = 0,4 ần chọn là: B\\nKết luận: Đáp án đúng là C (0,44).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4531, 291, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Tung hai đồng xu cân đối 50 lần ta được kết quả như sau: Sự kiện Hai đồng sấp Một đồng sấp, một đồng ngửa Hai đồng ngửa Số lần 22 20 8 Xác suất thực nghiệm của sự kiện “Hai đồng xu đều sấp”","images":[]}', '[{"key":"A","text":"0,22"},{"key":"B","text":"0,4"},{"key":"C","text":"0,44"},{"key":"D","text":"0,16"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tung hai đồng xu cân đối 50 lần ta được kết quả như sau: Sự kiện Hai đồng sấp Một đồng sấp, một đồng ngửa Hai đồng ngửa Số lần 22 20 8 Xác suất thực nghiệm của sự kiện “Hai đồng xu đều sấp”\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: - Số lần tung là 50.\\n- Số lần sự kiện “Có một đồng xu sấp, một đồng xu ngửa” xảy ra là 22.\\n- Xác suất thực nghiệm của sự kiện trên là là 22: 50=0,4422: 50=0,44.\\nần chọn là: C\\nKết luận: Đáp án đúng là C (0,44).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4532, 291, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":". Gieo một con xúc xắc 6 mặt 50 lần ta được kết quả như sau: Mặt 1 chấm 2 chấm 3 chấm 4 chấm 5 chấm 6 chấm Số lần 8 7 12 10 Hãy tính xác suất thực nghiệm của sự kiện gieo được mặt có số lẻ chấm trong 50 lần gieo trên.","images":[]}', '[{"key":"A","text":"0,21"},{"key":"B","text":"0,44"},{"key":"C","text":"0,42"},{"key":"D","text":"0,18"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Gieo một con xúc xắc 6 mặt 50 lần ta được kết quả như sau: Mặt 1 chấm 2 chấm 3 chấm 4 chấm 5 chấm 6 chấm Số lần 8 7 12 10 Hãy tính xác suất thực nghiệm của sự kiện gieo được mặt có số lẻ chấm trong 50 lần gieo trên.\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số lần gieo là 50.\\nCác mặt có số lẻ chấm của con xúc xắc là mặt 1, 3 và 5.\\nSố lần được mặt 1 chấm là 8 lần, mặt 3 chấm là 3 lần, mặt 5 chấm là 10 lần.\\nSố lần được mặt có số lẻ chấm là 8+3+10=21 lần Xác suất thực nghiệm của sự kiện gieo được mặt có số lẻ chấm trong 50 lần là: 21 50 = 0,42 ần chọn là: C\\nKết luận: Đáp án đúng là C (0,42).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4533, 291, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Hằng ngày Sơn đều đi xe buýt đến trường. Sơn ghi lại thời gian chờ xe của mình trong 20 lần liên tiếp ở bảng sau: Hãy tính xác suất thực nghiệm của sự kiện “ Sơn phải chờ xe dưới 2 phút ”","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Xác suất thực nghiệm trong một trò chơi và thí nghiệm đơn giản (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/a329d77ccbb8c1c335e0064b37a15e9e1451c424.png","width":"446","height":"107","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-xac-suat-thuc-nghiem-trong-mot-tro-choi-va-thi-nghiem-don-gian-113978.PNG"}]}', '[{"key":"A","text":"0,2"},{"key":"B","text":"5"},{"key":"C","text":"0,5"},{"key":"D","text":"0,25"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hằng ngày Sơn đều đi xe buýt đến trường. Sơn ghi lại thời gian chờ xe của mình trong 20 lần liên tiếp ở bảng sau: Hãy tính xác suất thực nghiệm của sự kiện “ Sơn phải chờ xe dưới 2 phút ”\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số lần Sơn chờ xe là 20 lần.\\nSố lần Sơn phải chờ xe dưới 2 phút là 5 lần.\\nXác suất thực nghiệm của sự kiện “ Sơn phải chờ xe dưới 2 phút ” là: 5 20 = 0,25 ần chọn là: D\\nKết luận: Đáp án đúng là C (0,5).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4534, 291, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Hằng ngày Sơn đều đi xe buýt đến trường. Sơn ghi lại thời gian chờ xe của mình trong 20 lần liên tiếp ở bảng sau: Hãy tính xác suất thực nghiệm của sự kiện “ Sơn phải chờ xe từ 5 phút trở lên ”","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Xác suất thực nghiệm trong một trò chơi và thí nghiệm đơn giản (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/d76a6631fca304d83647ac5ad53da5703a52910c.png","width":"476","height":"112","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-xac-suat-thuc-nghiem-trong-mot-tro-choi-va-thi-nghiem-don-gian-113979.PNG"}]}', '[{"key":"A","text":"0,3"},{"key":"B","text":"6"},{"key":"C","text":"0,6"},{"key":"D","text":"0,2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hằng ngày Sơn đều đi xe buýt đến trường. Sơn ghi lại thời gian chờ xe của mình trong 20 lần liên tiếp ở bảng sau: Hãy tính xác suất thực nghiệm của sự kiện “ Sơn phải chờ xe từ 5 phút trở lên ”\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số lần Sơn chờ xe là 20 lần.\\nSố lần Sơn phải chờ xe từ 5 phút đến dưới 10 phút là: 4 lần Số lần Sơn phải chờ xe từ 10 phút trở lên là: 2 lần Số lần Sơn phải chờ xe từ 5 phút trở lên là: 4+2 = 6 lần.\\nXác suất của sự kiện “ Sơn phải chờ xe từ 5 phút trở lên ” là: 6 20 = 0,3 ần chọn là: A\\nKết luận: Đáp án đúng là C (0,6).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4535, 291, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Hằng ngày Sơn đều đi xe buýt đến trường. Sơn ghi lại thời gian chờ xe của mình trong 20 lần liên tiếp ở bảng sau: Hãy tính xác suất thực nghiệm của sự kiện “ Sơn phải chờ xe dưới 10 phút ”","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Xác suất thực nghiệm trong một trò chơi và thí nghiệm đơn giản (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/391ced883521d13906f19d26cb06abbd59a1adfe.png","width":"474","height":"106","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-xac-suat-thuc-nghiem-trong-mot-tro-choi-va-thi-nghiem-don-gian-113980.PNG"}]}', '[{"key":"A","text":"0,1"},{"key":"B","text":"0,2"},{"key":"C","text":"0,9"},{"key":"D","text":"0,5"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Hằng ngày Sơn đều đi xe buýt đến trường. Sơn ghi lại thời gian chờ xe của mình trong 20 lần liên tiếp ở bảng sau: Hãy tính xác suất thực nghiệm của sự kiện “ Sơn phải chờ xe dưới 10 phút ”\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số lần Sơn chờ xe là 20 lần.\\nSố lần Sơn phải chờ xe dưới 2 phút là 5 lần.\\nSố lần Sơn phải chờ xe từ 2 phút đến dưới 5 phút là 9 lần.\\nSố lần Sơn phải chờ xe từ 5 phút đến dưới 10 phút là 4 lần.\\nSố lần Sơn phải chờ xe dưới 10 phút là 5+9+4=18 lần.\\nXác suất thực nghiệm của sự kiện “ Sơn phải chờ xe dưới 10 phút ” là: 18 20 = 0,9 ần chọn là: C\\nKết luận: Đáp án đúng là C (0,9).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4536, 291, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Trong hộp có một số bút xanh, một số bút vàng và một số bút đỏ. lấy ngẫu nhiên 1 bút từ hộp, xem màu gì rồi trả lại. Lặp lại hoạt động trên 40 lần ta được kết quả như sau: Màu bút Bút xanh Bút vàng Bút đỏ Số lần 14 10 16 Tính xác suất thực nghiệm của sự kiện lấy được màu đỏ","images":[]}', '[{"key":"A","text":"0,16"},{"key":"B","text":"0,6"},{"key":"C","text":"0,4"},{"key":"D","text":"0,45"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong hộp có một số bút xanh, một số bút vàng và một số bút đỏ. lấy ngẫu nhiên 1 bút từ hộp, xem màu gì rồi trả lại. Lặp lại hoạt động trên 40 lần ta được kết quả như sau: Màu bút Bút xanh Bút vàng Bút đỏ Số lần 14 10 16 Tính xác suất thực nghiệm của sự kiện lấy được màu đỏ\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số lần lấy là 40.\\nSố lần lấy được màu đỏ là 16.\\nXác suất thực nghiệm của sự kiện lấy được màu đỏ là: 16 40 = 0,4 ần chọn là: C\\nKết luận: Đáp án đúng là C (0,4).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4537, 291, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Trong hộp có một số bút xanh, một số bút vàng và một số bút đỏ. lấy ngẫu nhiên 1 bút từ hộp, xem màu gì rồi trả lại. Lặp lại hoạt động trên 40 lần ta được kết quả như sau: Màu bút Bút xanh Bút vàng Bút đỏ Số lần 14 10 16 Tính xác suất thực nghiệm của sự kiện không lấy được màu vàng","images":[]}', '[{"key":"A","text":"0,25"},{"key":"B","text":"0,75"},{"key":"C","text":"0,1"},{"key":"D","text":"0,9"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Trong hộp có một số bút xanh, một số bút vàng và một số bút đỏ. lấy ngẫu nhiên 1 bút từ hộp, xem màu gì rồi trả lại. Lặp lại hoạt động trên 40 lần ta được kết quả như sau: Màu bút Bút xanh Bút vàng Bút đỏ Số lần 14 10 16 Tính xác suất thực nghiệm của sự kiện không lấy được màu vàng\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số lần lấy bút là 40.\\nSố lần lấy được màu vàng là 10 Số lần không lấy được màu vàng là 40-10=30.\\nXác suất suất thực nghiệm của sự kiện không lấy được màu vàng là: 30 40 = 0,75 ần chọn là: B\\nKết luận: Đáp án đúng là C (0,1).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4538, 291, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tổng hợp kết quả xét nghiệm bệnh viêm gan ở một phòng khám trong một năm ta được bảng sau: Quý Số ca xét nghiệm Số ca dương tính I 210 II 150 III 180 9 IV 240 48 Xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính quý I” là","images":[]}', '[{"key":"A","text":"0,1"},{"key":"B","text":"0,25"},{"key":"C","text":"0,15"},{"key":"D","text":"0,125"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tổng hợp kết quả xét nghiệm bệnh viêm gan ở một phòng khám trong một năm ta được bảng sau: Quý Số ca xét nghiệm Số ca dương tính I 210 II 150 III 180 9 IV 240 48 Xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính quý I” là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số ca xét nghiệm quý I là 210.\\nSố ca dương tính là 21 ca.\\nXác suất thực nghiệm của sự kiện “một ca có kết quả dương tính quý I” là: 21 210 = 0,1 ần chọn là: A\\nKết luận: Đáp án đúng là C (0,15).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4539, 291, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":"Tổng hợp kết quả xét nghiệm bệnh viêm gan ở một phòng khám trong một năm ta được bảng sau: Quý Số ca xét nghiệm Số ca dương tính I 210 II 150 III 180 9 IV 240 48 Có bao nhiêu quý có xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính” dưới 0,1?","images":[]}', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"0"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tổng hợp kết quả xét nghiệm bệnh viêm gan ở một phòng khám trong một năm ta được bảng sau: Quý Số ca xét nghiệm Số ca dương tính I 210 II 150 III 180 9 IV 240 48 Có bao nhiêu quý có xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính” dưới 0,1?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Bước 1: Xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính” của quý I là: 21 210 = 0,1 Xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính” của quý II là: 15 200 = 0,075 Xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính” của quý III là: 9 180 = 0,05 Xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính” của quý IV là: 48 240 = 0,2 Bước 2: Ta có hai số nhỏ hơn 0,1 là 0,05 và 0,075.\\nVậy có 2 quý có xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính” dưới 0,1.\\nần chọn là: B\\nKết luận: Đáp án đúng là C (3).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4540, 291, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Tổng hợp kết quả xét nghiệm bệnh viêm gan ở một phòng khám trong một năm ta được bảng sau: Quý Số ca xét nghiệm Số ca dương tính I 210 II 150 III 180 9 IV 240 48 Xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính sau quý III tính từ đầu năm” là","images":[]}', '[{"key":"A","text":"0,05"},{"key":"B","text":"0,15"},{"key":"C","text":"1 12"},{"key":"D","text":"1 15"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Tổng hợp kết quả xét nghiệm bệnh viêm gan ở một phòng khám trong một năm ta được bảng sau: Quý Số ca xét nghiệm Số ca dương tính I 210 II 150 III 180 9 IV 240 48 Xác suất thực nghiệm của sự kiện “một ca có kết quả dương tính sau quý III tính từ đầu năm” là\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Số ca xét nghiệm sau quý III tính từ đầu năm là: 210\\n+ 150\\n+ 180 = 540.\\nSố ca dương tính sau quý III tính từ đầu năm là: 21\\n+ 15\\n+ 9 = 45.\\nXác suất thực nghiệm của sự kiện “một ca có kết quả dương tính sau quý III tính từ đầu năm” là: 45 540 = 1 12 ần chọn là: C\\nKết luận: Đáp án đúng là C (1 12).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4541, 291, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":"Kết quả kiểm tra môn Toán và Ngữ văn của một số học sinh được lựa chọn ngẫu nhiên cho ở bảng sau: Ví dụ: Số học sinh có kết quả Toán – giỏi , Ngữ văn – giỏi là 40 . Minh họa Hãy tính xác suất thực nghiệm của sự kiện một học sinh được chọn ra một cách ngẫu nhiên có kết quả: Môn Toán đạt loại giỏi","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Xác suất thực nghiệm trong một trò chơi và thí nghiệm đơn giản (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/b4dcf5d683006ca8198ad606aa08766d48a2ada7.png","width":"419","height":"124","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-xac-suat-thuc-nghiem-trong-mot-tro-choi-va-thi-nghiem-don-gian-113981.PNG"},{"id":"img-2","alt":"10+ Bài tập trắc nghiệm Xác suất thực nghiệm trong một trò chơi và thí nghiệm đơn giản (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/6d4896d5856c78c5fafeae76887f91c7edc61dec.png","width":"278","height":"81","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-xac-suat-thuc-nghiem-trong-mot-tro-choi-va-thi-nghiem-don-gian-113982.PNG"}]}', '[{"key":"A","text":"15 34"},{"key":"B","text":"4 17"},{"key":"C","text":"6 17"},{"key":"D","text":"13 34"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả kiểm tra môn Toán và Ngữ văn của một số học sinh được lựa chọn ngẫu nhiên cho ở bảng sau: Ví dụ: Số học sinh có kết quả Toán – giỏi , Ngữ văn – giỏi là 40 . Minh họa Hãy tính xác suất thực nghiệm của sự kiện một học sinh được chọn ra một cách ngẫu nhiên có kết quả: Môn Toán đạt loại giỏi\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số học sinh là tổng tất cả các số trên bảng: 170.\\nSố học sinh được loại giỏi môn Toán là 40\\n+ 20\\n+ 15 = 75 Xác suất thực nghiệm của sự kiện một học sinh được chọn ra một cách ngẫu nhiên được loại giỏi môn Toán là 75 170 = 15 34 ần chọn là: A\\nKết luận: Đáp án đúng là C (6 17).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4542, 291, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Kết quả kiểm tra môn Toán và Ngữ văn của một số học sinh được lựa chọn ngẫu nhiên cho ở bảng sau: Ví dụ: Số học sinh có kết quả Toán – giỏi , Ngữ văn – giỏi là 40 . Minh họa Hãy tính xác suất thực nghiệm của sự kiện một học sinh được chọn ra một cách ngẫu nhiên có kết quả: Loại khá trở lên ở cả hai môn","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Xác suất thực nghiệm trong một trò chơi và thí nghiệm đơn giản (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/4e73e6702af27ec2d726cd6298270d7c90a17928.png","width":"451","height":"141","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-xac-suat-thuc-nghiem-trong-mot-tro-choi-va-thi-nghiem-don-gian-113983.PNG"},{"id":"img-2","alt":"10+ Bài tập trắc nghiệm Xác suất thực nghiệm trong một trò chơi và thí nghiệm đơn giản (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/d904cb590318d6fbc928364eb08d1a9584548276.png","width":"283","height":"84","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-xac-suat-thuc-nghiem-trong-mot-tro-choi-va-thi-nghiem-don-gian-113984.PNG"}]}', '[{"key":"A","text":"9 17"},{"key":"B","text":"7 17"},{"key":"C","text":"21 34"},{"key":"D","text":"7 34"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Kết quả kiểm tra môn Toán và Ngữ văn của một số học sinh được lựa chọn ngẫu nhiên cho ở bảng sau: Ví dụ: Số học sinh có kết quả Toán – giỏi , Ngữ văn – giỏi là 40 . Minh họa Hãy tính xác suất thực nghiệm của sự kiện một học sinh được chọn ra một cách ngẫu nhiên có kết quả: Loại khá trở lên ở cả hai môn\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số học sinh là tổng tất cả các số trên bảng: 170.\\nCác học sinh được loại khá trở lên ở cả 2 môn:\\n+ Toán giỏi, Ngữ văn giỏi: 40\\n+ Toán giỏi, Ngữ văn khá: 20\\n+ Toán khá, Ngữ văn giỏi: 15\\n+ Toán khá, Ngữ văn khá: 30 Số học sinh được loại khá trở lên ở cả 2 môn là: 40+20+15+30=105 Xác suất thực nghiệm của sự kiện một học sinh được chọn ra một cách ngẫu nhiên được loại khá trở lên ở cả 2 môn là: 105 170 = 21 34 ần chọn là: C\\nKết luận: Đáp án đúng là C (21 34).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4543, 291, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Kết quả kiểm tra môn Toán và Ngữ văn của một số học sinh được lựa chọn ngẫu nhiên cho ở bảng sau: Ví dụ: Số học sinh có kết quả Toán – giỏi , Ngữ văn – giỏi là 40 . Minh họa Hãy tính xác suất thực nghiệm của sự kiện một học sinh được chọn ra một cách ngẫu nhiên có kết quả: Loại trung bình ở ít nhất một môn","images":[{"id":"img-1","alt":"10+ Bài tập trắc nghiệm Xác suất thực nghiệm trong một trò chơi và thí nghiệm đơn giản (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/9c2216bc3e3a3bd268ace3e91914818e2ca03687.png","width":"460","height":"140","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-xac-suat-thuc-nghiem-trong-mot-tro-choi-va-thi-nghiem-don-gian-113985.PNG"},{"id":"img-2","alt":"10+ Bài tập trắc nghiệm Xác suất thực nghiệm trong một trò chơi và thí nghiệm đơn giản (có đáp án) | Toán lớp 6 Cánh diều","url":"/uploads/images/crawled/94b924e911af9f0535c809dfb700a17f97d7e268.png","width":"283","height":"81","source_url":"https://vietjack.com/toan-6-canh-dieu/images/trac-nghiem-bai-4-xac-suat-thuc-nghiem-trong-mot-tro-choi-va-thi-nghiem-don-gian-113986.PNG"}]}', '[{"key":"A","text":"13 17"},{"key":"B","text":"13 34"},{"key":"C","text":"21 34"},{"key":"D","text":"1 2"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Kết quả kiểm tra môn Toán và Ngữ văn của một số học sinh được lựa chọn ngẫu nhiên cho ở bảng sau: Ví dụ: Số học sinh có kết quả Toán – giỏi , Ngữ văn – giỏi là 40 . Minh họa Hãy tính xác suất thực nghiệm của sự kiện một học sinh được chọn ra một cách ngẫu nhiên có kết quả: Loại trung bình ở ít nhất một môn\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số học sinh là 170.\\nCác học sinh được loại trung bình ở ít nhất một môn là:\\n+ Toán trung bình, Văn giỏi: 5\\n+ Toán trung bình, Văn khá: 15\\n+ Toán trung bình, Văn trung bình: 20\\n+ Văn trung bình, Toán giỏi: 15\\n+ Văn trung bình, Toán khá: 10 Số học sinh được loại trung bình ở ít nhất một môn là: 5\\n+ 15\\n+ 20\\n+ 15\\n+ 10 = 65 Xác suất thực nghiệm của sự kiện một học sinh được chọn ra một cách ngẫu nhiên có kết quả được loại trung bình ít nhất một môn: 65 170 = 13 34 ần chọn là: B\\nKết luận: Đáp án đúng là C (21 34).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4544, 291, NULL, 'MULTIPLE_CHOICE', 'HARD', 'STACK_VERTICAL', '{"text":". Nếu tung một đồng xu 22 lần liên tiếp thì, có 14 lần xuất hiện mặt N thì xác suất thực nghiệm xuất hiện mặt N bằng bao nhiêu?","images":[]}', '[{"key":"A","text":"7 11"},{"key":"B","text":"4 11"},{"key":"C","text":"4 7"},{"key":"D","text":"3 7"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Nếu tung một đồng xu 22 lần liên tiếp thì, có 14 lần xuất hiện mặt N thì xác suất thực nghiệm xuất hiện mặt N bằng bao nhiêu?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số lần gieo là 22.\\nSố lần gieo được mặt N là 14.\\nXác suất thực nghiệm xuất hiện mặt N là: 14 22 = 7 11 ần chọn là: A\\nKết luận: Đáp án đúng là C (4 7).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4545, 291, NULL, 'MULTIPLE_CHOICE', 'MEDIUM', 'STACK_VERTICAL', '{"text":". Nếu tung một đồng xu 30 lần liên tiếp có 12 lần xuất hiện mặt N thì xác suất thực nghiệm xuất hiện mặt S bằng bao nhiêu?","images":[]}', '[{"key":"A","text":"2 5"},{"key":"B","text":"1 5"},{"key":"C","text":"3 5"},{"key":"D","text":"3 4"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: . Nếu tung một đồng xu 30 lần liên tiếp có 12 lần xuất hiện mặt N thì xác suất thực nghiệm xuất hiện mặt S bằng bao nhiêu?\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số lần gieo là 30.\\nSố lần gieo được mặt S là 30 – 12 = 18.\\nXác suất thực nghiệm xuất hiện mặt S là: 18 30 = 3 5 ần chọn là: C\\nKết luận: Đáp án đúng là C (3 5).","images":[]}');
INSERT INTO QuestionBank (id, lesson_id, concept_id, question_type, difficulty, layout_template, content, choices, correct_answer, explanation) VALUES (4546, 291, NULL, 'MULTIPLE_CHOICE', 'EASY', 'STACK_VERTICAL', '{"text":"Một hộp có 5 chiếc thẻ cùng loại, mỗi thẻ được ghi một trong các số 1, 2, 3, 4, 5; hai thẻ khác nhau thì ghi số khác nhau. Rút ngẫu nhiên một thẻ rồi bỏ lại thẻ vào hộp. Sau 25 lần rút thẻ liên tiếp, hãy ghi kết quả thống kê theo mẫu sau: Lần 1 Số 3 Lần 6 Số 5 Lần 11 Lần 16 Số 2 Lần 21 Số 1 Lần 7 Lần 12 Lần 17 Lần 22 Lần 3 Lần 8 Lần 13 Lần 18 Lần 23 Lần 4 Lần 9 Số 4 Lần 14 Lần 19 Lần 24 Lần 5 Lần 10 Lần 15 Lần 20 Lần 25 Tính xác suất thực nghiệm Xuất hiện số 1","images":[]}', '[{"key":"A","text":"0,4"},{"key":"B","text":"0,14"},{"key":"C","text":"0,16"},{"key":"D","text":"0, 25"}]', 'C', '{"text":"Bước 1: Đọc kỹ yêu cầu của đề bài: Một hộp có 5 chiếc thẻ cùng loại, mỗi thẻ được ghi một trong các số 1, 2, 3, 4, 5; hai thẻ khác nhau thì ghi số khác nhau. Rút ngẫu nhiên một thẻ rồi bỏ lại thẻ vào hộp. Sau 25 lần rút thẻ liên tiếp, hãy ghi kết quả thống kê theo mẫu sau: Lần 1 Số 3 Lần 6 Số 5 Lần 11 Lần 16 Số 2 Lần 21 Số 1 Lần 7 Lần 12 Lần 17 Lần 22 Lần 3 Lần 8 Lần 13 Lần 18 Lần 23 Lần 4 Lần 9 Số 4 Lần 14 Lần 19 Lần 24 Lần 5 Lần 10 Lần 15 Lần 20 Lần 25 Tính xác suất thực nghiệm Xuất hiện số 1\\nBước 2: Phân tích dữ kiện và đối chiếu với từng phương án.\\nTrả lời: Tổng số lần rút là 25 lần.\\nSố lần xuất hiện số 1 là 4 lần.\\nXác suất thực nghiệm xuất hiện số 1 là 4 25 = 0,16 ần chọn là: C\\nKết luận: Đáp án đúng là C (0,16).","images":[]}');
